(window.GIM_TS=window.GIM_TS||{})["Niddah.5"]={"from":120,"a":[["\u0003קמוניא, ואשלג.\u0004","ואם \u0003הטבילו\u0004 את הבגד בעוד שהיה בו כתם זה (שאין אנו יודעים מה טיבו), \u0003ועשה על גביו\u0004 (על דעת שהוא טהור) \u0003טהרות,\u0004 ולאחר מכן \u0003העביר עליו,\u0004 על הכתם, את \u0003שבעה\u0004 ה\u0003סמנין\u0004 הללו, \u0003ולא עבר\u0004 (נעלם) הכתם על ידם — \u0003הרי\u0004 כתם \u0003זה\u0004 הוא \u0003צבע,\u0004 ולא דם. ולכך אותן \u0003הטהרות\u0004 שנעשו על גבי הבגד \u0003טהורות, ו\u0004את הבגד \u0003אינו צריך להטביל,\u0004 שאין בו טומאה. ואולם אם הכתם \u0003עבר\u0004 לאחר שהעבירו עליו את שבעת הסממנים הללו, \u0003או\u0004 אפילו \u0003ש\u0004לא נעלם לגמרי, אך \u0003דיהה\u0004 (התעמעם, שנחלש צבע הכתם) — \u0003הרי זה כתם\u0004 דם. \u0003ו\u0004לכך \u0003הטהרות\u0004 שהתעסק בהן על גבי הבגד \u0003טמאות, ו\u0004את הבגד \u0003צריך להטביל\u0004 שוב.","למעלה נמנו שבעת הסממנים המעבירים את הדם, ומסבירים: \u0003איזהו רוק תפל\u0004 — זה הרוק היוצא בבוקר, עם הקימה מהשינה, מפיו של \u0003כל\u0004 אדם \u0003שלא טעם כלום\u0004 כל הלילה. \u0003מי גריסין\u0004 — \u0003לעיסת גריסין של פול חלוקת נפש.\u0004 כלומר, גריס של צמח הפול שנחלק מעצמו, שיצא האוכל שבה מתוך קליפתו מעצמו, ולא בידי אדם. ונלעס בפי אדם, ולאחר מוכן הריהו מונח על הכתם. \u0003מי רגלים\u0004 — מי רגלים שהחמיצו, אחר ששהו שלושה ימים.","\u0003וצריך לכסכס\u0004 (לשפשף) את הבגד \u0003שלש פעמים לכל אחד ואחד\u0004 מהסממנים הללו. ואת שבעת הסממנים הללו צריך להעביר על הכתם, דווקא באופן זה שיועבר סממן אחר סממן בנפרד, ובסדר המנוי במשנתנו שבתחילה מעבירים רוק תפל ואחר כך מי גריסים וכן הלאה. ואולם אם \u0003העבירן שלא כסדרן, או שהעביר\u0004 את כל \u0003שבעה\u0004 ה\u0003סמנין כאחת\u0004 ולא בזה אחר זה — \u0003לא עשה ולא כלום.\u0004 שאין זו בדיקה תקפה, ואי אפשר לקבוע על פיה אם היה זה כתם דם או צבע.","שנינו במשנתנו שבעה סממנים המעבירים את הכתם, ואולם לא הוסבר במשנתנו אלא ענין שלושה מהם (רוק תפל, מי גריסים, ומי רגלים). ולענין בירור עניינו של הנתר מביאים מה ש\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: הנתר המעביר את הכתם — זה \u0003נתר אלכסנדרית, ולא נתר אנטפטרית.\u0004","ובבירור ענין ה\u0003בורית\u0004 הנזכרת במשנה, \u0003אמר רב יהודה: זה\u0004 הנקרא \u0003אהלא.\u0004 \u0003ומקשים על כך:\u0004 \u0003והתניא והרי שנויה\u0004 ברייתא\u0005]\u0006 האומרת בתוך דבריה \u0003הבורית והאהל,\u0004 והרי זה מורה כי אלה הם דברים שונים! \u0003אלא, מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003בורית\u0004 — \u0003כבריתא\u0004 \u0005[גופרית].\u0006","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 ומראים סתירה\u0005]\u0006 על הסבר זה ממה ששנינו לענין הצמחים שנאסרו לשימוש בשביעית כי \u0003הוסיפו עליהן\u0004 אף את \u0003הלביצין, והלעונין,\u0004 ו\u0003הבורית, והאהל.\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בורית\u0004 זו \u0003כבריתא, מי אית ליה\u0004 \u0005[האם יש לו]\u0006 איסור \u0003שביעית? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בהגדרת הדברים שיש בהם איסור שביעית, \u0003זה הכלל: כל שיש לו עיקר\u0004 (שורש, שממנו הוא ניזון) — \u0003יש לו\u0004 (הריהו בכלל) איסור \u0003שביעית, וכל שאין לו עיקר\u0004 — \u0003אין לו שביעית.\u0004 ואילו לכבריתא אין שורש! \u0003אלא\u0004 חוזרים לזיהוי הקודם האומר כי \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003בורית\u0004 — זה \u0003אהלא, ו\u0004באשר לשאלה שהקשינו, \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 האומרת בתוך דבריה \u0003הבורית והאהל,\u0004 והרי זה מורה כי הבורית אינה האהל — צריך לומר כי יש \u0003תרי גווני אהלא\u0004 \u0005[שני מיני אהל],\u0006 שאחד מהם נקרא גם \"בורית\", והאחר שונה מן הבורית.","ובענין ה\u0003קמוניא\u0004 הנזכרת במשנה, \u0003אמר רב יהודה:\u0004 זה הנקרא \u0003שלוף דוץ.\u0004 \u0003ו\u0004בענין ה\u0003אשלג\u0004 הנזכר במשנה, \u0003אמר שמואל: שאלתינהו לנחותי ימא\u0004 \u0005[שאלתי אותם, את יורדי הים],\u0006 מהו אשלג זה, \u0003ואמרו\u0004 לי כי \u0003אשלגא שמיה\u0004 \u0005[שמו],\u0006 \u0003ומשתכח ביני נקבי מרגניתא, ומפקי לה ברמצא דפרזלא\u0004 \u0005[ו\u0006הוא \u0005נמצא בין נקבי המרגלית, ומוציאים אותו במסמר ארוך של ברזל].\u0006","שנינו במשנתנו כי אם \u0003הטבילו\u0004 את הבגד שנמצא בו הכתם, \u0003ועשה\u0004 על גביו טהרות, ונבדק הבגד בשבעת הסממנים הללו ולא עבר הכתם — כתם זה הינו צבע, ואין כאן טומאה, והטהרות הינן טהורות, והבגד אינו צריך טבילה נוספת. ומביאים עוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003העביר עליו שבעה סמנין, ולא עבר\u0004 הכתם. ולאחר מכן הוסיף והעביר עליו \u0003צפון\u0004 (סבון), \u0003ועבר\u0004 הכתם בכך — \u0003טהרותיו טמאות.\u0004 ותוהים על כך: הרי הבדיקה הוכיחה שאין זה כתם דם.","וזה שנעלם הכתם לאחר שהעבירו עליו צפון — שהרי ה\u0003צפון צבע נמי מעבר\u0004 \u0005[גם כן מעביר]!\u0006 \u0003אלא\u0004 כך היא לשון הברייתא: \u0003העביר עליו\u0004 רק \u0003ששה סמנין, ולא עבר\u0004 בהם הכתם. ואחר כך \u0003העביר עליו צפון, ועבר\u0004 בכך הכתם — \u0003טהרותיו טמאות.\u0004 שיש מקום לומר \u0003שאם העביר\u0004 את הסממן ה\u0003שביעי מתחילה,\u0004 לפני שהעביר את הצפון — \u0003שמא עבר\u0004 \u0005[היה עובר]\u0006 הכתם בכך, שכן כתם דם הוא זה. ולכך הבגד טמא.","ועוד \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בענין זה, האומרת שאם \u0003העביר עליו שבעה סמנין, ולא עבר\u0004 בהם הכתם. ואחר כך \u0003שנאן\u0004 (חזר והעבירם שוב על הכתם), \u0003ועבר\u0004 הכתם בכך — \u0003טהרותיו טהורות,\u0004 אף שעבר הכתם על ידי שבעת הסממנים הללו, שאין זה כתם דם. שאילו היה זה דם — היה עובר בהעברת שבעת הסממנים בפעם הראשונה.","ובהסבר ברייתא זו \u0003אמר ר'\u0004 \u0003זירא: לא שנו\u0004 בברייתא שהטהרות הינן טהורות \u0003אלא\u0004 אלו \u0003הטהרות שנעשו בין\u0004 ה\u0003תכבוסת\u0004 (העברת שבעת הסממנים על הבגד) ה\u0003ראשונה\u0004 של הבגד \u0003ל\u0004בין התכבוסת ה\u0003שניה.\u0004 \u0003אבל טהרות שנעשו אחר תכבוסת שניה\u0004 — \u0003טהרותיו טמאות, שהרי\u0004 בזה שחזר והעביר על הכתם שוב את שבעת הסממנים (תכבוסת שניה), גילה דעתו ש\u0003הקפיד עליו\u0004 (שמסופק הוא עדיין שמא הרי זה כתם דם, למרות שהוא לא עבר בתכבוסת הראשונה), \u0003ו\u0004עתה (בתכבוסת השניה) ש\u0003עבר\u0004 הכתם — הרי זו ראיה שדם הוא."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא לרב אשי בקושיה על דבריו: \u0003מידי בקפידא תליא מילתא\u0004 \u0005[כלום בהקפדה\u0006 של בעלי הבגד \u0005תלוי הדבר]?\u0006 והרי מאחר שהטהרות שנעשו לאחר התכבוסת הראשונה הינן טהורות, כי הוכח כבר שאין זה דם. אף הטהרות שנעשו לאחר התכבוסת השניה לא תיטמאנה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לר' אבא בתשובה: \u0003אין\u0004 \u0005[כן],\u0006 אף בהקפדת בעלי הבגד תלוי הדבר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' חייא אומר\u0004 כי \u0003דם\u0004 של \u0003הנדה ודאי\u0004 — \u0003מעביר עליו\u0004 את \u0003שבעה\u0004 ה\u0003סמנין\u0004 הללו, \u0003ו\u0004בכך הריהו \u0003מבטלו\u0004 מלהיחשב עוד כדם, אף שלא עבר הכתם לגמרי. ומטביל את הבגד, ונטהר.","\u0003ו\u0004יש לדון בדבר זה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 נטהר הבגד, אף שלא עבר הכתם לגמרי, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003דם נדה הוא! אלמא\u0004 \u0005[נסיק\u0006 מכאן\u0005]\u0006 כי \u0003בקפידא תליא מילתא\u0004 \u0005[בהקפדה תלוי הדבר],\u0006 מאחר שאין בעל הבגד מקפיד על הכתם שנותר לאחר שכובס. \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בענייננו, \u0005גם כן]\u0006 יש לומר כי \u0003בקפידא תליא מילתא\u0004 \u0005[בהקפדה תלוי הדבר],\u0006 וכיון שבכגון זה אין אדם מקפיד, לכן שוב אינו נחשב כדם.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת כלים\u0005]:\u0006 \u0003חרסין\u0004 כגון עביט של מי רגלים \u0003שנשתמש בהן זב\u0004 לעשיית צרכיו, ונמצא איפוא \u0003שבלעו\u0004 החרסים הללו \u0003משקין\u0004 טמאים. \u0003ו\u0004לאחר מכן \u0003נפלו\u0004 החרסים הללו \u0003ל\u0004תוך \u0003אויר\u0004 (חלל) \u0003התנור, והוסק התנור\u0004 — \u0003התנור טמא.\u0004 וטעם הדבר: \u0003ש\u0004כן \u0003סוף\u0004 ה\u0003משקה\u0004 הבלוע בחרסים \u0003לצאת\u0004 מהם על ידי חום התנור, והם מטמאים את התנור.","ובפירוש דברי המשנה הללו נחלקו חכמים, ש\u0003אמר ריש לקיש: לא שנו\u0004 במשנה זו שהתנור נטמא מהחרסים רק בשעה שהוסק, \u0003אלא\u0004 כשבלועים בהם \u0003משקין קלים,\u0004 שאינם אב הטומאה, וכגון דמעתו או מי רגליו של הטמא בטומאת מת או בטומאת שרץ. שהרי גם כשהוסק התנור ויצאו המשקים הטמאים לאויר התנור, אין הם מטמאים אלא מדברי חכמים. שהרי אין משקה מטמא כלי, מלבד משקה אב הטומאה. \u0003אבל\u0004 אם היו אלה \u0003משקין חמורין,\u0004 וכגון שהם עביט מי רגלים של זב או זבה (שהריהם אב הטומאה) — \u0003טמא\u0004 התנור, \u0003אף על פי שלא הוסק התנור.\u0004 שמאחר והמשקים הבלועים בחרסים יכולים לצאת (על ידי היסק), שוב אין הם נחשבים כבלועים. ואילו \u0003ר' יוחנן אמר\u0004 כי \u0003אחד\u0004 דין \u0003משקין קלין ואחד\u0004 דין \u0003משקין חמורין, אם הוסק התנור\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נטמא התנור, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 הוסק התנור — \u0003לא\u0004 נטמא.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו במשנתנו שאם \u0003הטבילו\u0004 לבגד שנמצא בו לאחר מכן כתם, \u0003ועשה על גביו טהרות, והעביר עליו שבעה סמנין ולא עבר\u0004 הכתם — \u0003הרי זה צבע\u0004 ולא דם, \u0003ו\u0004לכך \u0003טהרותיו טהורות, ואין צריך להטביל\u0004 שוב את הבגד. הרי שדבר טמא בלוע שאינו יכול לצאת אלא על ידי גורם חיצוני כל עוד לא יצא אינו טמא, ואף בענייננו רק לכשתצא הטומאה יטמא התנור! והרי זה כשיטתי שאף המשקים הטמאים הבלועים בחרסים, כיון שאין הם יכולים לצאת אלא בהסקת התנור — אין הם מטמאים את התנור (אלא אם כן יצאו בפועל).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש לר' יוחנן בדחיית ראייתו: \u0003הנח לכתמים,\u0004 שאין להביא ראיה מהם לענין טומאת כלים, שכן כל עיקרה של טומאת כתמים אינו אלא \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולכך הקלו חכמים בזמן שאין הדם יוצא על ידי שבעה סממנים. מה שאין כן בטומאה שמן התורה.","שב ר' יוחנן והקשה עוד על ריש לקיש: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 (בברייתא שהובאה למעלה) כי אף \u0003דם הנדה ודאי\u0004 — \u0003מעביר עליו שבעה סמנין, ומבטלו,\u0004 והרי זו ראיה לשיטתי שאין הדבר הבלוע היוצא רק על ידי הדחק נחשב לטמא. ואמורים הדברים הללו אף בטומאה שמן התורה, כדם הנדה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש לר' יוחנן: אין להקשות על שיטתי מדברי ברייתא זו, שכן משובשת היא. שהרי אם \u0003רבי\u0004 (ר' יהודה הנשיא, מסדר המשנה) \u0003לא שנה\u0004 הלכה זו במשנתו, \u0003ר' חייא\u0004 (תלמידו של רבי, שדבריו מובאים בברייתא זו) \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006","ועוד שב ו\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו במשנה במסכת אהלות: \u0003רביעית דם\u0004 של מת (המטמאת בטומאת אוהל) \u0003שנבלע ב\u0004קרקע ה\u0003בית\u0004 — כל כלי \u0003ה\u0004נמצא ב\u0003בית טמא.\u0004 \u0003ואמרי לה\u0004 \u0005[ויש האומרים אותה\u0006 הלכה\u0005]\u0006 כי במקרה זה כלי \u0003ה\u0004נמצא ב\u0003בית טהור.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הדעות הללו \u0005חלוקות]\u0006 אלא \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו,\u0006 האומרת שהבית טמא\u0005]\u0006 — מדובר בה \u0003בכלים דמעיקרא\u0004 \u0005[שמתחילה],\u0006 שהיו בבית לפני שנבלע בו דם זה, וכלים אלה נטמאו בטומאת אוהל. ואילו \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו,\u0006 האומרת שהבית טהור\u0005]\u0006 — מדובר בה \u0003בכלים\u0004 שהגיעו אל הבית ל\u0003בסוף,\u0004 לאחר שנבלע הדם בקרקע הבית.","וממשיכה המשנה ואומרת כי אם רביעית דם המת \u0003נבלעה בכסות,\u0004 הרי כסות זו נבדקת: \u0003אם מתכבסת ויוצא ממנה רביעית דם\u0004 — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — הריהי \u0003טהורה.\u0004 נמצאנו למדים כי דם הבלוע שאינו יוצא בכיבוס — אינו מטמא. והרי זה כשיטתי האומרת שטומאה בלועה איננה מטמאה, אף שאפשר להוציאה על ידי הדחק!","\u0003אמר רב כהנא:\u0004 אין להביא מכאן ראיה, שכן \u0003מקולי רביעיות\u0004 דם \u0003שנו כאן,\u0004 שמדובר במשנה זו ברביעית דם תבוסה (דמו של הרוג, שיצא ממנו רביעית דם בחייו ובמותו, ואין יודעים אם רובה של רביעית דם זו יצאה ממנו בעודו בחיים, ואינה מטמאה. או שמא יצאה רובה של רביעית לאחר מותו, והריהי מטמאה). ו\u0003שאני\u0004 \u0005[שונה]\u0006 הוא דין \u0003דם תבוסה\u0004 — שאין טומאתו אלא מ\u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ובטומאה שהיא מדברי חכמים, אף ריש לקיש מודה שיש להקל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ממה ששנינו כי \u0003כל הבלוע\u0004 (שנבלע בו דבר טומאה) \u0003שאינו יכול לצאת\u0004 — הריהו \u0003טהור.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יכול לצאת\u0004 — הרי זה \u0003טמא, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא נפיק\u0004 \u0005[יצא]\u0006 עדיין. והרי זה כשיטתי!","\u0003אמר רב פפא\u0004 בדחיית ראיה זו: ב\u0003כל היכא\u0004 \u0005[היכן,\u0006 אופן\u0005]\u0006 שבו דבר הטומאה הבלוע \u0003אין יכול לצאת, ולא הקפיד עליו\u0004 הבעלים, שאין הימצאו של הדבר מפריע לו — ל\u0003דברי הכל,\u0004 ריש לקיש ור' יוחנן, הרי זה \u0003טהור.\u0004 ובכל אופן ש\u0003יכול\u0004 דבר הטומאה \u0003לצאת, והקפיד עליו\u0004 הבעלים, שמפריע לו הדבר ועומד הוא להוציאו — ל\u0003דברי הכל\u0004 הרי זה \u0003טמא.\u0004","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 ריש לקיש ור' יוחנן — הרי זה במקרה ש\u0003יכול\u0004 דבר הטומאה \u0003לצאת, ולא הקפיד עליו\u0004 הבעלים. ובזאת נחלקו: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003כיון\u0004 ש\u0003יכול\u0004 דבר הטומאה \u0003לצאת\u0004 — הריהו טמא, ו\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הקפיד עליו.\u0004 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003יכול לצאת,\u0004"],["\u0003אם הקפיד עליו\u0004 הבעלים — \u0003אין\u0004 \u0005[כן],\u0006 הריהו מטמא, ואולם \u0003אי לא\u0004 \u0005[אם אין]\u0006 הבעלים מקפיד עליו אף שיכול דבר הטומאה לצאת — \u0003לא\u0004 טמא.","שנינו במשנתנו בהגדרתו של רוק תפל, \u0003איזהו רוק תפל?\u0004 — כל שלא טעם כלום. ובענין שיעור הזמן שלא אכל, שמביאים מה ש\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: איזהו רוק תפל? \u0003כל שלא טעם כלום מבערב.\u0004 ובפירוש הדברים מביאים כי \u0003סבר\u0004 \u0005[הסביר]\u0006 \u0003רב פפא\u0004 את דברי הברייתא הזו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא למימר\u0004 \u0005[לומר]\u0006 שהריהי \u0003כ\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהכוונה היא ש\u0003לא טעם מידי באורתא\u0004 \u0005[דבר מליל\u0006 אתמול, מאמש\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מי קתני\u0004 \u0005[האם הוא,\u0006 התנא \u0005שנה]\u0006 \"כל שלא טעם \u0003בערב\"?\u0004 שמשמע הדברים הוא שלא אכל דבר למן הלילה הקודם. והרי \"כל שלא טעם \u0003מבערב\" קתני\u0004 \u0005[הוא שנה],\u0006 שבערב זה הוא לא טעם דבר, ואולם בליל אמש הוא אכל. ובאו הדברים כדי \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005],\u0006 שאין זה רוק תפל \u0003היכא דקדים ואכיל\u0004 \u0005[היכן,\u0006 כאשר \u0005הקדים\u0006 לקום משנתו קודם שעלה היום, \u0005ואכל],\u0006 ששוב אין הרוק שבפיו נחשב לרוק תפל.","ועוד בענין זה \u0003אמר רבה בר בר חנה, אמר ר'\u0004 \u0003יוחנן: איזהו רוק תפל?\u0004 — \u0003כל ש\u0004לא אכל דבר, ו\u0003עבר עליו\u0004 זמן \u0003חצות לילה, ו\u0004היה שרוי \u0003בשינה.\u0004 ומקשים: \u0003למימרא\u0004 \u0005[האם\u0006 בא \u0005לומר]\u0006 ש\u0003בשינה תליא מילתא\u0004 \u0005[תלוי הדבר]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 כי אם \u0003ישן כל היום\u0004 כולו — \u0003אין זה רוק תפל,\u0004 אף שישן. ואילו אם היה \u0003ניעור כל הלילה\u0004 כולו — \u0003הרי זה רוק תפל,\u0004 אף שלא ישן. הרי איפוא שלא השינה היא הגורמת לרוק להיתפל, אלא הלילה כשלעצמו! ומתרצים: \u0003התם\u0004 \u0005[שם\u0006 בברייתא\u0005]\u0006 אין כוונת \"ניעור כל הלילה\" שלא ישן כל הלילה שינה של ממש, ואולם היה \u0003מתנמנם,\u0004 שישן באופן חלקי, ודי בשינה חלקית שכזו כדי שיהיה הרוק תפל.","ומסבירים: \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק]\u0006 \u0003מתנמנם? אמר רב אשי: נים\u0004 \u0005[נם]\u0006 \u0003ולא נים\u0004 \u0005[נם],\u0006 \u0003תיר\u0004 \u0005[ער]\u0006 \u0003ולא תיר\u0004 \u0005[ער],\u0006 \u0003דקרו ליה\u0004 \u0005[שקוראים לו]\u0006 \u0003ועני\u0004 \u0005[ועונה],\u0006 \u0003ולא ידע לאהדורי סברא\u0004 \u0005[ואין יודע להשיב סברה],\u0006 \u0003ו\u0004אולם \u0003כי מדכרו ליה\u0004 \u0005[כאשר מזכירים לו]\u0006 את סברת הדבר — \u0003מדכר\u0004 \u0005[נזכר]\u0006 בה.","ועוד בהגדרת הרוק התפל, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: כל ש\u0003השכים\u0004 בבוקר משנתו, \u0003ושנה פרקו\u0004 בדיבור — \u0003אין זה רוק תפל,\u0004 אף שלא טעם דבר מהערב, שכן הדיבור מעביר את תפילותו של הרוק. \u0003ו\u0004שואלים: \u0003עד כמה\u0004 הוא שיעור לימודו בפה המעביר את תפילותו של הרוק? \u0003אמר רב יהודה בר שילא, אמר רב אשי, אמר ר'\u0004 \u0003אלעזר: כל שיצא\u0004 מפיו \u0003רוב דבורו\u0004 שהוא עשוי לדבר בפרק זמן \u0003של שלש שעות.\u0004","שנינו במשנתנו בהגדרת \u0003מי גריסין\u0004 המשמשים להעברת הכתם שהכוונה ל\u0003לעיסת גריסין של פול\u0004 שנחלק (שיצא האוכל שבו מתוך קליפתו מעצמו) ולאחר מכן נלעס. ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי דין זה, המצריך לעיסת הגריס, \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לריש לקיש,\u0004 שכן \u0003אמר ריש לקיש: רוק תפל צריך שיהא עם כל אחד ואחד\u0004 מששת הסממנים המעבירים את הכתם? ודוחים: אין זו ראיה, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 סיבת הדבר שצריכים ללעוס את הגריס, אינה משום תוספת רוק תפל, אלא משום ש\u0003הבלא דפומא מעלי\u0004 \u0005[הבל הפה,\u0006 חום, \u0005מועיל]\u0006 להעברת הכתם.","ומציעים עוד כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 שאמרה כי די בלעיסה של הפול, ובחום הפה הבא עם הלעיסה, היא ש\u0003לא כ\u0004שיטת \u0003ר' יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: מי גריסין\u0004 המשמש כסממן להעברת הכתם, צריך להיות \u0003רותח\u0004 (חם ביותר), שהוא הרבה מעל חום הפה, \u0003ו\u0004כן כי \u0003עובר\u0004 (קודם) \u0003שיתן לתוכו מלח.\u0004","ומבררים: \u0003מאי משמע דהאי\u0004 \u0005[מה,\u0006 מאין \u0005משתמע שזו\u0006 המלה\u0005]\u0006 \u0003\"עובר\"\u0004 — \u0003לישנא דאקדומי\u0004 \u0005[לשון הקדמה]\u0006 \u0003הוא? אמר רב נחמן בר יצחק:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וירץ אחימעץ דרך הככר ויעבר את הכושי\"\u0004 (שמואל ב יח, כג). \u0003אביי אמר\u0004 כי \u0003מהכא\u0004 \u0005[מכאן]\u0006 יש ללמוד כן, מן האמור בפגישת יעקב עם עשיו \"וישם את השפחות ואת ילדיהן ראשונה ואת לאה וילדיה אחרונים ואת רחל ואת יוסף אחרונים. \u0003והוא עבר לפניהם\"\u0004 (בראשית לג, ב—ג), \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור\u0006 שנלמד \u0005מכאן],\u0006 מן הכתוב \"עלה הפורץ לפניהם פרצו ויעבורו שער ויצאו בו \u0003ויעבר מלכם לפניהם וה' בראשם\"\u0004 (מיכה ב, יג).","בהגדרת \u0003מי רגלים\u0004 המשמשים להעברת הכתם שנינו במשנתנו שמדובר במי רגלים \u0003שהחמיצו,\u0004 ואולם לא נתברר במשנה מהו משך חימוצם של מי הרגלים. ובענין זה מביאים מה ש\u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003כמה\u0004 ימים הוא משך \u0003חימוצן\u0004 של מי רגלים המשמשים להעברת הכתם? — \u0003שלשה ימים.\u0004","ועוד בדינם של מי רגלים להעברת כתם דם, ולענין שיעורם, \u0003אמר ר'\u0004 \u0003יוחנן: כל שיעורי חכמים\u0004 שאמרו \u0003ב\u0004מי רגלים המשמשים להעברת \u0003כתמים\u0004 — \u0003צריך שיעור לשיעורן,\u0004 שאין זה ברור לגמרי במה המדובר, ולדון בדבר זה בארבע שאלות הנוגעות לסוג מי הרגלים, שכן שונים הם זה מזה ביכולת העברת הכתם: האם אלה מי רגלים של \u0003ילד\u0004 שכוחם מועט להעביר את הכתם, \u0003או\u0004 מי רגלים של \u0003זקן,\u0004 שכוחם מרובה? האם אלה מי רגלים של \u0003איש או\u0004 מי רגלים של \u0003אשה?\u0004 האם אלה מי רגלים שהיו \u0003מכוסים, א\u0004 \u0003ו\u0004מי רגלים מגולים? האם אלה מי רגלים ש\u0003בימות החמה\u0004 (קיץ), \u0003או\u0004 מי רגלים ש\u0003בימות הגשמים\u0004 (חורף)?","שנינו במשנתנו שכאשר מעבירים את שבעת הסממנים על הכתם, \u0003צריך לכסכס\u0004 (לשפשף, להוליך ולהוביל) את הסממנים על פני הכתם \u0003שלש פעמים.\u0004 ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 האם הכוונה היא שפעולת \u0003אמטויי ואתויי\u0004 \u0005[הולכה והבאה]\u0006 שתיהן נחשבות ככסכוס \u0003חד\u0004 \u0005[אחד],\u0006 ויש להוליך ולהביא שלוש פעמים. \u0003או דלמא אמטויי ואתויי\u0004 \u0005[או שמא הולכה והבאה]\u0006 נחשבות כ\u0003תרתי\u0004 \u0005[שני]\u0006 כסכוסים, ודי להוסיף עליהן עוד הולכה אחת, \u0003מאי\u0004 \u0005[מהי]\u0006 ההלכה? ומסכמים: לבעיה זו לא נמצא פתרון, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד בהגדרת דרך הבדיקה הראויה שנינו במשנתנו כי אם \u0003העבירן\u0004 את שבעת הסממנים על הבגד \u0003שלא כסדרן\u0004 הנזכר במשנה, או שהעבירם בבת אחת — הרי זו בדיקה שאינה ראויה, ואין לה כל משמעות. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הקדים\u0004 להעביר בתחילה את סדרת הסממנים ה\u0003שניים\u0004 (נתר, בורית, קמוניא ואשלג) \u0003ל\u0004סדרת הסממנים ה\u0003ראשונים\u0004 (רוק תפל, מי גריסים ומי רגלים), \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 האומרת כי ה\u0003שניים\u0004 — \u0003עלו\u0004 (הועילו) \u0003לו,\u0004 ואילו \u0003ראשונים\u0004 — \u0003לא עלו לו.\u0004 \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 האומרת כי \u0003ראשונים\u0004 — \u0003עלו לו,\u0004 ואילו \u0003שניים\u0004 — \u0003לא עלו לו.\u0004","\u0003אמר אביי:\u0004 לא נחלקו הברייתות, ו\u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 סבורות כי סדרת הסממנים שהועברו בתחילה — אינה נחשבת, ואילו סדרת הסממנים שלאחר מכן נחשבת. ולכך אמרה הברייתא שהובאה בתחילה כי \u0003שניים עלו לו, ולא ראשונים.\u0004 ואף הברייתא שהובאה לאחר מכן שאמרה כי ראשונים עלו לו ושניים לא עלו, סבורה כן, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"ראשונים\"\u0004 — אלה הסממנים הראויים להיות \u0003ראשונים לכסדרן, ו\u0004אילו עתה הריהם \u0003שניים להעברתן.\u0004","\u0003כל אשה שיש לה וסת\u0004 שאינה תלויה בזמן אלא בתחושה גופנית \u0003דיה שעתה,\u0004 שאין היא מטמאה את הטהרות אלא משעה שיארע לה הדבר. \u0003ו\u0004מפרטים, \u0003אלו הן הוסתות\u0004 מסוג זה: זו שקודם לראיית הדם הריהי \u0003מפהקת, ו\u0004כן זו ה\u0003מעטשת, ו\u0004כן זו ש\u0003חוששת\u0004 (חשה כאב) \u0003בפי\u0004 (כנגד) \u0003כריסה, ו\u0004בדומה לכך זו שחשה כאב \u0003בשפולי מעיה\u0004 (בבית הרחם), \u0003ו\u0004כן זו ש\u0003שופעת\u0004 דם, \u0003ו\u0004זו ש\u0003כמין צמרמורות\u0004 (חום ורעידות) \u0003אוחזין אותה, וכן\u0004 כל תחושות \u0003כיוצא בהן\u0004 שחשה האשה לפני שרואה דם. \u0003ו\u0004ב\u0003כל\u0004 אחת מהתופעות הגופניות הללו \u0003שקבעה לה\u0004 (שאירעו לה כן) \u0003שלשה פעמים\u0004 רצופות, ולאחר מכן ראתה דם — \u0003הרי זה\u0004 נקבע כסימן ל\u0003וסת.\u0004 ומעתה, אם חוותה שוב אותה תופעה גופנית ולאחר מכן ראתה דם — דיה שעתה לענין טומאת הטהרות שנגעה בהן.","שנינו במשנתנו שכל אשה שיש לה וסת דיה שעתה לענין טומאת הטהרות שנגעה בהן, ותוהים: הרי כבר \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 זאת \u0005פעם אחת],\u0006 במשנה בתחילת מסכתנו כי \u0003כל אשה שיש לה וסת\u0004 — \u0003דיה שעתה!\u0004 ומשיבים: יש צורך לשוב ולשנות הלכה זו, שכן \u0003התם\u0004 \u0005[שם,\u0006 במשנה שבתחילת המסכת\u0005]\u0006 — מדובר \u0003בוסתות דיומי\u0004 \u0005[של ימים],\u0006 במי שרואה דם בזמנים קבועים, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005]\u0006 — מדובר \u0003בוסתות דגופא\u0004 \u0005[של הגוף],\u0006","\u0003כדקתני\u0004 \u0005[כפי שהוא\u0006 התנא במשנתנו \u0005שונה\u0006 בה\u0005],\u0006 \u0003אלו הן וסתות?\u0004 — \u0003היתה מפהקת, מעטשת, וחוששת בפי כריסה, ובשפולי מעיה, ושופעת,\u0004 שכל אלה הריהם וסתות הגוף.","ושואלים: שנינו בכלל אלה את האשה ש\u0003שופעת\u0004 דם, ומה מקום יש לקבוע בה וסת, ו\u0003הא שפעה ואזלא\u0004 \u0005[הרי\u0006 היא \u0005שופעת והולכת,\u0006 ממשיכה\u0005]\u0006 ואין זה סימן מוקדם ולא הוסת עצמה! \u0003אמר עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עלאי\u0004 בתשובה:"],["אין הכוונה בזו השופעת דם נדה כל העת, אלא \u0003ב\u0004זו ה\u0003שופעת דם טמא\u0004 (דם נדות) \u0003מתוך דם טהור.\u0004 שרגילה שקודם לראיית דם טמא הריהי רואה דם טהור (כעין דם שצבעו אינו אדום), ולאחריו היא רואה דם טמא. ומעתה נקבעה לה וסת הגוף באופן זה, לענין שדיה שעתה לטומאת טהרות שנגעה בהן לפני כן.","\u0003ו\u0004עוד שנינו במשנתנו בכלל וסתות הגוף זו ש\u0003כמין צמרמורות\u0004 אוחזות אותה, והוסיפה המשנה ואמרה \u0003\"וכן כיוצא בהן\",\u0004 ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 באה לשון זו, שאף הוא בכלל הקובעים וסת הגוף? \u0003אמר רבה בר עולא\u0004 בתשובה: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003אשה שראשה כבד עליה, ואבריה כבדים עליה, ורותתת\u0004 (רועדת), \u0003וגוסה\u0004 (משהקת).","ובענין דברי רבה בר עולא אלה מביאים מה ש\u0003אמר רב הונא בר חייא, אמר שמואל: הרי אמרו\u0004 חכמים כי \u0003ל\u0004צורך קביעת וסת \u0003ימים\u0004 — די ב\u0003שנים,\u0004 שאם ראתה פעם אחת בתאריך מסויים או בהפרש זמן מסויים מראייתה הקודמת, וחזרה וראתה שוב בזמן זה, נקבעה לה בכך וסת ימים. ואילו \u0003ל\u0004ענין \u0003וסתות\u0004 הגוף — די בראיה \u0003אחת.\u0004 ואולם \u0003למה\u0004 (לאותן תופעות) \u0003שלא מנו\u0004 אותן \u0003חכמים\u0004 בכלל הדברים במשנתנו שעל פיהן נקבעת וסת הגוף — יש צורך ב\u0003שלשה\u0004 ראיות, כדי לקבוע על פיהן וסת הגוף.","ויש לברר את הדברים: לשון זו \u0003\"למה שלא מנו חכמים\",\u0004 \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 היא באה? \u0003אמר רב יוסף: לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את זו ש\u0003ראשה כבד עליה, ואבריה כבדין עליה, ורותתת, וגוסה,\u0004 וכאמור בדברי רבה בר עולא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בתמיהה: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]?\u0006 והלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא\u0004 האומרת \"וכן כיוצא בהן\". \u0003דהא\u0004 \u0005[שהרי]\u0006 בא ו\u0003פרשה רבה בר עולא\u0004 שכוונתה לתופעות אלה. \u0003אלא אמר אביי\u0004 הלשון \"למה שלא שנו חכמים\" באה \u0003לאתויי\u0004 \u0005[לרבות]\u0006 את זו ש\u0003אכלה שום ו\u0004לאחר מכן \u0003ראתה\u0004 דם. \u0003ו\u0004כן זו ש\u0003אכלה בצלים וראתה,\u0004 או זו ש\u0003כססה פלפלים וראתה.\u0004 שאם אירע לה כן שלוש פעמים, קבעה וסת הגוף בכך.","\u0003אמר רב יוסף: לא שמיע לי הא שמעתא\u0004 \u0005[לא שמעתי הלכה זו]\u0006 שאמר שמואל כי לוסת ימים יש צורך בשתי ראיות ולוסת הגוף די באחת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: והלא \u0003את אמריתה ניהלן, ואהא אמריתה ניהלן\u0004 \u0005[אתה\u0006 עצמך \u0005אמרת לנו\u0006 אותה, \u0005ועל זה אמרת לנו],\u0006 על המשנה האומרת כי האשה ש\u0003היתה למודה\u0004 (רגילה) \u0003להיות רואה\u0004 דם ב\u0003יום חמשה עשר\u0004 בחודש, \u0003ושינתה\u0004 (והשתנה נוהג גופה) והריהי רואה דם \u0003ליום עשרים\u0004 בחודש, מה דינה בחודש הבא? — הרי יום \u0003זה\u0004 (יום חמישה עשר בחודש הבא), שהוא יום וסתה, \u0003ו\u0004יום \u0003זה\u0004 (יום עשרים לחודש), שהוא יום שראתה בו בחודש הקודם, \u0003אסורין\u0004 בתשמיש, שמא קבעה וסת ביום העשרים. ואולם אם השתנה זמן ראיית הדם \u0003שלש פעמים\u0004 רצופות \u0003ליום עשרים\u0004 בחודש — \u0003הותר יום חמשה עשר\u0004 בחודש בתשמיש, שמעתה שוב אין מקום לחשש שתראה ביום זה. \u0003ו\u0004מכאן והלאה הריהי \u0003קבעה לה\u0004 את \u0003יום עשרים\u0004 בחודש כיום וסתה. \u0003שאין אשה קובעת לה וסת עד שתקבענה שלש פעמים.\u0004","\u0003ואמרת לן עלה\u0004 \u0005[לנו עליה,\u0006 על משנה זו\u0005]\u0006 מה ש\u0003אמר רב יהודה, אמר שמואל:\u0004 משנה \u0003זו\u0004 הריהי כ\u0003דברי רבן גמליאל בר\u0004 \u0005[בן]\u0006 \u0003רבי שאמר משום\u0004 \u0005[בשם]\u0006 \u0003רבן שמעון בן גמליאל\u0004 שאין קביעת וסת אלא כשראתה האשה כן שלוש פעמים. \u0003אבל חכמים\u0004 חלוקים בדבר, ו\u0003אומרים\u0004 כי אף אם \u0003ראתה\u0004 פעם אחת — קבעה לה בכך וסת, שכן לקביעת וסת היא \u0003אינה צריכה לא לשנות\u0004 (לראות פעם שניה), \u0003ולא לשלש\u0004 (לראות פעם שלישית).","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 \u0003לך\u0004 בשאלה: כיון שאין היא צריכה \u0003לשנות אמרת לן\u0004 \u0005[לנו],\u0006 מעתה שאין היא צריכה \u0003לשלש מיבעיא\u0004 \u0005[נצרך]\u0006 לומר? \u0003ואמרת לן\u0004 \u0005[לנו]\u0006 בתשובה כי מה שאמרו חכמים שאין היא צריכה \u0003לשנות\u0004 — מדובר \u0003בוסתות\u0004 הגוף, שדי בראיה אחת כדי לקבוע וסת הגוף. ומה שאמרו חכמים כי אין היא צריכה \u0003לשלש\u0004 — המדובר \u0003ב\u0004וסתות \u0003ימים,\u0004 הנקבעות בשתי ראיות.","ושואלים: מדוע אמר שמואל כי דברי משנה זו הריהם כדברי רבן גמליאל בר רבי שאמר בשם רבן שמעון בן גמליאל, \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 בקצרה כי \u0003\"זו דברי רבן שמעון בן גמליאל\"!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006ב\u0005זה הוא משמיע לנו]\u0006 \u0003שמואל:\u0004 ש\u0003רבן גמליאל ברבי\u0004 (בנו של רבי) — \u0003כרבן שמעון בן גמליאל סבירא ליה\u0004 \u0005[הריהו סבור].\u0006","האשה ש\u0003היתה למודה\u0004 (רגילה) \u0003להיות רואה\u0004 דם \u0003בתחלת הוסתות\u0004 שבגופה (שהריהי רואה בתחילת תופעה גופנית כפיהוק והתעטשות ושאר תופעות וסת הגוף), אף שראתה דם לא בתחילת תופעת הגוף אלא לאחר מכן — \u0003כל הטהרות שעשתה בתוך הוסתות\u0004 למן תחילת הוסת, הריהן \u0003טמאות.\u0004 שכן הוחזקה זו לראות בתחילת הוסת. ואם היתה רגילה לראות \u0003בסוף הוסתות\u0004 (שהריהי רואה דם רק לאחר זמן מסוים של תופעה גופנית מסויימת כפיהוק או כהתעטשות וכיוצא באלה — \u0003כל הטהרות שעשתה בתוך הוסתות\u0004 הריהן \u0003טהורות.\u0004 שכן הוחזקה לראות רק בסוף הוסת.","ר' \u0003יוסי אומר: אף ימים\u0004 מסויימים \u0003ושעות\u0004 מסויימות קובעים ל\u0003וסתות.\u0004 ומסביר: כיצד? \u0003היתה למודה להיות רואה\u0004 ביום מסויים בחודש בשעה שהיא \u0003עם הנץ החמה —\u0004 \u0003אינה אסורה\u0004 בתשמיש עם בעלה ביום הוסת הקבוע לה, \u0003אלא\u0004 באותה שעה שהיא \u0003עם הנץ החמה,\u0004 ואולם בלילה (עד הנץ החמה), וכן ביום משעבר הנץ החמה אם לא ראתה — הריהי מותרת בתשמיש. \u0003ר' יהודה אומר:\u0004 משעבר הנץ החמה ולא ראתה — \u0003כל היום שלה,\u0004 ומותרת בתשמיש וכדעת ר' יוסי, ואולם בלילה הקודם אסורה, ושלא כדעת ר' יוסי.","שנינו במשנתנו כי נחלקו ר' יוסי ור' יהודה בדינה של האשה הרגילה לראות ביום הוסת הקבוע שלה עם הנץ החמה. ובענין זה עוד \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003כיצד\u0004 (באיזה אופן) \u0003אמר ר'\u0004 \u0003יוסי\u0004 את שיטתו ש\u0003ימים\u0004 מסויימים \u0003ושעות\u0004 מסויימות קובעים ל\u0003וסתות?\u0004 — \u0003היתה למודה\u0004 (רגילה) \u0003להיות רואה מיום עשרים\u0004 בחודש \u0003ליום עשרים\u0004 בחודש, \u0003ו\u0004ביום זה הריהי רגילה לראות \u0003משש שעות\u0004 (השעה השישית) \u0003לשש שעות\u0004 ביום זה בחודש הבא. כש\u0003הגיע יום עשרים\u0004 בחודש \u0003ו\u0004אף ש\u0003לא ראתה\u0004 — הריהי \u0003אסורה לשמש\u0004 עם בעלה \u0003כל שש שעות ראשונות,\u0004 אלו \u0003דברי ר'\u0004 \u0003יהודה.\u0004 \u0003ור' יוסי מתיר\u0004 לה לשמש \u0003עד שש שעות, וחוששת\u0004 (ואסורה לשמש מפני החשש) שתראה \u0003בשש שעות.\u0004","מש \u0003עברו שש שעות\u0004 ביום זה \u0003ולא ראתה\u0004 — הריהי \u0003אסורה לשמש כל היום כולו,\u0004 אלו הם \u0003דברי ר'\u0004 \u0003יהודה.\u0004 \u0003ו\u0004אילו \u0003ר' יוסי מתיר\u0004 באופן זה לשמש \u0003מן\u0004 זמן \u0003המנחה\u0004 (מתחילת השעה השביעית) \u0003ולמעלה\u0004 (והלאה).","שנינו במשנתנו כי לדעת ר' יהודה במקרה ש\u0003היתה למודה\u0004 לראות בזמן הנץ החמה ביום וסתה, כל היום (משעבר הנץ החמה) הריהי מותרת לשמש עם בעלה, ואולם בלילה הקודם הריהי אסורה מלשמש. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 האומרת כי \u0003ר' יהודה אומר\u0004 ש\u0003כל הלילה שלה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האומרת שהריהי מותרת בלילה — מדברת במי ש\u0003רגילה לראות בתחלת יממא\u0004 \u0005[היום].\u0006 \u0003ו\u0004אילו \u0003הא\u0004 \u0005[\u0006משנתנו \u0005זו]\u0006 האומרת שהריהי אסורה בלילה — מדברת במי ש\u0003רגילה לראות בסוף ליליא\u0004 \u0005[הלילה].\u0006","ומביאים עוד מדברי ר' יהודה בענין זה, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 האומרת כי ר' יהודה אוסרה לפני וסתה, ומתירה לאחר וסתה. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 האומרת כי ר' יהודה \u0003אוסרה לאחר וסתה, ומתירה לפני וסתה.\u0004","\u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האומרת שלדעת ר' יהודה הריהי אסורה לפני וסתה — מדברת באשה ש\u0003רגילה למחזי\u0004 \u0005[לראות]\u0006 \u0003בסוף ליליא\u0004 \u0005[הלילה].\u0006 ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האומרת שהריהי אסורה בסוף וסתה — מדברת בזו ש\u0003רגילה למחזי\u0004 \u0005[לראות]\u0006 \u0003בתחלת יממא\u0004 \u0005[היום].\u0006","\u0003אמר רבא: הלכה כר' יהודה\u0004 שאסורה כל עונתה. \u0003ו\u0004תוהים: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב \u0003\"והזרתם את בני ישראל מטומאתם\"\u0004 (ויקרא טו, לא) — \u0003מכאן,\u0004 מכתוב זה \u0003אמר ר'\u0004 \u0003ירמיה,\u0004 למדים אנו \u0003אזהרה לבני ישראל שיפרשו מנשותיהן סמוך לוסתן.\u0004","\u0003וכמה? אמר רבא: עונה.\u0004 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה בדברי רבא הללו ל\u0003עונה אחריתי\u0004 \u0005[אחרת,\u0006 נוספת\u0005],\u0006 שיש לפרוש מן האשה אף בעונה הסמוכה לוסתה? ודוחים: \u0003לא\u0004 זו הכוונה, אלא לומר שחייבים לפרוש ב\u0003אותה עונה.\u0004","ושואלים: \u0003ותרתי\u0004 \u0005[ושתי\u0006 פעמים\u0005]\u0006 שפסק רבא שאין חייבים לפרוש אלא עונה אחת בלבד, \u0003למה לי?\u0004 ומשיבים: \u0003צריכא\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006 להיאמר. \u0003דאי אשמועינן הא\u0004 \u0005[ש\u0006כן \u0005אם היה משמיע לנו\u0006 רבא רק את \u0005זה,\u0006 שהלכה כדברי ר' יהודה שבמשנתנו\u0005]\u0006 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003ל\u0004ענין \u0003טהרות\u0004 שאסורה לעסוק באותה עונה בטהרות \u0003אבל ל\u0004ענין תשמיש עם \u0003בעלה\u0004 — \u0003לא\u0004 תיאסר אלא בשעת הוסת (וכדעת ר' יוסי), ולא בכל עונת הוסת (כדעת ר' יהודה), לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 רבא \u0005משמיע לנו].\u0006 שהלכה כר' יהודה אף לענין תשמיש עם בעלה.","\u0003ואי מההיא\u0004 \u0005[ואם משם,\u0006 מדין פרישה סמוך לוסת\u0005]\u0006 בלבד היה משמיע לנו רבא שהכוונה לעונה אחת — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי משמעות הדברים \u0003\"סמוך לוסתה\"\u0004 היא \u0003עונה אחריתי\u0004 \u0005[אחרת,\u0006 נוספת\u0005],\u0006 שלפני עונת הוסת. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 רבא \u0005משמיע לנו]\u0006 שהכוונה ל\u0003אותה עונה\u0004 בלבד.","\u0003היתה למודה להיות רואה\u0004 דם ב\u0003יום חמשה עשר\u0004 בחודש, \u0003ושינתה\u0004 (והשתנה נוהגה) \u0003להיות רואה ליום עשרים\u0004 בחודש, מה דינה בחודש הבא? — הרי יום \u0003זה\u0004 (יום חמישה עשר בחודש הבא), שהוא יום וסתה, \u0003ו\u0004יום \u0003זה\u0004 (יום עשרים לחודש), שהוא יום שראתה בו בחודש הקודם, אם לא ראתה ביום חמישה עשר שבחודש הבא, \u0003אסורין\u0004 בתשמיש. וכן אם \u0003שינתה\u0004 (השתנה מנהגה) \u0003פעמים,\u0004 שראתה שתי פעמים בזה אחר זה \u0003ליום עשרים\u0004 בחודש — \u0003זה,\u0004 יום החמישה עשר, \u0003וזה,\u0004 יום העשרים, \u0003אסורין\u0004 שהריהי חוששת לשני הימים הללו.","ואולם אם השתנה זמן ראיית הדם \u0003שלש פעמים\u0004 רצופות \u0003ליום עשרים\u0004 בחודש — \u0003הותר\u0004 יום \u0003חמשה עשר\u0004 בחודש בתשמיש, שמעתה שוב אין לחשוש שתראה ביום זה. ונעקרה הוסת מיום זה, \u0003ו\u0004מכאן והלאה לחודשים הבאים הריהי \u0003קבעה לה\u0004 את \u0003יום עשרים\u0004 בחודש כיום וסתה. \u0003שאין אשה קובעת לה וסת\u0004 \u0003עד שתקבענה שלש פעמים.\u0004 \u0003ו\u0004כן היא \u0003אינה מטהרת\u0004 (להיות מותרת בתשמיש) \u0003מן הוסת\u0004 הקבועה שלה, אם החלה לראות בזמן אחר מזה הקבוע לה \u0003עד שתעקר ממנה שלש פעמים.\u0004"],["שנינו במשנתנו דינה של זו שהיה לה וסת ביום קבוע בחודש, והשתנה הדבר וראתה ביום אחר. ובענין זה \u0003איתמר\u0004 \u0005[נאמר]:\u0006 מי ש\u0003ראתה\u0004 דם ב\u0003יום חמשה עשר לחדש זה, ו\u0004לאחר מכן ראתה דם ב\u0003יום ששה עשר לחדש זה\u0004 הבא אחריו, \u0003ו\u0004שוב ראתה דם ב\u0003יום שבעה עשר לחדש זה\u0004 שלאחריו. \u0003רב אמר: קבעה לה\u0004 אשה זו בכך \u0003וסת לדילוג\u0004 של יום בכל חודש, ומכאן והלאה יהיה יום וסתה בכל חודש יום נוסף על החודש הקודם (בחודש הרביעי — יום שמונה עשר בו, ובחודש החמישי — ביום תשעה עשר בו, וכן הלאה). \u0003ו\u0004אילו \u0003שמואל אמר:\u0004 אין בשלוש הפעמים הללו כדי לקבוע לה וסת, אלא \u0003עד שתשלש בדילוג,\u0004 שתראה אף בחודש הרביעי בדילוג של יום אחד (ביום שמונה עשר בו). דם בדילוג יום אחד לפי שהראייה שראתה בחודש הראשון, בט\"ו בו, לא היתה בדילוג.","ומציעים: \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי \u0003רב ושמואל בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רבי ורבן שמעון בן גמליאל קמיפלגי\u0004 \u0005[הם חולקים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 אשה ש\u0003ניסת\u0004 (נישאה) \u0003ל\u0004בעל \u0003ראשון, ומת\u0004 בעלה זה. ולאחר מכן עמדה ונישאה \u0003ל\u0004בעל \u0003שני, ו\u0004אף הוא \u0003מת\u0004 — \u0003ל\u0004בעל \u0003שלישי\u0004 שוב \u0003לא תנשא,\u0004 שהריהי בחזקת \"אשה קטלנית\" (שבעליה מתים על ידה), אלו \u0003דברי רבי.\u0004 \u0003רבן שמעון בן גמליאל אומר:\u0004 \u0003ל\u0004בעל \u0003שלישי\u0004 רשאית היא ש\u0003תנשא,\u0004 שכן בפטירת שני בעלים עדיין אין היא בחזקת זו שבעליה מתים על ידה, ואולם \u0003ל\u0004בעל \u0003רביעי לא תנשא.\u0004 ומעתה יש לומר כי רב סבור כשיטת רבי, ולכך די בשתי פעמים של דילוג יום אחד כדי לקבוע על ידם את וסתה כוסת הדילוג. ואילו שמואל סבור כרבן שמעון בן גמליאל, ולכך יש צורך בשלוש פעמים של דילוג כדי לקבוע וסת.","ודוחים: לא, אפשר לומר \u0003דכולי עלמא\u0004 \u0005[ש\u0006דעת \u0005הכל,\u0006 שמואל ואף רב\u0005]\u0006 היא \u0003כ\u0004שיטתו של \u0003רבן שמעון בן גמליאל,\u0004 שאין חזקה נוצרת אלא לאחר שלוש פעמים, שכך היא הלכה בכלל דיני התורה, וכן הוא גם לענין קביעת וסת הדילוג. \u0003ו\u0004אולם \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן,\u0006 בזו הרואה בדילוגים, \u0005בזה הם חולקים],\u0006 ש\u0003רב סבר\u0004 \u0005[סבור]\u0006 כי אף מה שראתה ב\u0003חמשה עשר\u0004 בחודש הראשון, גם הוא \u0003ממנינא\u0004 \u0005[מן המנין],\u0006 ולכך ישנן כאן שלוש ראיות שעל פיהן נקבע דינה של זו. \u0003ו\u0004אילו \u0003שמואל סבר\u0004 \u0005[סבור]\u0006 כי \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003בדילוג\u0004 יום מהחודש שקדם לו, \u0003חזיתיה\u0004 \u0005[ראתהו]\u0006 את הדם בחמישה עשר בחודש הראשון, לכך \u0003לאו ממנינא\u0004 \u0005[לא מהמנין]\u0006 \u0003הוא,\u0004 ואין לה אלא שתי ראיות של דילוג, ולכך נזקקת היא לראיית דילוג נוספת בחודש הרביעי, כדי לקבוע לה וסת הדילוג.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 שמואל לרב ממה ששנינו: מי ש\u0003היתה למודה להיות רואה\u0004 בכל חודש ב\u0003יום חמשה עשר\u0004 בו, \u0003ושינתה\u0004 חודש אחד וראתה \u0003ליום ששה עשר\u0004 בחודש, שדילגה בזמן ראייתה יום אחד — \u0003זה וזה\u0004 (הן יום חמישה עשר והן יום ששה עשר בחודש) \u0003אסורין\u0004 להבא בתשמיש עם בעלה. ואם \u0003שינתה\u0004 בפעם הבאה וראתה \u0003ליום שבעה עשר\u0004 בו, והרי זו דילגה פעמיים בראיית יום אחד — מכאן ואילך \u0003הותר\u0004 בתשמיש יום \u0003ששה עשר\u0004 בחודש (שאין לחשוש לו שוב להבא, שהרי ראתה עתה ביום שבעה עשר ולא ביום ששה עשר), \u0003ו\u0004אולם עדיין \u0003נאסר\u0004 בתשמיש יום \u0003חמשה עשר\u0004 (שכן הוא טרם נעקר מקביעותו), \u0003ו\u0004כן נאסר יום \u0003שבעה עשר\u0004 להבא, שהרי ראתה בתאריך זה בחודש).","ואם עמדה ו\u0003שינתה\u0004 בפעם הבאה וראתה \u0003ליום שמונה עשר\u0004 בחודש, והרי זו איפוא דילגה שלוש פעמים בראיית יום אחד — \u0003הותרו כולן,\u0004 ואף יום חמישה עשר שכן ראתה שלוש פעמים שלא ביום זה, וכן אין חוששים ליום שבעה עשר (שהרי עתה ראתה ביום שמונה עשר). ומעתה קבעה לה וסת דילוגים ליום אחד, \u0003ו\u0004לכך \u0003אין אסור\u0004 להבא \u0003אלא מ\u0004יום \u0003שמונה עשר ואילך\u0004 (הוא יום תשעה עשר בחודש הבא, ויום עשרים בחודש שלאחריו וכן הלאה). והרי זה איפוא \u0003קשיא\u0004 \u0005[קושיה]\u0006 \u0003ל\u0004שיטתו של \u0003רב\u0004 הסבור שדי בשני דילוגים כדי לקבוע וסת דילוגים! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך רב\u0004 בתשובה כי במי שהיא \u0003למודה\u0004 לראות, שיש לה וסת קבוע (כגון זו שהיה לה יום וסת קבוע ביום חמישה עשר בחודש) \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר, שבאשה כזו אין הראייה הראשונה נחשבת (שהרי זה יום וסתה הקבוע) להצטרף עם שתי הראיות (שבאו בדילוגים) כדי לקבוע על פיהן וסת דילוגים.","ותוהים על עצם הקושיה שהקשינו על רב: \u0003ודקארי לה, מאי קארי לה\u0004 \u0005[ומי שהקשה אותה,\u0006 שמואל שהקשה כן לרב, על \u0005מה הקשה אותה],\u0006 שהרי ברור כי זו שיש לה יום וסת קבוע, אין לצרף את אותו היום לקביעת וסת דילוגים? ומסבירים: לדעת שמואל דין זה במי שהיתה \u0003למודה\u0004 לראות ביום קבוע בחודש (כגון בחמישה עשר בו) \u0003אצטריכא ליה\u0004 \u0005[נצרך לו]\u0006 לתנא להשמיענו, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]\u0006 כי \u0003כיון\u0004 שאשה זו \u0003למודה\u0004 לראות בחמישה עשר בחודש, \u0003ועקרתיה\u0004 \u0005[ועקרתו]\u0006 ליום שבעה עשר, שהרי שינתה ראייתה ליום אחר — מעתה נאמר כי \u0003בתרי זימני עקרה ליה\u0004 \u0005[בשתי פעמים,\u0006 ראיות בלבד \u0005היא עוקרת את אותו\u0006 יום\u0005],\u0006 ולכך תהיה מותרת להבא לשמש ביום חמישה עשר בחודש, ואין צורך שתראה עוד פעם — משום כך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאין וסת קבועה נעקרת אלא לאחר שלוש פעמים של ראייה ביום אחר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת שמואל ממה ששנינו: אשה ש\u0003ראתה\u0004 ב\u0003יום עשרים ואחד בחדש זה,\u0004 ולאחר מכן ראתה ב\u0003יום עשרים ושנים בחדש זה\u0004 שלאחריו, ולאחר מכן ראתה ב\u0003יום עשרים ושלשה בחדש זה\u0004 שלאחריו — \u0003קבעה לה\u0004 בכך \u0003וסת\u0004 דילוגי יום אחד. ואולם אם בפעם השלישית \u0003סירגה\u0004 (קיפצה) על פני יום, וראתה \u0003ליום עשרים וארבעה\u0004 בו, שהוא דילוג של יומיים על פני החודש הקודם — \u0003לא קבעה לה וסת\u0004 דילוגים, שהרי אין דילוג זה כדילוגים הקודמים. ומעתה הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003שמואל\u0004 האומר כי יש צורך בשלושה דילוגים, ואילו בברייתא נאמר במפורש שאם היו הדילוגים שווים, בני יום אחד, די בשני דילוגים לקביעת וסת!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך שמואל\u0004 בהסבר הדברים כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בברייתא זו \u0005במה אנו עוסקים]\u0006 — לא במי שראתה פעם ראשונה ביום עשרים בחודש זה (ולאחר מכן ראתה בדילוגים של יום אחד), אלא במי שהיה לה יום וסת קבוע, ו\u0003כגון\u0004 אשה זו ש\u0003רגילה\u0004 היא \u0003למחזי\u0004 \u0005[לראות]\u0006 \u0003ביום עשרים\u0004 בחודש, \u0003ושינתה\u0004 וראתה \u0003ליום עשרים ואחד\u0004 בחודש, ולאחר מכן שינתה וראתה בחודש הבא ביום עשרים ושנים בו, וכן בחודש שלאחריו ראתה בעשרים ושלושה בו, והרי אלה איפוא שלושה דילוגים, ולכך קבעה בהם וסת דילוגים. וכשיטתי שנדרשים אנו לשלושה דילוגים לשם קביעת וסת דילוגים. ומוסיפים: לשון הברייתא \u0003דיקא נמי\u0004 \u0005[מדוקדק גם כן]\u0006 כהעמדה זו של שמואל, \u0003דשבקינן\u0004 \u0005[ש\u0006כן \u0005עוזבים אנו]\u0006 בברייתא \u0003ליום עשרים, ונקט\u0004 \u0005[ואחז]\u0006 התנא \u0003ליום עשרים ואחד,\u0004 שהרי ראוי היה שיאמר התנא \"ראתה יום עשרים...\", במקום \"ראתה יום עשרים ואחד...\" — ומתוך שלא שנה כן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שמדובר במי שיש לה יום וסת קבוע לראיית עשרים בחודש, ועמדה ושינתה לראות ביום עשרים ואחד בחודש.","שנינו במשנתנו \u0003שאין האשה קובעת לה וסת עד שתקבענה\u0004 שלוש פעמים. ובהסבר הדברים הללו \u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא למקבעה\u0004 \u0005[ל\u0006ענין \u0005קביעת\u0006 וסת\u0005],\u0006 שמעתה והלאה יום זה הוא יום וסתה הקבוע. \u0003אבל למיחש\u0004 \u0005[ל\u0006ענין \u0005לחשוש]\u0006 \u0003לה\u0004 שמא תראה בפעם הבאה שוב ביום זה שראתה בו עתה (אף שרק פעם אחת ראתה בו) — אף \u0003בחדא זימנא חיישא\u0004 \u0005[בפעם אחת חוששת].\u0006","ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 רב פפא \u0005משמיע לנו\u0006 בדבריו\u0005],\u0006 והלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו במי ש\u0003היתה למודה להיות רואה\u0004 ב\u0003יום חמשה עשר\u0004 בחודש, \u0003ושינתה\u0004 וראתה \u0003ליום עשרים\u0004 בחודש — \u0003זה וזה אסורין,\u0004 שאסורה לשמש עם בעלה בחודש הבא גם ביום וסתה הקבוע (חמישה עשר בחודש), וגם באותו תאריך (עשרים בחודש) שראתה בו פעם אחת!","ומשיבים: נצרך רב פפא להשמיענו כן, כי \u0003אי מהתם\u0004 \u0005[אם\u0006 נרצה ללמוד כן \u0005משם,\u0006 ממשנתנו בלבד\u0005] —\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 שחוששת לתאריך זה שראתה בו פעם אחת בלבד\u0005]\u0006 אמורים דווקא \u0003היכא דקיימא\u0004 \u0005[היכן,\u0006 במקרה \u0005שעומדת,\u0006 מתרחשת\u0005]\u0006 ראייתה זו (בעשרים בחודש) \u0003בתוך\u0004 פרק הזמן של \u0003ימי נדתה,\u0004 שזהו פרק הזמן בו מעותדת היא לראות בו. \u0003אבל היכא דלא קיימא\u0004 \u0005[היכן שאין עומדת]\u0006 ראייתה זו (של העשרים בחודש) \u0003בתוך ימי נדתה,\u0004 אלא באחד עשר ימי זיבה, שאין זה זמן שהיא ראויה לראות בו — \u0003אימא\u0004 \u0005[אומר]\u0006 שהיא \u0003לא\u0004 צריכה לחשוש בפעם הבאה לעשרים בחודש. לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 רב פפא, \u0005משמיע לנו]\u0006 שאף בזו הריהי חוששת לאותו יום בפעם הבאה.","\u0003ו\u0004עוד שנינו במשנתנו כי האשה שיש לה וסת קבועה \u0003אינה מטהרת מן הוסת\u0004 אלא כשראתה שלוש פעמים רצופות שלא בתאריך וסתה הקבוע. ואף בהסבר הלכה זו \u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 בוסת זו \u0003דקבעתיה תלתא זימני\u0004 \u0005[שקבעתה\u0006 ב\u0005שלוש פעמים]\u0006 — \u0003דצריכי תלתא זימני למעקריה\u0004 \u0005[שנצרכות שלוש פעמים\u0006 של ראיות בזמן אחר, כדי \u0005לעוקרה],\u0006 \u0003אבל\u0004 ב\u0003תרי זימני\u0004 \u0005[שתי פעמים]\u0006 שראתה בתאריך מסויים בחודש — \u0003בחדא זימנא מיעקר\u0004 \u0005[בפעם אחת\u0006 של ראייה בתאריך אחר בחודש, \u0005נעקרת].\u0006","ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 רב פפא \u0005משמיע לנו\u0006 בדבריו\u0005],\u0006 והלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו כי אין האשה קובעת לה וסת עד שתקבענה שלש פעמים! ומשיבים: נצרך רב פפא להשמיענו כן, שהרי \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]\u0006 שכך היא הלכה: עקירה \u0003חדא\u0004 \u0005[אחת]\u0006 — נצרכת \u0003לחד\u0004 \u0005[ל\u0006ראייה \u0005אחת],\u0006 ו\u0003תרי\u0004 \u0005[שתי]\u0006 עקירות — נצרכות \u0003לתרתי\u0004 \u0005[לשתי\u0006 ראיות\u0005],\u0006 \u0003ותלתא\u0004 \u0005[ושלוש\u0006 עקירות] — נצרכות \u0003לתלתא\u0004 \u0005[לשלוש\u0006 ראיות\u0005].\u0006 לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 רב פפא, \u0005משמיע לנו]\u0006 שלא רק ראייה אחת נעקרת על ידי ראייה אחת אחרת, אלא גם שתי ראיות נעקרות על ידי ראייה אחת.","ומציינים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמותו,\u0006 כשיטתו\u0005]\u0006 של \u0003רב פפא:\u0004 \u0003היתה\u0004 האשה \u0003למודה להיות רואה יום עשרים\u0004 בחודש, \u0003ושינתה\u0004 לראות \u0003ליום שלשים\u0004 בחודש — הן \u0003זה\u0004 (יום הוסת הקבוע בעשרים בחודש) \u0003ו\u0004הן \u0003זה\u0004 (יום שלושים בחודש), \u0003אסורין\u0004 בתשמיש עם בעלה. ואם \u0003הגיע יום עשרים\u0004 בחודש הבא, \u0003ולא ראתה\u0004 בו — הריהי \u0003מותרת לשמש\u0004 עם בעלה \u0003עד יום שלשים\u0004 בחודש, \u0003ו\u0004אולם \u0003חוששת\u0004 היא \u0003ליום שלשים\u0004 שמא תראה בו, ולכך אסורה לשמש ביום זה עם בעלה.","ואם \u0003הגיע יום שלשים\u0004 באותו החודש \u0003וראתה\u0004 בו, והרי ראתה איפוא שתי פעמים רצופות ביום שלושים בחודש ודילגה על יום העשרים. ולאחר מכן \u0003הגיע יום עשרים\u0004 בחודש הבא \u0003ולא ראתה\u0004 בו. \u0003ו\u0004לאחר מכן \u0003הגיע יום שלשים\u0004 באותו החודש \u0003ולא ראתה\u0004 בו (ומעתה אין בידיה שלוש ראיות רצופות ביום השלושים בחודש). \u0003ו\u0004לאחר מכן \u0003הגיע יום עשרים\u0004 בחודש הבא, ושוב חזרה \u0003וראתה\u0004 בו — \u0003הותר יום שלשים,\u0004 שאין היא צריכה לחשוש מלשמש עם בעלה בתאריך זה (שהרי על ידי ראייתה בעשרים בחודש זה, נעקרו שתי הראיות של יום שלושים בחודש),"],["וחזר \u0003ונאסר יום עשרים\u0004 בחודש, כיום וסת קבוע, ואף שעברו שני חודשים שבהם לא ראתה ביום זה אלא ביום אחר — \u0003מפני שאורח\u0004 (כינוי למחזור החודשי הנשי) \u0003בזמנו\u0004 הקבוע לו \u0003בא.\u0004 ואילו במקרה זה רק שתי פעמים עברו עליה בראייה שלא בתאריך זה, וכדברי רב פפא. דומות ה\u0003נשים ב\u0004ענין דם \u0003בתוליהם\u0004 ודם נידתן \u0003כגפנים.\u0004 שנבדלות הנשים זו מזו לענין זה, כשם שנבדלות הגפנים אלה מאלה. שכשם ש\u0003יש גפן ש\u0004צבע \u0003יינה\u0004 הוא \u0003אדום, ויש גפן ש\u0004צבע \u0003יינה\u0004 הוא \u0003שחור,\u0004 כן ישנן נשים שצבע דמן הוא אדום ויש נשים שצבע דמן הוא שחור. \u0003ו\u0004כשם ש\u0003יש גפן שיינה מרובה, ויש גפן שיינה מועט,\u0004 כן ישנן נשים שדם נדה היוצא מהן מרובה ויש נשים שדם היוצא מהן מועט. ועוד בהשוואה זו של האשה לענין דמיה לגפן, \u0003ר' יהודה אומר: כל גפן\u0004 שלא יבשה — \u0003יש בה\u0004 ענבים שראוי להפיק מהם \u0003יין, ו\u0004אילו גפן \u0003שאין בה\u0004 ענבים שניתן להפיק מהן \u0003יין\u0004 — \u0003הרי זה דורקטי\u0004 (עץ יבש). ובדומה לכך, כל אשה הרואה דם הריהי יולדת, וזו שאינה רואה דם הריהי כעץ יבש מללדת.","","שנינו במשנתנו בדברי ר' יהודה המכנה את הגפן שאין מפיקים ממנה יין (ובדומה לכך, אף האשה שאינה יולדת) בשם \"דורקטי\". ומביאים כי \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא בדברי ר' יהודה אלה \"ושאין בה יין — הרי זה \u0003דור קטוע\",\u0004 שאין היא מעמידה ילדים (הדור הבא הראוי לבוא ממנה) כשאר נשים. ומביאים עוד השוואה לענין הזיקה שבין דמי בתוליה ודמי נדותה של האשה ליכולת הלידה שלה, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: כשם שהשאור יפה לעיסה,\u0004 שהלחם הנאפה מעיסה שעירבו בה שאור משובח יותר — \u0003כך\u0004 ה\u0003דמים יפין לאשה\u0004 לענין הלידה. ועוד בענין זה \u0003תנא משום\u0004 \u0005[החכם\u0006 בברייתא \u0005בשם]\u0006 \u0003ר' מאיר: כל אשה שדמיה מרובין\u0004 — \u0003בניה מרובין.\u0004","","\u0003תינוקת\u0004 (קטנה, שעדיין אינה נערה) \u0003שלא הגיע\u0004 עדיין \u0003זמנה לראות\u0004 דם, \u0003וניסת\u0004 (ונישאה) לבעל, ונבעלה לו — \u0003בית שמאי אומרים:\u0004 אין \u0003נותנין לה\u0004 (להחשיבה כטהורה מטומאת נדות) אלא \u0003ארבע\u0004 ה\u0003לילות\u0004 מעת שנבעלה. שדם שראתה בזמן זה — הרי זה דם בתולים, ולא דם נדות. ואולם לאחר מכן הריהי נטמאת בראיית דם. \u0003ו\u0004אילו \u0003בית הלל אומרים:\u0004 אין היא נטמאת בכל דם שתראה מאז הבעילה \u0003עד שתחיה המכה\u0004 (שיתרפא הפצע הנגרם מהבעילה), ואף אם עברו למעלה מארבעה לילות מאז. \u0003הגיע זמנה לראות\u0004 דם, שהיא נערה, ואולם עדיין לא ראתה דם, \u0003וניסת\u0004 לבעל ונבעלה לו, \u0003בית שמאי אומרים:\u0004 אין \u0003נותנין לה\u0004 (להחשיבה כטהורה) אלא \u0003לילה הראשון\u0004 בלבד, שהדם שרואה בו אינו נחשב כדם נדות אלא כדם בתולים. \u0003ו\u0004אילו \u0003בית הלל אומרים:\u0004 הריהי טהורה, אף שראתה דם, \u0003עד מוצאי שבת\u0004 שלאחר יום נישואיה, שהוא פרק זמן של \u0003ארבע לילות.\u0004 שכן כרגיל זמן נישואי הבתולה הוא ביום הרביעי בשבוע. ומעתה למן ליל יום חמישי ועד למוצאי שבת, ליל יום ראשון, יש לה ארבעה לילות שיכולה היא לשמש בהם עם בעלה, אף שראתה דם.","","\u0003ראתה\u0004 דם \u0003ו\u0004בזמן ש\u0003עודה בבית אביה\u0004 (כלומר, טרם נישואיה), \u0003בית שמאי אומרים: נ\u0004 \u0003ותנין לה\u0004 רק \u0003בעילת מצוה\u0004 (בעילה ראשונה שמסיים את בעילתו, אף שראתה דם בתוך כך, ואינו צריך לפרוש ממנה כפורש מן הנדה), ואולם לאחר מכן הריהי אסורה לו, כיון שראתה דם. \u0003ו\u0004אילו \u0003בית הלל אומרים:\u0004 הריהם מותרים בתשמיש \u0003כל הלילה כולה,\u0004 שמותר לבעלה לשוב ולשמש עמה כמה פעמים באותו הלילה, אף שראתה דם, שרואים אנו דם זה כדם הבא מפצע הבתולים.","שנינו בתחילת משנתנו דינה של הקטנה שעדיין לא הגיע זמנה לראות. \u0003אמר רב נחמן בר יצחק:\u0004 ובכלל דין זה כל קטנה, \u0003ואפילו\u0004 זו שאירע לה ו\u0003ראתה\u0004 דם. ומסבירים: \u0003ממאי\u0004 \u0005[מנין]\u0006 לנו שכך הוא? \u0003מדקא מפליג בסיפא\u0004 \u0005[מתוך שהוא\u0006 התנא במשנתנו \u0005מחלק בסוף\u0006 המשנה, בדינה של זו שהגיע זמנה לראות\u0005]\u0006 \u0003בין ראתה בין בשלא ראתה, מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[ש\u0006בדינה של זו הנזכרת ב\u0005תחילת\u0006 המשנה, בקטנה\u0005]\u0006 — \u0003לא שנא הכי ולא שנא הכי\u0004 \u0005[אין\u0006 זה \u0005משנה כך,\u0006 אם לא ראתה עדיין, \u0005ואין\u0006 זה \u0005משנה כך,\u0006 אם ראתה\u0005].\u0006","ומציינים כי אכן \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן\u0006 ברייתא האומרת \u0005כך]\u0006 במפורש: \u0003בית הלל אומרים:\u0004 קטנה שלא הגיע זמנה לראות, נותנים לה \u0003עד שתחיה המכה, בין\u0004 בקטנה ש\u0003ראתה\u0004 כבר דם, \u0003בין\u0004 בקטנה ש\u0003לא ראתה\u0004 עדיין. במשנתנו נאמר כי לדעת בית הלל נותנים לקטנה \u0003עד שתחיה המכה\u0004 ומבררים: \u0003עד כמה\u0004 (מתי) הוא זמן זה שנותנים לה, כיצד יודעים אנו שעדיין לא התרפא הפצע שנגרם מחמת הבעילה? \u0003אמר רב יהודה\u0004 שכך \u0003אמר\u0004 לו רבו \u0003רב: כל זמן ש\u0004הריהי עדיין \u0003נוחרת\u0004 (וכפי שיוסבר להלן). והוסיף רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר\u0006 לאחר מכן \u0005אמרתיה\u0006 להלכה זו של רב \u0005לפני]\u0006 \u0003שמואל\u0004 רבי, \u0003אמר לי: נחירה זו\u0004 — \u0003איני יודע מה היא, אלא\u0004 יש לומר כי \u0003כל זמן שהרוק\u0004 עדיין \u0003מצוי בתוך הפה\u0004 (כינוי בלשון נקיה: שרואה דם בבית הערוה) \u0003מחמת\u0004 (בשל) \u0003תשמיש\u0004 המטה עם בעלה.","ומבררים: \u0003נחירה\u0004 זו \u0003דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רב היכי דמי\u0004 \u0005[איך היא בדיוק]?\u0006 \u0003אמר רב שמואל בר רב יצחק:\u0004 ואולם \u0003לדידי מפרשא\u0004 \u0005[לי עצמי התפרש]\u0006 \u0003לי\u0004 הדבר \u0003מיניה\u0004 \u0005[ממנו]\u0006 מ\u0003רב:\u0004 אם קטנה זו כשהיא \u0003עומדת ו\u0004אזי היא \u0003רואה\u0004 דם, ואולם כשהיא \u0003יושבת ו\u0004אזי היא \u0003אינה רואה\u0004 — \u0003בידוע\u0004 הוא \u0003ש\u0004עדיין \u0003לא חיתה\u0004 אצלה \u0003המכה.\u0004 ודם זה בא מן הפצע, וניגר מתוך שהיא עומדת. וכן אף בזו היושבת \u0003על גבי קרקע ו\u0004אזי היא \u0003רואה,\u0004 ואולם כשהיא יושבת \u0003על גבי כרים וכסתות ו\u0004אזי היא \u0003אינה רואה\u0004 — \u0003בידוע\u0004 הוא \u0003ש\u0004עדיין \u0003לא חיתה המכה.\u0004 ובא הדם מן הפצע, מתוך שמתאמצת היא בישיבתה על הקרקע. ואולם אם כשיושבת \u0003על גבי כולם\u0004 (כל אלה הנזכרים למעלה, הן קרקע והן כרים וכסתות) \u0003ו\u0004הריהי \u0003רואה,\u0004 ויושבת \u0003על גבי כולם ואינה רואה\u0004 — \u0003בידוע שחיתה המכה,\u0004 שהריהי ככל אשה שהגיע זמנה לראות, שפעמים רואה באופנים הללו ופעמים שאינה רואה.","","שנינו במשנתנו בדינה של זו ש\u0003הגיע זמנה\u0004 לראות, ונישאה ונבעלה, שלדעת בית הלל נותנים לה עד מוצאי שבת, שהם ארבעה לילות. ובענין זה מביאים עוד, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדינה של זו שהגיע זמנה לראות, ונישאה ו\u0003שימשה\u0004 עם בעלה אף \u0003בימים,\u0004 מלבד ששימשה אתו בלילות. \u0003רב אמר\u0004 כי \u0003לא הפסידה\u0004 בכך את ה\u0003לילות\u0004 הבאים, עד מוצאי שבת. \u0003ו\u0004אילו \u0003לוי אמר\u0004 כי \u0003הפסידה לילות,\u0004 שכיון ששימשה ארבע עונות (לילה ויום, לילה ויום), שוב אין היא נחשבת כרואה דם מחמת פצע הבתולים. ומנמקים החכמים את דעותיהם: \u0003רב אמר\u0004 כי \u0003לא הפסידה לילות,\u0004 שהרי נותנים לה \u0003\"עד מוצאי שבת\" תנן\u0004 \u0005[שנינו],\u0006 ולא הגבילה המשנה זאת רק לזו ששימשה עם בעלה רק בלילות. \u0003ו\u0004אילו \u0003לוי אמר\u0004 כי \u0003הפסידה\u0004 \u0003לילות, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ארבע לילות\" דקתני\u0004 \u0005[ששנה\u0006 התנא\u0005]? —\u0006 \u0003ארבעה עונות\u0004 (לילה או יום). \u0003ו\u0004שואלים: \u0003ל\u0004שיטתו של \u0003רב, למה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003\"ארבע לילות\",\u0004 שהרי מותרת היא לשמש עם בעלה, אף בארבעת הימים? ומשיבים: \u0003אורח ארעא קא משמע לן\u0004 \u0005[דרך ארץ הוא,\u0006 התנא במשנתנו, \u0005משמיע לנו]\u0006 ש\u0003דרכה\u0004 המתוקנת של \u0003ביאה\u0004 שתהא דווקא \u0003בלילות.\u0004 \u0003ו\u0004שואלים: \u0003ל\u0004שיטת \u0003לוי,\u0004 הסבור כי דווקא בארבעת הלילות בלבד אמורים הדברים, \u0003ליתני\u0004 \u0005[שישנה\u0006 התנא במשנתנו\u0005]\u0006 כי נותנים לה \"\u0003ארבע לילות\",\u0004 והתוספת ששנה \u0003\"עד מוצאי שבת\" למה לי\u0004 לשנותה? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006בתוספת זו את \u0005זה הוא\u0006 התנא \u0005משמיע לנו]\u0006 \u0003דשרי למבעל\u0004 \u0005[שמותר לבעול]\u0006 \u0003לכתחלה\u0004 (בעילה של תחילת נישואין, שלא בעל עד כה אלא שתי בעילות בלבד (בליל חמישי ובליל ששי), ועדיין פתח בית הערוה דחוק) \u0003בשבת.\u0004 ו\u0003כ\u0004שיטתו של \u0003שמואל,\u0004 שכן \u0003אמר שמואל: פרצה דחוקה\u0004 (בלשון נקיה: פתח בית הערוה של הבתולה שנבעלה, ועדיין הינו דחוק) \u0003מותר ליכנס בה בשבת, ואף על פי ש\u0004בתוך כך הבועל \u0003משיר צרורות\u0004 (אבנים, וככינוי להרחבת פתח בית הערוה).","","","","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 בתולה שבעלה \u0003בעל\u0004 אותה בתחילה \u0003ולא מצא דם, ו\u0004לאחר מכן (בתוך ארבעה לילות שלאחר בעילת נישואיה) \u0003חזר ובעל, ומצא דם, ר'\u0004 \u0003חנינא אמר:\u0004 הריהי \u0003טמאה,\u0004 שזהו דם נדה. \u0003ו\u0004אילו \u0003ר' אסי אמר:\u0004 הריהי \u0003טהורה,\u0004 שדם זה בא מפצע הבתולים.","ומנמקים החכמים את דעותיהם, \u0003ר' חנינא אמר\u0004 שהריהי \u0003טמאה:\u0004 שכן \u0003אם איתא דהוה\u0004 \u0005[יש\u0006 מקום לומר \u0005שהיה]\u0006 זה \u0003דם בתולים\u0004 — \u0003מעיקרא הוי אתי\u0004 \u0005[מתחילה,\u0006 עם הביאה הראשונה, \u0005היה בא].\u0006 \u0003ו\u0004אילו \u0003ר' אסי אמר\u0004 שהריהי \u0003טהורה:\u0004 שכן יש מקום לומר כי \u0003דילמא אתרמי ליה\u0004 \u0005[הזדמן לו,\u0006 לבעל זה בבעילתו הראשונה\u0005]\u0006 לבעול \u0003כ\u0004דרך שאמר \u0003שמואל,\u0004 שכך \u0003אמר שמואל: יכולני לבעול\u0004 את האשה הבתולה \u0003כמה בעילות, בלא\u0004 להוציא \u0003דם.\u0004 ואומרים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' חנינא\u0005],\u0006 אינו סבור כן, כי \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד הוא\u0005]\u0006 \u0003שמואל\u0004 בכך, שכן \u0003רב גובריה\u0004 \u0005[גדול כוחו],\u0006 מה שאין כן בשאר אנשים.","שנינו במשנתנו את דינן של הקטנה שלא הגיע זמנה לראות ושל הנערה שהגיע זמנה לראות, ומעתה דנים בעניינה של הבוגרת (בת שתים עשרה שנים וששה חודשים). \u0003אמר רב: בוגרת\u0004 שנישאה ונבעלה — אין \u0003נותנין לה\u0004 להחשיבה כטהורה, אלא \u0003לילה הראשון\u0004 בלבד. ומסייג את דבריו: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 רק בבוגרת \u0003ש\u0004עדיין \u0003לא ראתה\u0004 דם נדות. \u0003אבל\u0004 הבוגרת שכבר \u0003ראתה\u0004 דם נדות לפני שנישאה — \u0003אין\u0004 נותנים \u0003לה אלא בעילת מצוה,\u0004 שאמנם בעלה משלים את בעילתו, \u0003ותו\u0004 \u0005[ו\u0006אולם עוד, ובנוסף לכך\u0005] —\u0006 \u0003לא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת רב ממה ששנינו: \u0003מעשה\u0004 היה בנישואיה של בתולה \u0003ונתן לה רבי\u0004 (ר' יהודה הנשיא) להחשיב את הדם שראתה כדם בתולים ב\u0003ארבע לילות\u0004 שנבעלה בהם \u0003מתוך שנים עשר חדש\u0004 מאז נישואיה. ועתה יש לברר: \u0003היכי דמי\u0004 \u0005[איך בדיוק היה זה]?\u0006 \u0003אילימא דיהיב\u0004 \u0005[אם תאמר שנתן]\u0006 \u0003לה\u0004 רבי את ארבעת הימים הללו \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003בימי קטנות\u0004 — אין לומר כן,"],["שהרי בדינה של הקטנה \"נותנים לה ארבעה לילות \u0003עד שתחיה המכה\" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 ולא ארבעה לילות בלבד (כדרך שנתן רבי במעשה הזה).","\u0003אלא\u0004 אם נאמר שמדובר \u0003דיהיב\u0004 \u0005[שנותן]\u0006 \u0003לה\u0004 רבי את ארבעת הימים \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003בימי נערות\u0004 — אף זה אינו אפשרי, שהרי תקופת \u0003נערות\u0004 בת \u0003שנים עשר חדש מי איכא\u0004 \u0005[האם יש]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל\u0004 \u0003כי\u0004 \u0003אין בין נערות לבגרות אלא ששה חדשים בלבד! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בפירוש דברי שמואל הללו כי דווקא \u0003בציר מהכי\u0004 \u0005[פחות מכך,\u0006 מששה חודשים\u0005]\u0006 \u0003הוא דליכא\u0004 \u0005[שאין]\u0006 בין נערות לבגרות, \u0003הא טפי\u0004 \u0005[הרי\u0006 ש\u0005יותר]\u0006 מכך \u0003איכא\u0004 \u0005[יש]\u0006 — אין לומר כך, שכן \u0003הא\u0004 \u0005[הרי]\u0006 \"אין בין נערות לבגרות אלא ששה חדשים \u0003בלבד\" קאמר\u0004 \u0005[הוא אמר],\u0006 ומורה הלשון \"בלבד\", שלא פחות ולא יותר מכך!","\u0003אלא\u0004 אם נאמר שמדובר \u0003דיהיב\u0004 \u0005[שנתן]\u0006 \u0003לה\u0004 רבי את ארבעת הלילות \u0003שתים בימי קטנות ושתים בימי נערות\u0004 — אף זאת אין לומר, שכן \u0003הא בעא מיניה\u0004 \u0005[הרי שאל ממנו]\u0006 \u0003רב חיננא בר שלמיא מרב\u0004 בדינה של הקטנה שנישאה כאשר עדיין לא הגיע זמנה לראות, ונבעלה ועדיין לא חיתה המכה, ובתוך כך \u0003הגיע זמנה לראות\u0004 (שהיתה לנערה) כשהיא כבר \u0003תחת בעלה\u0004 (נשואה), \u0003מהו\u0004 דינה, האם נחשבת היא עתה כזו שהגיע זמנה לראות (ויש לה ארבעה לילות)?","ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003כל בעילות שאתה בועל\u0004 בזמן שהיתה קטנה, \u0003אינן\u0004 נחשבות \u0003אלא\u0004 כבעילה \u0003אחת, והשאר\u0004 (שלוש הבעילות הבאות) הריהן \u0003משלימין ל\u0004מנין \u0003ארבעה לילות\u0004 שנותנים למי שהגיע זמנה לראות. ונמצא שאין לומר שנתן לה רבי שני לילות בימי קטנותה. וכן אין לומר שנתן לה רבי לילה אחד בימי קטנותה ושלושה לילות בימי נערותה, ונמשך הדבר על פני פרק זמן של שנים עשר חודש — שהרי אין תקופת הנערות נמשכת יותר מששה חודשים.","\u0003אלא\u0004 חייבים לומר \u0003דיהיב\u0004 \u0005[שנתן]\u0006 \u0003לה\u0004 רבי לילה \u0003אחת בימי קטנות, ושתים בימי נערות, ו\u0004עוד לילה \u0003אחת בימי בגרות.\u0004 ומעתה יש לדון בדבר: \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אתה אומר]\u0006 ש\u0003בוגרת בעלמא יהבינן\u0004 \u0005[סתם,\u0006 רגילה \u0005נותנים אנו]\u0006 \u0003לה טפי\u0004 \u0005[יותר]\u0006 מלילה אחד, כלומר, שני לילות — מעתה יוסבר מדוע נתן רבי לאותה בתולה לילה אחד בימי בגרות. שכן \u0003כי היכי דאהני\u0004 \u0005[כמו שהועילו]\u0006 כל הבעילות שבימי ה\u0003קטנות\u0004 לכך ש\u0003בימי נערות למבצר\u0004 \u0005[להפחית]\u0006 \u0003לה\u0004 לילה \u0003חדא\u0004 \u0005[אחת],\u0006 שאין היא מקבלת שלושה לילות נוספים (מלבד הלילה של ימי הקטנות), אלא שני לילות בלבד. כך \u0003אהני נמי\u0004 \u0005[מועילים גם כן]\u0006 כל הבעילות שנבעלה בימי \u0003נערות לבגרות למבצר\u0004 \u0005[להפחית]\u0006 \u0003לה\u0004 לילה \u0003חדא\u0004 \u0005[אחת],\u0006 שאין היא זוכה לשני לילות (כשאר בוגרות), אלא ללילה אחד.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003בוגרת דעלמא לא יהבינן\u0004 \u0005[סתם,\u0006 רגילה \u0005אין אנו נותנים]\u0006 \u0003לה טפי\u0004 \u0005[יותר]\u0006 מלילה אחד — \u0003לא ליתב\u0004 \u0005[יתן]\u0006 \u0003לה\u0004 רבי \u0003אלא בעילת מצוה\u0004 בלבד, \u0003ותו\u0004 \u0005[ויותר]\u0006 \u0003לא!\u0004","ומתרצים: \u0003לעולם\u0004 מדובר \u0003דיהיב\u0004 \u0005[שנתן]\u0006 \u0003לה\u0004 רבי לילה \u0003אחת בימי קטנות ושלש\u0004 לילות \u0003בימי נערות,\u0004 ובאשר לשאלה כיצד זה אפשרי בתוך פרק זמן של ששת חודשי נערות — \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003כל תלתא ירחי\u0004 \u0005[שלושה חודשים],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003עונה\u0004 היא? אין זה כך, אלא \u0003כל תרי ירחי\u0004 \u0005[שני חודשים]\u0006 — \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003עונה\u0004 היא.","ומסופר כי החכם \u0003מנימין סקסנאה הוה שקיל ואזיל לאתריה\u0004 \u0005[נטל\u0006 עצמו \u0005והלך למקומו של]\u0006 \u0003שמואל, סבר למעבד עובדא כוותיה\u0004 \u0005[סבור היה לעשות\u0006 לפסוק הלכה \u0005למעשה, כשיטתו של]\u0006 \u0003רב\u0004 שנותנים לבוגרת הבתולה כל הלילה הראשון, ו\u0003אפילו\u0004 בבוגרת שכבר \u0003ראתה\u0004 לפני נישואיה. שכן \u0003אמר\u0004 מנימין סקסאה: הרי \u0003לא פליג\u0004 \u0005[חילק]\u0006 \u0003רב\u0004 בדבריו \u0003בין\u0004 בוגרת ש\u0003ראתה\u0004 כבר ל\u0003בין\u0004 זו שעדיין \u0003לא ראתה.\u0004","\u0003קדים שכיב באורחא\u0004 \u0005[הקדים\u0006 ו\u0005נפטר\u0006 מנימין סקסנאה בהיותו עדיין \u0005בדרך,\u0006 לפני שהגיע למקומו של שמואל\u0005].\u0006 \u0003קרי\u0004 \u0005[קרא,\u0006 ייחס פסוק מן המקרא\u0005]\u0006 \u0003שמואל עליה\u0004 \u0005[עליו],\u0006 על \u0003רב \"לא יאנה לצדיק כל און\"\u0004 (משלי יב, כא), שאין הקדוש ברוך הוא מזמן שיצא דבר תקלה על ידם של הצדיקים, וכגון זה שלא נפסקה הלכה שלא כהוגן בהסתמך בטעות על דברי רב.","ומתוך שהובאו למעלה דברי רב חיננא בר שלמיא ששאל את רב, מביאים עוד ממה ש\u0003אמר רב חיננא בר שלמיא משמיה\u0004 \u0005[משמו של]\u0006 \u0003רב: כיון שנתקו\u0004 (נשרו) \u0003שניו של אדם,\u0004 שאין לו עתה במה לאכול — אף \u0003נתמעטו מזונותיו,\u0004 שאין לו גם כן מה לאכול, כבעבר. \u0003ש\u0004כן \u0003נאמר\u0004 \u0003\"גם אנכי נתתי לך נקיון שנים בכל עריכם וחסר לחם בכל מקומתיכם\"\u0004 (עמוס ד, ו), הרי שחוסר שינים (\"נקיון שינים\") מביא בעקבותיו למיעוט מזונות (\"חוסר לחם\").","שנינו במשנתנו שלדעת בית הלל זו ש\u0003ראתה\u0004 כבר \u0003ו\u0004ב\u0003עודה\u0004 בבית אביה, קודם שנישאה, נותנים לה את כל הלילה. ומביאים עוד בענין זה, מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ראתה ועודה בבית אביה\u0004 — \u0003בית הלל אומרים: כל הלילה שלה, ונותנין לה עונה שלמה.\u0004 \u0003וכמה\u0004 היא \u0003עונה שלמה?\u0004 — \u0003פירש רבן שמעון בן גמליאל: לילה וחצי יום.\u0004","\u0003ו\u0004תוהים: \u0003מי בעינן כולי האי\u0004 \u0005[האם צריכים אנו כל זאת],\u0006 שתהא \"עונה\" נחשבת לילה וחצי יום? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003הרי שהיו גתיו ובית בדיו טמאות, ובקש לעשותן\u0004 את היין (הנעשה בגיתות אלה) והשמן (הנעשה בבתי הבד הללו) \u0003בטהרה,\u0004 שלא יטמאו בהם, ולשם כך עליו לנקותם תחילה מהטומאות שבלעו ושעליהם, \u0003כיצד הוא עושה?\u0004 את \u0003הדפין\u0004 (משטחי העץ, לדחיסת הענבים, עליהם מונחת הקורה) \u0003ו\u0004את \u0003הלולבין\u0004 (המשמשים כמטאטאים לניקוי) \u0003ו\u0004את \u0003העדשין\u0004 (הגיתות, שצורתן כצורת העדשה), שהם הכלים המשמשים בגת ובבית הבד — הריהו \u0003מדיחן\u0004 (שוטפם במים), ומנקה מעליהם את היין והשמן שנטמאו."],["ואת \u0003העקלים\u0004 (כעין סלים, בהם מונחים הזיתים העומדים לכבישה בבית הבד), הן אלה שהם \u0003של נצרים\u0004 (עלי דקל דקים) \u0003ו\u0004הן אלה שהם \u0003של בצבוץ\u0004 (קנבוס) — הריהו \u0003מנגבן\u0004 באפר ומים ממה שעליהם. ואילו אלה שהן \u0003של שיפא ושל גמי\u0004 (העשויים מקני סוף), הסופגים הרבה מן היין — \u0003מיישנן\u0004 (משאיר אותם ללא שימוש), \u0003וכמה\u0004 זמן הריהו \u0003מיישנן? שנים עשר חדש.\u0004 \u0003רבן שמעון בן גמליאל אומר: מניחן מ\u0004תקופת שימוש זו ב\u0003גת ל\u0004תקופת שימוש הבאה ב\u0003גת ומ\u0004תקופת שימוש בבית ה\u0003בד ל\u0004תקופת השימוש הבאה בבית ה\u0003בד.\u0004","והקשו על שיטת רבן שמעון בן גמליאל: והלא \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטתו של \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 שהרי מתקופת שימוש אחת לאחרת עוברים שנים עשר חודשים, ובמה נחלק עליו? והשיבו כי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל להלכה לענין \u0003חרפי ואפלי\u0004 \u0005[המוקדמים והמאוחרים],\u0006 שרבן שמעון בן גמליאל אומר שאין צורך לדקדק בשנים עשר חודש מלאים לעונת הבציר והמסיק, שפעמים ההבדל הוא יותר או פחות משנים עשר חודש. ואילו לדעת חכמים יש להקפיד על אי שימוש במשך שנים עשר חודש בדיוק.","\u0003ר' יוסי אומר: הרוצה לטהר\u0004 את גיתיו ואת בתי בדיו \u0003מיד,\u0004 ולא ליישנם שנה — הריהו \u0003מגעילן ב\u0004מים \u0003רותחין\u0004 שמערה עליהם, \u0003או\u0004 ש\u0003חולטן\u0004 (מרתיח אותם) \u0003במי זיתים.\u0004 \u0003רבן שמעון בן גמליאל אומר משום\u0004 (בשם) \u0003ר' יוסי: מניחן תחת הצינור שמימיו מקלחין\u0004 כל הזמן, \u0003או במעיין שמימיו רודפין\u0004 (שוטפים), ואז אנו מניחים שהמים השוטפים מנקים את הכל. \u0003וכמה\u0004 זמן עליו להניחם תחת מים זורמים? — \u0003עונה.\u0004 ומוסיפים כי \u0003כדרך\u0004 זו \u0003שאמרו\u0004 חכמים לנהוג \u0003ביין נסך כך אמרו\u0004 חכמים לנהוג \u0003בטהרות.\u0004","ובטרם שממשיכים בהבאת הדברים, תוהים על לשון זו: \u0003כלפי לייא\u0004 \u0005[להיכן\u0006 נוטים הדברים\u0005]?\u0006 כלומר, הלא צריך לומר להיפך (\"כדרך שאמרו בטהרות כך אמרו ביין נסך\"), שהרי \u0003ב\u0004דיני \u0003טהרות קיימינן\u0004 \u0005[עומדים אנו]!\u0006 \u0003אלא\u0004 יש לתקן וכך לגרוס: \u0003כדרך שאמרו בטהרות\u0004 (בטהרתם של כלים שנטמאו), \u0003כך אמרו ביין נסך\u0004 (בכלים שבלעו יין נסך).","וממשיכים בהבאת הדברים, \u0003וכמה\u0004 היא \u0003עונה? אמר ר'\u0004 \u0003חייא בר אבא, אמר ר'\u0004 \u0003יוחנן:\u0004 מחצית אחת מן היממה, \u0003או יום או לילה.\u0004 ואילו \u0003ר' חנה שאונא, ואמרי לה\u0004 \u0005[ויש האומרים]\u0006 כי היה זה \u0003ר' חנה בר שאונא אמר\u0004 בשמו של \u0003רבה בר בר חנה\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 שהכוונה ל\u0003חצי יום וחצי לילה.\u0004","\u0003ואמר רב שמואל בר רב יצחק: ולא פליגי\u0004 \u0005[ואין\u0006 ר' חייא בר אבא ור' חנה (בר) שאונא \u0005חלוקים],\u0006 אלא \u0003הא\u0004 \u0005[זה]\u0006 שאמר או יום או לילה — מדבר \u0003בתקופת ניסן ותשרי,\u0004 שאז הימים והלילות שווים, בני שתים עשרה שעות. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר חצי יום וחצי לילה — מדבר \u0003בתקופת תמוז וטבת,\u0004 שהיום והלילה שבהן אינם שווים, ולכן חצי יום וחצי לילה הם ביחד שתים עשרה שעות. והרי זה שלא כדברי רבן שמעון בן גמליאל האומר שעונה היא לילה וחצי יום!","ומתרצים: \u0003הכא נמי אימא גבי\u0004 \u0005[כך גם כן אמור אצל,\u0006 בענין\u0005]\u0006 \u0003נדה\u0004 כי הכוונה ב\"עונה\" ל\u0003חצי יום וחצי לילה!\u0004 ותוהים על תירוץ זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לילה וחצי יום\" קאמר\u0004 \u0005[הוא,\u0006 רבן שמעון בן גמליאל \u0005אמר]!\u0006 ומסבירים: \u0003אלא\u0004 כך יש לומר בהבנת דברי רבן שמעון בן גמליאל, \u0003אי\u0004 \u0005[או]\u0006 \u0003לילה\u0004 של תקופות \u0003ניסן ותשרי,\u0004 שבהן גם הלילה וגם היום בני שתים עשרה שעות, שזהו שיעור עונה. \u0003אי\u0004 \u0005[או]\u0006 \u0003חצי יום וחצי לילה\u0004 של תקופות \u0003טבת ותמוז,\u0004 שבתקופת טבת היום קצר והלילה ארוך, ובתקופת תמוז היום ארוך והלילה קצר, ונמצא שמחצית מזו ומזו אף היא עולה לשתים עשרה שעות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: אכן לענין טהרות ויין נסך מוגדרת \"עונה\" כחצי יום וחצי לילה, ואולם לענין בעילת מצוה של הבתולה, \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר, ומשום כתיבת ה\u0003כתובה\u0004 הקודמת לבעילת המצוה, שיש \u0003דמגבי\u0004 \u0005[שמתעכבים]\u0006 \u0003בה טפי\u0004 \u0005[ביותר]\u0006 \u0003עד דחתמי\u0004 \u0005[ש\u0006משלימים אותה ו\u0005חותמים\u0006 עליה\u0005],\u0006 ולכך האריכו את משך ה\"עונה\" ביותר והעמידוה חכמים על לילה וחצי יום.","אף ששנינו במשנתנו בדינן של התינוקת שלא הגיעה זמנה לראות ושל הנערה שהגיע זמנה לראות שנותנים להן פרק זמן שבו אין הדם שהן רואות נחשב כדם נדה, מכל מקום \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו\u0006 כן \u0005שניהם]:\u0006 \u0003הלכה\u0004 בזו שראתה דם משנבעלה, שבעלה \u0003בועל בעילת מצוה, ופורש.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חסדא\u0004 ממה ששנינו בברייתא ש\u0003מעשה\u0004 היה בבתולה שנישאת, \u0003ונתן לה רבי ארבעה לילות מתוך שנים עשר חדש\u0004 מעת שנישאה, שאין הבעל פורש לאחר שגמר בעילת מצוה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב חסדא: \u0003הדורי אפירכא\u0004 \u0005[חיזור,\u0006 חיפוש, אחר \u0005קושיה]\u0006 כמו שהקשית מן הברייתא על דברי רב ושמואל, \u0003למה לי? אותיב ממתניתין\u0004 \u0005[הקשה\u0006 עליהם \u0005ממשנתנו]!\u0006 ומסבירים מדוע העדיף רב חסדא להקשות מן הברייתא: שכן \u0003הוא סבר\u0004 שכוח דברים שמובא בהם \u0003מעשה\u0004 (שהיה עמו פסק הלכה) הריהו \u0003רב\u0004 (גדול יותר) מכוחם של דברים שאין בהם מעשה, כדברי משנתנו.","ושבים לעצם השאלה, \u0003מכל מקום לרב ושמואל קשיא\u0004 \u0005[קשה].\u0006 ומשיבים: \u0003אינהו דעבדו\u0004 \u0005[הם,\u0006 רב ושמואל, \u0005שעשו,\u0006 שהורו כן\u0005] —\u0006 \u0003כרבותינו\u0004 שהורו כך. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבותינו חזרו ונמנו\u0004 והחליטו כי הבתולה שראתה דם משנבעלה, בעלה \u0003בועל בעילת מצוה, ופורש.\u0004 שאין אנו נותנים לה פרק זמן שייחשב הדם שהיא רואה כדם בתולים. ומביאים כי כהלכה זו שהורו רב ושמואל, כן הורו ר' יוחנן וריש לקיש.","שכך \u0003אמר עולא: כי הוו\u0004 \u0005[כאשר למדו]\u0006 \u0005בה ר' י\u0006 \u0003וחנן וריש לקיש ב\u0004הלכה זו שבפרק \u0003תינוקת\u0004 (הוא פרקנו), \u0003לא הוו מסקי מינה\u0004 \u0005[היו מעלים\u0006 מסיקים הלכה למעשה \u0005ממנה]\u0006 \u0003אלא כדמסיק תעלא מבי כרבא\u0004 \u0005[כ\u0006דרך \u0005שמעלה השועל מהשדה החרוש,\u0006 שאינו אלא אבק\u0005],\u0006 שאף הם לא קבעו הלכה כאמור במשנתנו, \u0003ומסיימי\u0004 \u0005[והיו מסיימים]\u0006 \u0003בה,\u0004 לאחר שלמדוה, \u0003הכי\u0004 \u0005[כך]:\u0006 אין זו להלכה, אלא הריהו \u0003בועל בעילת מצוה ופורש.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי\u0004 בשאלה על הלכה זו של ר' יוחנן וריש לקיש: \u0003אלא מעתה,\u0004 שהריהי נטמאת משעה שגמר את ביאת המצוה — יקבעו חכמים כי כל שהוא \u0003בעל נפש\u0004 (ירא שמים) אף \u0003לא יגמור\u0004 את \u0003ביאתו! אמר ליה\u0004 \u0005[לו]:\u0006 לא קבעו כך חכמים, ש\u0003אם\u0004 היו קובעים \u0003כן\u0004 — היה \u0003לבו\u0004 של הבעל \u0003נוקפו\u0004 פן תראה אשתו דם, \u0003ו\u0004היה \u0003פורש\u0004 מלבעול בכלל.","שנינו במשנתנו כי יש ונותנים לבתולה שנישאת פרק זמן של ארבעה לילות מעת שנישאה, שיהא הדם שהיא רואה בהם נחשב כדם בתולים. ומביאים עוד בענין זה ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003וכולן\u0004 (שאמרו בהן חכמים שיש להם ארבעה לילות, כתינוקת שלא הגיע זמנה לראות לדעת בית שמאי, וכנערה שהגיע זמנה לראות לדעת בית הלל) \u0003שהיו שופעות דם ובאות\u0004 (ממשיכות לראות דם) \u0003מתוך ארבעה לילות\u0004 אלה \u0003לאחר ארבעה\u0004 ה\u0003לילות,\u0004 או בזו שכבר ראתה דם בהיותה בית אביה (שנותנים לה את הלילה הראשון לדעת בית הלל) שהמשיכה לראות דם \u0003מתוך הלילה\u0004 הראשון אל \u0003לאחר הלילה\u0004 — אין אלה יכולות לסמוך על כך שדם בתולים הוא זה, אלא \u0003כולן צריכות לבדוק את עצמן\u0004 (וכדרך שתוסבר להלן).","\u0003ובכולן\u0004 היה \u0003ר' מאיר מחמיר\u0004 להנהיג בדיקה זו \u0003כדברי בית שמאי\u0004 ולא כדברי בית הלל. ולכך הקטנה ששפעה דם מתוך ארבעת הלילות הללו אל לאחריהם, אף שלא התרפאה המכה, הריהי צריכה בדיקה. וכן הנערה שהגיע זמנה לראות ששפעה דם מתוך הלילה הראשון אל לאחריו, הריהי צריכה בדיקה.","\u0003ו\u0004אילו ב\u0003שאר ראיות\u0004 דם \u0003ש\u0004יש מחלוקת בעניינן \u0003בין בית שמאי ובית הלל\u0004 — קבע ר' מאיר כי \u0003הלך\u0004 (לך) \u0003אחר מראה\u0004 ה\u0003דמים,\u0004 שבית הלל מטהרים כאשר נמצא שהשתנה מראה הדמים שלאחר מכן, ושלא כשיטת בית שמאי המטמאים אף שלא השתנה מראה הדמים.","\u0003ש\u0004כן \u0003היה ר'\u0004 \u0003מאיר אומר:\u0004 ה\u0003מראה\u0004 של ה\u0003דמים\u0004 הטמאים והטהורים \u0003משונים\u0004 (שונים) \u0003הן זה מזה.\u0004 \u0003כיצד? דם נדה\u0004 — מראהו \u0003אדום,\u0004 ואילו \u0003דם בתולים\u0004 — מראהו \u0003אינו אדום.\u0004 \u0003דם נדה\u0004 — יש לו מראה \u0003זיהום\u0004 (עכור), ואילו \u0003דם בתולים\u0004 — \u0003אינו\u0004 בעל מראה \u0003זיהום.\u0004 וכן מקור הדמים הטמאים והטהורים שונה זה מזה, שהרי \u0003דם נדה\u0004 — \u0003בא מן המקור,\u0004 ואילו \u0003דם בתולים\u0004 — \u0003בא מן הצדדין.\u0004","\u0003אמר ר'\u0004 \u0003יצחק בר ר'\u0004 \u0003יוסי, אמר ר'\u0004 \u0003יוחנן: זו דברי ר'\u0004 \u0003מאיר, אבל חכמים אומרים כל מראה דמים\u0004 הטמאים והטהורים — \u0003אחת הן,\u0004 ולכן אין טעם לבדיקה זו באשה השופעת דם, שהרי אף אם נשתנה מראה הדם הריהי טהורה כל עת ששופעת היא.","מתוך שדנים בענין הבתולה שראתה דם משנבעלה, מביאים בעניין כל אשה הרואה דם מחמת תשמיש. שכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה דם מחמת תשמיש\u0004 — \u0003משמשת\u0004 ב\u0003פעם\u0004 ה\u0003ראשונה, ו\u0004כן משמשת בפעם ה\u0003שניה\u0004 (שאינה חוששת שמא תראה בפעם זו, אף שכבר ראתה בפעם קודמת בשעת תשמיש), אם תראה דם, \u0003ו\u0004כן אם תשמש שוב בפעם ה\u0003שלישית,\u0004 ושוב תראה דם, \u0003מכאן ואילך\u0004 כיון שהוחזקה בכך — \u0003לא תשמש\u0004 עוד עם בעלה, \u0003עד שתתגרש\u0004 ממנו,"],["\u0003ו\u0004מותרת היא ש\u0003תנשא ל\u0004בעל \u0003אחר,\u0004 ולשמש עמו. שאפשר ואין היא רואה דם מחמת תשמיש אלא אצל בעלה הראשון.","ואם אשה זו \u0003ניסת\u0004 (נישאה) \u0003ל\u0004בעל \u0003אחר, ו\u0004אף בתשמיש איתו \u0003ראתה דם מחמת תשמיש,\u0004 שהיתה \u0003משמשת\u0004 ורואה דם, \u0003פעם ראשונה ו\u0004פעם \u0003שניה ו\u0004פעם \u0003שלישית.\u0004 אף כאן הלכה היא כי \u0003מכאן ואילך לא תשמש\u0004 עוד עם בעל זה, \u0003עד שתתגרש\u0004 ממנו, \u0003ו\u0004הריהי מותרת ש\u0003תנשא לאחר,\u0004 שלישי, ותשמש עימו. שאפשר והריהי רואה דם מחמת תשמיש דווקא אצל שני בעליה הקודמים. ואם אכן \u0003ניסת\u0004 (נישאה) \u0003ל\u0004בעל \u0003אחר, ו\u0004אף בתשמישה איתו \u0003ראתה דם מחמת תשמיש,\u0004 שהיתה \u0003משמשת\u0004 ורואה דם, \u0003פעם ראשונה ו\u0004פעם \u0003שניה ו\u0004פעם \u0003שלישית\u0004 — הרי הוחזקה כמי שרואה דם מחמת תשמיש אצל כל בעל, ולכך \u0003מכאן ואילך לא תשמש\u0004 כלל \u0003עד שתבדוק\u0004 את \u0003עצמה\u0004 קודם תשמיש.","ומפרטים: \u0003כיצד\u0004 היא \u0003בודקת את עצמה?\u0004 — \u0003מביאה שפופרת ובתוכה מכחול, ומוך\u0004 (מטלית רכה כשל צמר) \u0003מונח על ראשו\u0004 של המכחול, ומכניסתו אל תוך המקור דרך אותה שפופרת, ומוציאתו. ומעתה, \u0003אם נמצא דם על ראש המוך\u0004 — \u0003בידוע שמן המקור הוא בא,\u0004 וטמאה היא. ואם \u0003לא נמצא דם על ראשו\u0004 של המכחול — \u0003בידוע שמן הצדדין הוא בא,\u0004 וטהורה היא.","\u0003ואם יש לה\u0004 לאשה זו הרואה דם מחמת תשמיש, \u0003מכה\u0004 (פצע מדמם) \u0003באותו מקום\u0004 — הריהי \u0003תולה\u0004 (מייחסת) את הדם שרואה \u0003במכתה,\u0004 ולא כבא מן המקור, וטהורה היא. \u0003ואם יש לה וסת\u0004 קבועה לראייה מחמת תשמיש. שאין היא רואה כל פעם שמשמשת עם בעלה, אלא רק בזמנים מסויימים קבועים — הריהי \u0003תולה\u0004 את הדם שראתה בתשמיש \u0003בוסתה,\u0004 ומותרת לשמש עם בעלה שלא בשעת וסת זו.","\u0003ו\u0004אולם \u0003אם היה דם מכתה משונה\u0004 במראהו \u0003מדם ראייתה\u0004 בשעת תשמיש — \u0003אינה תולה\u0004 את הדם במכה. \u0003ונאמנת אשה לומר \"מכה יש לי במקור, שממנה דם יוצא\",\u0004 אלו \u0003דברי רבי.\u0004","\u0003רבן שמעון בן גמליאל אומר: דם מכה הבא מן המקור\u0004 — אף שאינו אוסר את האשה על בעלה, הריהו דם \u0003טמא\u0004 כאב הטומאה, ומטמא את האשה לענין אכילת טהרות. \u0003ו\u0004אילו \u0003רבותינו העידו\u0004 (שכך בא להם במסורת) \u0003על דם המכה הבא מן המקור שהוא טהור.\u0004","ומבררים: \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 לאיזה ענין יש הבדל \u0005ביניהם,\u0006 בין רבן שמעון בן גמליאל ורבותינו\u0005]?\u0006 \u0003אמר עולא:\u0004 השאלה היא האם \u0003מקור, מקומו טמא\u0004 ודבר שהיה בו נטמא איפוא \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. שלדעת רבן שמעון בן גמליאל, כיון שהיה דם המכה במקומו של המקור — הריהו טמא בשל כך, ואילו לדעת רבותינו אין הוא טמא בשל כך.","ודנים את זו ששנינו בדרך הבדיקה של הרואה דם מחמת תשמיש, שנעשית באמצעות \u0003שפופרת\u0004 ומכחול שבראשו מוך המוכנסים אל תוך המקור. ותוהים על כך: והרי באופן זה הריהי \u0003אפגורי מפגרא לה\u0004 \u0005[פוצעת את עצמה],\u0006 ומעתה יתכן והדם הנמצא על המוך הינו דם פצע ולא דם נדות! \u0003אמר שמואל\u0004 בהסבר הדבר: מדובר \u0003בשפופרת\u0004 קנה חלול \u0003של אבר\u0004 (עופרת), \u0003ופיה\u0004 של השפופרת \u0003רצוף\u0004 (מכופף) \u0003לתוכה,\u0004 שבשפופרת כזו אין הבדיקה גורמת לפציעת האשה. ועוד בבירור הדברים ששנינו, שאחר שראתה שלוש פעמים דם מחמת תשמיש אצל בעלה הראשון הריהי מתגרשת ממנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 בשאלה: \u0003ותבדוק עצמה\u0004 לפני כל תשמיש שמשמשת עם בעלה, \u0003ב\u0004בדיקה זו שעל ידי שפופרת ומכחול, למן ה\u0003ביאה\u0004 ה\u0003שלישית\u0004 (שראתה בה דם מחמת תשמיש) \u0003של\u0004 ה\u0003בעל הראשון,\u0004 ולא יצטרך לגרשה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה: מוטב שלא תצטרך לבדוק את עצמה לפני כל תשמיש עם בעל זה שיתכן שבכך תיאסר לכל, שכן אפשרי הדבר שאצל בעל אחר לא תראה מחמת תשמיש, \u0003לפי שאין כל האצבעות\u0004 (כינוי בלשון נקיה לאבר הבעל) \u0003שוות.\u0004 שאין היא רואה דם מחמת תשמיש אלא משום שזה הוא הבועל אותה, ואילו אצל אחר הבועל אותה, לא תראה דם מחמת תשמיש.","חזר ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש לר' יוחנן בשאלה: מדוע הריהי בודקת את עצמה רק לאחר שלושה תשמישים עם הבעל השלישי שראתה בהם דם, \u0003ו\u0004מדוע לא \u0003תבדוק\u0004 את \u0003עצמה\u0004 מאז שראתה דם \u0003בביאה\u0004 ה\u0003ראשונה של\u0004 ה\u0003בעל\u0004 ה\u0003שלישי,\u0004 שהרי כבר בביאה ראשונה של הבעל השלישי התברר שהיא רואה דם מחמת תשמיש אצל בעלים שונים? ענה לו ר' יוחנן: כל עוד לא נבעלה שלוש פעמים (לבעלה השלישי) וראתה דם, עדיין לא התברר שהיא רואה דם מחמת תשמיש אף אצל בעל זה, \u0003לפי שאין כל הכחות\u0004 של מעשי הבעילה \u0003שוות,\u0004 ויתכן הדבר שאף שבבעילה ראשונה שלו (שנעשתה בכח מסויים) ראתה דם, לא תראה דם בבעילה אחרת שלו שתיעשה בכח אחר.","ומביאים מעשים והנהגות הוראה בעניינה של הרואה דם מחמת תשמיש, \u0003ההיא דאתאי לקמיה\u0004 \u0005[אשה אחת שבאה לפני]\u0006 \u0003רבי,\u0004 שיורה לה כיצד לנהוג, שכן היא רואה דם מחמת תשמיש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי \u0003לאבדן: זיל, בעתה\u0004 \u0005[לך, הפחד לפתע אותה].\u0006 \u0003אזל בעתה\u0004 \u0005[הלך\u0006 אבדן \u0005הפחיד אותה],\u0006 \u0003ו\u0004כתוצאה מכך \u0003נפל ממנה חררת\u0004 (גודש) \u0003דם.\u0004 \u0003אמר רבי:\u0004 בכך \u0003נתרפאה\u0004 האשה ה\u0003זאת,\u0004 ושוב לא תראה דם מחמת תשמיש. שכן גוש דם זה הוא שגרם לה לראות דם.","ועוד מסופר: \u0003ההיא אתתא דאתאי לקמיה\u0004 \u0005[אשה אחת שבאה לפני]\u0006 \u0003מר שמואל,\u0004 להורות לה כיצד תנהג מפני שהיתה רואה דם מחמת תשמיש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל \u0003לרב דימי בר יוסף: זיל, בעתה\u0004 \u0005[לך, הפחד לפתע אותה].\u0006 \u0003אזל בעתה\u0004 \u0005[הלך\u0006 רב דימי בר יוסף \u0005הפחיד אותה],\u0006 \u0003ולא נפל ממנה ולא מידי\u0004 \u0005[משהו].\u0006 \u0003אמר שמואל:\u0004 אשה \u0003זו\u0004 — \u0003ממלאה\u0004 (מתמלאת) בדם, \u0003ונופצת\u0004 (ומשליכה) \u0003היא\u0004 אותו בשעת תשמיש, \u0003וכל הממלאה ונופצת\u0004 — \u0003אין לה תקנה\u0004 (רפואה).","מסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת שבאה לפני]\u0006 \u0003ר' יוחנן,\u0004 ש\u0003כל אימת דהות סלקא\u0004 \u0005[כל פעם שהיתה עולה]\u0006 \u0003מטבילת מצוה\u0004 בבית הטבילה, \u0003הות קחזיא דמא\u0004 \u0005[היתה רואה דם],\u0006 עוד קודם לתשמישה עם בעלה, וביקשה שיורה לה ר' יוחנן כיצד תנהג. \u0003אמר לה: שמא דימת\u0004 \u0005[לעז]\u0006 של בנות \u0003עיריך\u0004 (עירך) הרואות אותך שבה מבית הטבילה לבעלך, והריהן מקנאות בך על החיבה שבינך לבין בעלך היא ש\u0003עלתה ביך\u0004 (בך), והיא הגורמת לכך. מעתה, \u0003לכי והבעלי לו\u0004 לאחר שטבלת \u0003על גבי\u0004 (סמוך) \u0003הנהר,\u0004 שלא תדענה בנות עירך שחוזרת את מטבילת מצוה.","\u0003איכא\u0004 \u0005[יש]\u0006 ש\u0003אמר\u0004 שכך \u0003אמר לה\u0004 ר' יוחנן: \u0003תגלי לחברותיך\u0004 שכך קורה לך כשאת שבה מטבילת מצוה. שעל ידי כך, \u0003כי היכי דתהוו\u0004 \u0005[כמו שתוהות,\u0006 מסתכלות\u0005]\u0006 הנשים הללו \u0003עליך להך גיסא\u0004 \u0005[לצד זה,\u0006 שקנאו בך\u0005].\u0006 ומעתה שישמעו שכך קורה לך, \u0003נתהוו עלך להך גיסא\u0004 \u0005[יתהו עליך לצד זה,\u0006 שירחמו עליך\u0005],\u0006 ושוב לא יקרה לך כן. \u0003ואיכא\u0004 \u0005[ויש]\u0006 ש\u0003אמר\u0004 שכך \u0003אמר לה: גלי לחברותיך\u0004 שכך קורה לך כשאת שבה מטבילת מצוה, \u0003כי היכי דלבעו\u0004 \u0005[כדי שיבקשו]\u0006 \u0003עליך רחמים,\u0004 שתתפללנה עליך, ששוב לא יקרה לך כן. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בדינו של המצורע \u0003\"וטמא טמא יקרא\"\u0004 (ויקרא יג, מה) — \u0003צריך\u0004 המצורע, וכן כל הסובל, \u0003להודיע\u0004 את \u0003צערו לרבים, ורבים מבקשים עליו רחמים.\u0004","\u0003אמר רב יוסף: הוה עובדא\u0004 \u0005[היה מעשה]\u0006 שכזה \u0003ב\u0004עיר \u0003פומבדיתא,\u0004 באשה שהיתה רואה דם לאחר טבילת מצוה, ונהגה כדרך שאמר ר' יוחנן, \u0003ו\u0004אמנם \u0003אתסי\u0004 \u0005[נרפאה].\u0006","\u0003אמר רב יוסף, אמר רב יהודה,\u0004 \u0003אמר רב: התקין רבי\u0004 (ר' יהודה הנשיא) תקנה לדרים \u0003בשדות\u0004 (במקומות המרוחקים, שאין בהם תלמידי חכמים), ואינם יודעים כראוי דיני נדה, מתי הם ימי נדות ומתי הם ימי זיבות, ויש חשש שיכשלו, שכל ש\u0003ראתה\u0004 דם \u0003יום אחד\u0004 — \u0003תשב\u0004 (ותספור, כנדה) \u0003ששה\u0004 ימים \u0003ו\u0004נוסף להם \u0003הוא\u0004 (אותו יום שראתה בו), והרי אלה עולים לשבעה ימי נקיות, ולאחר מכן תטבול לטהרתה. הגם שאפשר שלאמיתו של דבר לא היתה זו אלא ראיית זיבה, המצריכתה שמירת יום אחד בלבד (שטובלת לטהרתה למחרת).","וכן אם ראתה \u0003שנים\u0004 ימים — \u0003תשב ששה\u0004 ימים \u0003והן\u0004 (שני הימים שראתה), והריהי טובלת לטהרתה לאחר שמונה ימים. ואולם אם ראתה \u0003שלשה\u0004 ימים, ומעתה יש לחשוש שהריהי בימי זיבה, והריהי איפוא זבה גדולה — \u0003תשב שבעה\u0004 ימים \u0003נקיים.\u0004","ומביאים לענין זה מה ש\u0003אמר ר'\u0004 \u0003זירא:\u0004 כל \u0003בנות ישראל החמירו על עצמן, שאפילו\u0004 הן \u0003רואות טפת דם\u0004 מועטה ביותר, כזו ששיעורה הוא \u0003כ\u0004זרע צמח ה\u0003חרדל\u0004 — הריהן \u0003יושבות עליה שבעה נקיים,\u0004 כאילו הן זבות.","ובענין דברי ר' זירא אלה, מביאים עוד: \u0003אדבריה\u0004 \u0005[הדריכו]\u0006 \u0003רבא לרב שמואל\u0004 בדרך, \u0003ודרש:\u0004 אשה הרה ש\u0003קשתה\u0004 ללדת במשך \u0003שני ימים\u0004 בתקופת ימי זיבתה, \u0003ול\u0004יום ה\u0003שלישי\u0004 של הקישוי \u0003הפילה\u0004 את עוברה — אף שאין דם הנראה בקישוי לידה מטמא את האשה בזיבה, מכל מקום זו \u0003תשב שבעה נקיים\u0004 כזבה. ומסבירים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רבא כי \u0003אין\u0004 נוהג דין \u0003קשוי\u0004 (שאין האשה נטמאת בזיבה בדם הנראה אז), אלא בלידה של ממש, ולא \u0003לנפלים.\u0004 \u0003ו\u0004כן סבור רבא כי \u0003אי אפשר לפתיחת הקבר\u0004 (בית הרחם), שנפתח בעת הלידה, \u0003בלא\u0004 שתראה \u0003דם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא\u0004 בשאלה על דבריו אלה: \u0003מאי אריא\u0004 \u0005[מה המכוון]\u0006 בדבריך שמדובר במי ש\u0003קשתה שני ימים,\u0004 והלא \u0003אפילו\u0004 ראתה \u0003משהו\u0004 דם \u0003בעלמא\u0004 \u0005[בסתם]\u0006 הריהי יושבת עליו שבעה נקיים, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר'\u0004 \u0003זירא: בנות ישראל החמירו על עצמן, שאפילו רואות טפת דם כחרדל\u0004 — \u0003יושבות עליה שבעה נקיים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב פפא: \u0003אמינא\u0004 \u0005[אני אמרתי]\u0006 \u0003לך איסורא\u0004 \u0005[איסור],\u0006 שכך הוא דינה של אשה זו מן התורה, \u0003ואת אמרת מנהגא\u0004 \u0005[ואתה אומר\u0006 לי \u0005מנהג]?!\u0006 \u0003היכא דאחמור\u0004 \u0005[היכן שהחמירו]\u0006 בנות ישראל על עצמן כדברי ר' זירא — \u0003אחמור\u0004 \u0005החמירו],\u0006 ויושבות הן שבעה נקיים. ואולם \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אחמור\u0004 \u0005[החמירו]\u0006 בנות ישראל על עצמן כדברי ר' זירא — \u0003לא אחמור\u0004 \u0005[החמירו],\u0006 ואינן יושבות שבעה נקיים. ואולם במקרה זה שאמרתי, הריהן חייבות לשבת מן התורה שבעה נקיים.","מתוך שהובאו דברי רבא בענין טומאת הנדה, מביאים עוד מדברים שונים שאמר בענין זה. ומציינים כי המלים הבאות \u0003(תבעוה, נתר, בחמין, לטבול, קמטים, על גבי, נמל,\u0004 הריהן \u0003סימן\u0004 לזכרון העניינים שיבואו להלן\u0003).\u0004 \u0003אמר רבא:\u0004 אשה ש\u0003תבעוה\u0004 (הפצירו בה) \u0003לינשא, ונתפייסה\u0004 (ונעתרה) לכך — \u0003צריכה שתשב שבעה נקיים,\u0004 שמא ראתה דם מתוך חימוד (תשוקה).","ובענין זה מסופר כי \u0003רבינא איעסק ליה לבריה\u0004 \u0005[התעסק\u0006 השתדל להשיא \u0005את בנו]\u0006 \u0003בי\u0004 \u0005[\u0006ב\u0005בית]\u0006 \u0003רב חנינא,\u0004 שיישא בנו את בתו של רב חנינא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חנינא לר' ירמיה: האם \u0003סבר ליה מר למכתב\u0004 \u0005[חושב אדוני לכתוב]\u0006 \u0003כתובה\u0004 שייערכו הנישואין \u0003לארבעה יום\u0004 (ביום הרביעי)? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה: \u0003אין\u0004 \u0005[כן].\u0006 ואולם \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003לארבעה\u0004 (היום הרביעי), לא נערכו הנישואין, אלא \u0003נטר\u0004 \u0005[המתין]\u0006 מלשאת \u0003עד ארבעה\u0004 (היום הרביעי) \u0003אחרינא\u0004 \u0005[האחר,\u0006 בשבוע הבא\u0005],\u0006 וכך נמצא כי \u0003איעכב\u0004 \u0005[התעכב]\u0006 יום הנישואין \u0003שבעה יומי בתר ההוא יומא\u0004 \u0005[ימים לאחר אותו היום]\u0006 שבו הוסכם על נישואין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חנינא לר' ירמיה: \u0003מאי האי\u0004 \u0005[מה זה],\u0006 מדוע מתעכבים עוד שבוע מהנישואין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא סבר לה מר להא\u0004 \u0005[אין אדוני סבור,\u0006 מקבל \u0005את\u0006 הלכה \u0005זו]\u0006 של \u0003רבא,\u0004 שכן \u0003אמר רבא:\u0004 אשה ש\u0003תבעוה לינשא ונתפייסה\u0004 — \u0003צריכה לישב שבעה נקיים?\u0004 ולכך המתנתי אף אני שבעה ימים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חנינא לר' ירמיה: \u0003אמר\u0004 \u0005[אמור]\u0006 שכך \u0003אמר רבא\u0004 דווקא \u0003ב\u0004מי שהיא \u0003גדולה, דקחזיא דמא\u0004 \u0005[שרואה\u0006 כבר \u0005דם].\u0006 \u0003אבל בקטנה דלא חזיא דמא\u0004 \u0005[ש\u0006עדיין \u0005אינה רואה דם],\u0006 כבתי זו — \u0003מי\u0004 \u0005[האם]\u0006 גם כן \u0003אמר\u0004 רבא את דינו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה לרב חנינא: \u0003בפירוש אמר רבא: לא שנא\u0004 \u0005[אין שונה]\u0006 דין זה ב\u0003גדולה, לא שנא\u0004 \u0005[\u0006ו\u0005אין שונה]\u0006 ב\u0003קטנה.\u0004 שהרי ב\u0003גדולה טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 להצריכה לשבת שבעה נקיים משעה שהתפייסה? \u0003משום דמחמדא\u0004 \u0005[שחומדת],\u0006 \u0003קטנה נמי מחמדא\u0004 \u0005[גם כן חומדת].\u0006","ועוד \u0003אמר רבא:\u0004 ה\u0003אשה\u0004 הטובלת לטהרתה מטומאת נדתה"],["\u0003לא תחוף\u0004 (תחפוף) את שער ראשה \u0003לא בנתר ולא בחול.\u0004 והסבר הדברים: \u0003בנתר\u0004 אינה חופפת — \u0003משום דמקטף\u0004 \u0005[ש\u0006הוא \u0005מנתק]\u0006 את שער הראש משורשיו, והשערה שנשרה והתערבה בתוך שאר שערות הראש, מהווה חציצה בטבילה. \u0003ו\u0004אין היא חופפת את שער ראשה \u0003בחול\u0004 — \u0003משום דמסריך\u0004 \u0005[ש\u0006הוא \u0005מדביק\u0006 את שערות הראש\u0005],\u0006 והרי זו חציצה בטבילה.","\u0003ו\u0004עוד בדין החפיפה, \u0003אמר אמימר משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רבא: אשה לא תחוף\u0004 (תחפוף) את שער ראשה \u0003אלא ב\u0004מים \u0003חמין, אבל לא בצונן.\u0004 \u0003ו\u0004יכולה היא לחפוף את ראשה \u0003אפילו בחמי חמה\u0004 (מים שחוממו על ידי קרני השמש). ומסבירים: ב\u0003צונן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 תחפוף את שער ראשה — \u0003משום דקרירי\u0004 \u0005[ש\u0006המים \u0005קרירים],\u0006 \u0003ומשרו מזייא\u0004 \u0005[וגורמים להשרת השער],\u0006 והשערה שנשרה והתערבה בשאר שערות הראש חוצצת בטבילה.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בהנהגות טבילת הנשים: \u0003לעולם ילמד אדם בתוך ביתו\u0004 (את הנשים שבמשפחתו) \u0003שתהא\u0004 ה\u0003אשה\u0004 הטובלת \u0003מדיחה\u0004 (מנקה) את מקום \u0003בית קמטיה\u0004 (חלקי הגוף בהם ישנם קפלים, כבית השחי ובית הסתרים) \u0003במים\u0004 לפני טבילתה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו כי \u0003בית הקמטים ובית הסתרים אינן צריכין לביאת מים\u0004 (שיגיעו אל תוכם מי מקוה הטהרה) כדי שתיטהר הטובלת!","ומשיבים: \u0003נהי\u0004 \u0005[אמנם]\u0006 \u0003ביאת מים\u0004 בפועל — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים],\u0006 ואולם שיהא זה \u0003מקום הראוי לביאת מים\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו].\u0006 והרי זה \u0003כ\u0004שיטת \u0003ר' זירא,\u0004 שכן \u0003אמר ר'\u0004 \u0003זירא: כל\u0004 קרבן מנחה הקרב במקדש \u0003הראוי לבילה\u0004 (בלילה) עם שמן ששיעורה עד ששים עשרון — \u0003אין\u0004 ה\u0003בילה\u0004 (בלילה) \u0003מעכבת בו,\u0004 לפסול את המנחה כשלא נבללה. \u0003ו\u0004אילו כל דבר מנחה \u0003שאין ראוי לבילה\u0004 ששיעורה יותר מששים עשרון — ה\u0003בילה מעכבת בו.\u0004 ועקרון זה של ר' זירא נוהג בהלכות רבות, וכן בענייננו, שצריך שיהא המקום ראוי שיבואו בו מים, ואף אם לא באו בו מים בפועל הרי זו טבילה ראויה.","ובענין זה שיש להדיח את המקומות הללו בגוף לשם הטבילה, \u0003אמר רבין בר רב אדא,\u0004 \u0003אמר ר'\u0004 \u0003יצחק: מעשה בשפחתו של רבי שטבלה\u0004 \u0003ועלתה, ו\u0004לאחר מכן \u0003נמצא לה עצם\u0004 ה\u0003חוצץ בין שיניה,\u0004 \u0003והצריכה רבי טבילה אחרת.\u0004 שאף שאין צורך שיבואו המים בפועל אל בין שיניה (שמקום בית הסתרים הוא), מכל מקום לא עלתה לה טבילתה, מפני שלא היה מקום זה ראוי לביאת מים.","\u0003ו\u0004עוד \u0003אמר רבא\u0004 בדין טבילת אשה מטומאתה: \u0003טבלה\u0004 האשה מטומאתה \u0003ועלתה\u0004 מן המקווה, \u0003ו\u0004לאחר מכן \u0003נמצא עליה,\u0004 על שערה, \u0003דבר\u0004 ה\u0003חוצץ,\u0004 מה דינה? \u0003אם\u0004 ב\u0003סמוך לחפיפה\u0004 של שערה \u0003טבלה\u0004 — \u0003אינה צריכה\u0004 לשוב ו\u0003לחוף\u0004 (לחפוף) \u0003ולטבול\u0004 שנית. שכן מניחים אנו שלא היתה בה חציצה זו בשעה שטבלה. \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003צריכה\u0004 לחזור ו\u0003לחוף ולטבול.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את דברי רבא אלה באופן שונה: \u0003אם באותו יום שחפפה טבלה\u0004 — \u0003אינה צריכה לחוף ולטבול, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003צריכה\u0004 לשוב ו\u0003לחוף ולטבול.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל יש \u0005ביניהם,\u0006 בין שתי הלשונות הללו\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 \u0003ל\u0004ענין \u0003מסמך\u0004 \u0005[סמיכה,\u0006 הצמדה\u0005]\u0006 \u0003לחפיפה\u0004 את ה\u0003טבילה.\u0004 שללשון הראשון צריכה הטבילה להיות סמוך לחפיפה, ואילו ללשון השני אין צורך שתהיה הטבילה בסמוך לחפיפה, ודי שתהא באותו יום שבו חפפה את ראשה. ועוד נבדלים שני הלשונות הללו בשאלה האם מותר \u0003למיחף ביממא ולמטבל בליליא\u0004 \u0005[לחפוף ביום ולטבול\u0006 בסמוך לכך \u0005בלילה].\u0006 שלפי הלשון הראשון מותר הדבר (שהרי נעשתה הטבילה בסמוך לחפיפה), ואילו ללשון השני אסור הדבר (שהרי אין הטבילה באותו יום בו נעשתה החפיפה).","ועוד הלכה ש\u0003אמר רבא\u0004 בדין טבילת אשה: \u0003אשה לא תעמוד על גבי כלי חרס, ותטבול.\u0004 \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב כהנא למימר\u0004 \u0005[לומר]\u0006 כי \u0003טעמא מאי\u0004 \u0005[טעם\u0006 הדבר \u0005מהו]\u0006 — \u0003משום גזירת מרחצאות,\u0004 שלא תבואנה מתוך כך הנשים לטבול מטומאתן במרחץ שמימיו שאובים, שכן במרחצאות היו כלים שהיו עומדים עליהם הרוחצים. ומכאן ניתן להסיק: \u0003הא\u0004 \u0005[הרי]\u0006 שלעמוד \u0003על גבי סילתא\u0004 \u0005[בקעת\u0006 עץ\u0005]\u0006 ולטבול — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר לעשות כן\u0005],\u0006 שהרי אין מקום לגזור על כך, שכן אין הוא נוהג בבתי המרחץ.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן מנהרדעא\u0004 לרב כהנא: אין הטעם בדברי רבא כדבריך, אלא \u0003התם טעמא מאי\u0004 \u0005[שם,\u0006 בדברי רבא \u0005הטעם מהו]\u0006 שאסור לעמוד על גבי כלי חרס ולטבול — \u0003משום דבעית\u0004 \u0005[שמפחדת]\u0006 האשה לעשות כן, שלא תיפול, ואין היא טובלת יפה. וכיון שזהו הטעם — אף טבילה על גבי סילתא אסורה, שכן העמידה על ה\u0003סילתא נמי בעיתא\u0004 \u0005[גם כן מפחידה],\u0006 כעמידה על כלי חרס.","ועוד בדרך הראויה לטבילת אשה, \u0003אמר רב שמואל בר רב יצחק: אשה לא תטבול\u0004"],["\u0003בנמל\u0004 (מקום עגינתן של הספינות בחוף הים), שיש שם הרבה טיט, שעשוי להיות חציצה בטבילה אם הוא נדבק על גופה של הטובלת, \u0003אף על גב דהשתא ליכא\u0004 \u0005[אף על פי שעתה אין\u0006 טיט\u0005]\u0006 — אסורה לטבול שם, שכן \u0003אימר ברדיוני\u0004 \u0005[אמור\u0006 כי \u0005בדשדוש הרגליים],\u0006 שדשדשה האשה לאחר שטבלה \u0003נפל\u0004 מעליה הטיט. ואולם היה עליה בשעה שטבלה, ולא היתה זו טבילה ראויה.","ומסופר כי \u0003אבוה\u0004 \u0005[אביו]\u0006 של האמורא \u0003שמואל עבד לבנתיה\u0004 \u0005[עשה לבנותיו]\u0006 \u0003מקוואות\u0004 (בורות שיש בהם מי גשמים, כשיעור הראוי לטבילה) שתטבולנה בהם מטומאתן, \u0003ביומי\u0004 \u0005[בימי]\u0006 תקופת \u0003ניסן.\u0004 \u0003ולא הניחן לטבול בנהר משום שהנהר מלא מי גשמים שאינם מטהרים בדרך זו.\u0004 \u0003ו\u0004עשה להן \u0003מפצי\u0004 \u0005[מחצלות]\u0006 אותן הניח ליד הנהר, שתפסענה עליהן בבואן לטבול בנהר, \u0003ביומי\u0004 \u0005[בימי]\u0006 תקופת \u0003תשרי, שלא יחצוץ הטיט.\u0004","ומביאים עוד מדברי חכמים בדיני חציצה בטבילה. \u0003אמר רב גידל, אמר רב:\u0004 האשה ש\u0003נתנה תבשיל לבנה, ו\u0004לאחר מכן \u0003טבילה ועלתה\u0004 — \u0003לא עלתה\u0004 (אין נחשבת) \u0003לה טבילה\u0004 זו. ו\u0003אף על גב דהשתא ליכא\u0004 \u0005[אף על פי שעתה אין]\u0006 עליה שארית של תבשיל זה — שכן \u0003אימר ברדיוני\u0004 \u0005[אמור\u0006 כי \u0005בדשדוש הרגליים],\u0006 בעת שדשדשה האשה ברגליה לאחר שטבלה \u0003נפל\u0004 מעליה התבשיל שדבק בה, ואולם בשעת הטבילה היה עדיין עליה, וחצץ.","\u0003אמר רמי בר אבא: הני רבדי דכוסילתא\u0004 \u0005[קרום עור המגליד פצעי הקזה],\u0006 \u0003עד תלתא יומי\u0004 \u0005[שלושה ימים\u0006 מזמן ההקזה\u0005]\u0006 — \u0003לא חייצי\u0004 \u0005[אינם חוצצים],\u0006 שעדיין הם לחים, \u0003מכאן ואילך\u0004 — הריהם \u0003חייצי\u0004 \u0005[חוצצים],\u0006 שהתייבשו לגמרי.","\u0003אמר מר עוקבא: לפלוף\u0004 (ליחת העין המתייבשת בה) \u0003ש\u0004נתון \u0003בעין,\u0004 אם עדיין הוא \u0003לח\u0004 — \u0003אינו חוצץ,\u0004 ומשעה ש\u0003יבש\u0004 — הריהו \u0003חוצץ.\u0004 ומסבירים: \u0003אימתי נקרא\u0004 זה \"לפלוף \u0003יבש\"?\u0004 — \u0003משעה שמתחיל לירק\u0004 (להצהיב).","\u0003אמר שמואל: כחול\u0004 (צבע קישוט של נשים הניתן סביב לעין) \u0003ש\u0004נתון \u0003בתוך העין\u0004 — \u0003אינו חוצץ, ו\u0004אילו זה \u0003ש\u0004נתון \u0003על גבי העין\u0004 — \u0003חוצץ.\u0004 ו\u0003אם היו עיניה פורחות\u0004 (מפלבלות, נפתחות ונסגרות בתכיפות) — \u0003אפילו\u0004 היה הכחול נתון \u0003על גבי העין\u0004 — \u0003אינו חוצץ,\u0004 שכן הפתיחה והסגירה התכופה של העין גורמת להעברתו של הכחול.","ועוד בדין חציצה \u0003אמר ר'\u0004 \u0003יוחנן:\u0004 האשה ש\u0003פתחה עיניה ביותר\u0004 בשעה שטבלה — הרי זה נחשב לה כחציצה לעור שמעל לעיניה, \u0003או\u0004 ש\u0003עצמה עיניה ביותר\u0004 בשעה שטבלה — הרי זה נחשב לה כחציצה לעור שמתחת לעיניה, ולכך \u0003לא עלתה לה טבילה.\u0004","ועוד בענין טבילה \u0003אמר ריש לקיש:\u0004 \u0003האשה לא תטבול\u0004 לטהרתה \u0003אלא דרך גדילתה\u0004 (בדרכה הרגילה כהרגלה): שלא תדחק את זרועותיה בכוח על גופה, שלא תצמיד את רגליה ביותר, ואף אינה צריכה לפושטם ביותר, אלא כדרך שהיא נוהגת תמיד. ואז הקמטים בגוף שאין המים מגיעים אליהם, אינם נחשבים כחציצה, ועלתה לה הטבילה. ו\u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 לענין האופן בו צריכים להיראות האיש והאשה לפני הכהן הקובע בהם אם נטמאו בנגעי הגוף: \u0003האיש\u0004 שיש בו נגע בין רגליו, הריהו \u0003נראה\u0004 לפני הכהן \u0003כ\u0004דרך שנראה בה האדם ה\u0003עודר\u0004 בקרקע לניכוש העשבים שבה, שעושה כן בפיסוק רגליים מועט. \u0003ו\u0004אם הנגע בין זרועות האיש, הריהו עומד לפני הכהן כאדם ה\u0003מוסק\u0004 (מלקט) \u0003זיתים,\u0004 שמניף את זרועותיו כלפי מעלה. וה\u0003אשה\u0004 שיש לה נגע בין רגליה \u0003נראת\u0004 לפני הכהן \u0003כ\u0004דרך שנראית בה האשה ה\u0003אורגת.\u0004 אם הנגע שבה הוא מתחת לדדיה, הריהי נראית לפני הכהן \u0003כ\u0004אשה ה\u0003מניקה את בנה.\u0004","ועוד בדיני חציצה, \u0003אמר רבה בר רב הונא: נימא\u0004 (שערה) \u0003אחת\u0004 ה\u0003קשורה\u0004 בשערות הראש הריהי בוודאי מהודקת היטב, ולכן נחשבת כ\u0003חוצצת\u0004 בטבילה."],["וכמו כן ברור הוא כי \u0003שלש\u0004 נימין הקשורות, אינן מהודקות היטב, ולכך \u0003אינן חוצצות\u0004 בטבילה. ואולם מה דינן של \u0003שתים\u0004 נימות הקשורות — \u0003איני יודע.\u0004 \u0003ו\u0004אילו \u0003ר' יוחנן אמר: אנו אין לנו\u0004 במסורת לפסול בטבילה משום חציצה \u0003אלא\u0004 בנימה \u0003אחת\u0004 קשורה. ואולם שתי נימין הקשורות ויתר על כך, אינן חוצצות.","ועוד בדיני חציצה. \u0003אמר ר'\u0004 \u0003יצחק:\u0004 \u0003דבר תורה\u0004 (מדין תורה, כהלכה שנמסרה למשה מסיני) אין דבר חוצץ בטבילה, אלא כאשר החוצץ מכסה את \u0003רובו,\u0004 וכמו כן כאשר הוא דבר ש\u0003ה\u0004טובל \u0003מקפיד עליו.\u0004 וכאשר מתקיימים שני תנאים אלה — הרי זה \u0003חוצץ.\u0004 אכן כאשר הדבר הוא אמנם \u0003רובו ו\u0004אולם הטובל \u0003אינו מקפיד עליו\u0004 — \u0003אינו חוצץ\u0004 מדין תורה. \u0003ו\u0004חכמים \u0003גזרו\u0004 אף \u0003על רובו שאינו מקפיד\u0004 שהריהו חוצץ. וטעם גזירתם: \u0003משום רובו המקפיד\u0004 עליו. \u0003ו\u0004כן \u0003גזרו\u0004 אף \u0003על מיעוטו המקפיד\u0004 עליו, שהריהו חוצץ, וטעם גזירתם: \u0003משום רובו המקפיד.\u0004","ושואלים: \u0003ולגזור נמי\u0004 \u0005[ושיגזרו גם כן]\u0006 \u0003על מיעוטו שאינו מקפיד\u0004 שיהא חוצץ, ו\u0003משום מיעוטו המקפיד!\u0004 ומשיבים: \u0003היא גופה\u0004 \u0005[עצמה,\u0006 מיעוטו המקפיד עליו\u0005]\u0006 אינו חוצץ מדין תורה אלא רק מ\u0003גזרה\u0004 שגזרו חכמים, \u0003ואנן ניקום\u0004 \u0005[ואנו נעמוד]\u0006 \u0003ונגזור גזרה לגזרה?!\u0004","ובענין זמנה של טבילת אשה מטומאת נדתה \u0003אמר רב:\u0004 אשה שהיתה טמאה \u0003נדה\u0004 וטובלת לטהרתה \u0003בזמנה\u0004 — \u0003אינה טובלת אלא בלילה\u0004 (ליל היום השמיני), ולא ביום השביעי (שלא כאשה הזבה הטובלת ביום השביעי לספירת שבעת ימי נקיות). \u0003ו\u0004אולם אם לא טבלה בליל יום השמיני, והריהי טובלת \u0003שלא בזמנה\u0004 (ביום השמיני) — הריהי \u0003טובלת בין ביום בין בלילה.\u0004 ואילו \u0003ר' יוחנן אמר\u0004 כי \u0003בין\u0004 הטובלת \u0003בזמנה, בין\u0004 הטובלת \u0003שלא בזמנה\u0004 — \u0003אינה טובלת אלא בלילה\u0004 ולא ביום. וטעם הדבר: \u0003משום סרך\u0004 (היגררות) של \u0003בתה.\u0004 שיש לחשוש שבתה תראה את אמה הטובלת ביום. ומאחר שאין הבת יודעת שזו טבילה שלא בזמנה, עלולה היא לכשתינשא לטבול אף טבילה שבזמנה ביום ולא בלילה. ולא תעלה לה טבילה זו לטהרתה, שעדיין נדה היא.","\u0003ו\u0004מוסרים כי \u0003אף רב הדר ביה\u0004 \u0005[חזר בו],\u0006 מהוראתו זו. שכן \u0003אמר ר'\u0004 \u0003חייא בר אשי, אמר רב: נדה, בין בזמנה בין שלא בזמנה\u0004 — \u0003אינה טובלת אלא בלילה,\u0004 וטעם הדבר: \u0003משום סרך בתה.\u0004 ואולם מסופר על חכמים שונים שהתקינו לטבול ביום השמיני, ומפני טעמים שונים.","\u0003אתקין\u0004 \u0005[התקין]\u0006 \u0003רב אידי ב\u0004עיר \u0003נרש למטבל ביומא דתמניא\u0004 \u0005[לטבול ביום השמיני],\u0006 \u0003משום אריותא\u0004 \u0005[אריות]\u0006 ששוטטו בלילות באיזור זה, והיו פוגעים בנשים הטובלות בלילה. \u0003רב אחא בר יעקב\u0004 התקין \u0003ב\u0004עיר \u0003פפוניא\u0004 לטבול ביום ולא בלילה, \u0003משום גנבי\u0004 \u0005[גנבים]\u0006 הגונבים בלילות, שהיו אלה מנצלים את זמן היעדרה של האשה הטובלת בלילה וגונבים מביתה.","ובדומה לכך \u0003רב יהודה\u0004 התקין \u0003ב\u0004עיר \u0003פומבדיתא\u0004 שיטבלו ביום השמיני ולא בלילו, וטעמו של דבר: \u0003משום צנה\u0004 המרובה בלילות, המסכנת את הנשים הטובלות בלילה. וכן התקין \u0003רבא ב\u0004עיר \u0003מחוזא\u0004 שיטבלו ביום השמיני ולא בלילו, ו\u0003משום אבולאי\u0004 \u0005[שומרי העיר]\u0006 המשוטטים בעיר בלילות, ועלולים לפגוע בנשים בדרכן אל בית הטבילה ובשובן משם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא ולאביי\u0004 בשאלה: \u0003מכדי האידנא כולהו\u0004 \u0005[מכיון שבזמן הזה\u0006 כל הנשים \u0005כולן]\u0006 שראו דם, ואפילו בשיעור מועט כדין \u0003ספק זבות שוינהו רבנן\u0004 \u0005[עשאון,\u0006 קבעו בהן, \u0005חכמים],\u0006 והריהן סופרות שבעה נקיים, אם כן מעתה \u0003ליטבלינהו ביממא דשביעאה\u0004 \u0005[שיטבילון,\u0006 שיתירו להן לטבול \u0005ביום השביעי],\u0006 שהרי אם נדה היא — הרי ספרה שבעת ימי נדותה, ואם ספק זיבה היא — הרי הזבה טובלת ביום השביעי!","השיבו לו: הטעם שאין נוהגים כן, \u0003משום\u0004 דרשתו של \u0003ר' שמעון, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 על הכתוב בטהרת האשה הזבה \"ואם טהרה מזובה וספרה לה שבעת ימים \u0003אחר תטהר\"\u0004 (ויקרא טו, כח): כך אמרה תורה בדין טהרתה של הזבה, שתהיה הטהרה \u0003\"אחר\"\u0004 — \u0003אחר לכולן,\u0004 אחר כל ימי טהרתה, שיהיו אלה שבעת ימי טהרה רצופים, \u0003שלא תהא טומאה מפסקת ביניהן.\u0004 ואילו \u0003ר' שמעון אומר\u0004 בדרשת הכתוב \u0003\"אחר תטהר\"\u0004 — \u0003אחר מעשה\u0004 (של ספירתה, שכיון שספרה מקצת היום של היום השביעי), \u0003תטהר.\u0004","\u0003אבל אמרו חכמים\u0004 כי למעשה \u0003אסור לעשות כן,\u0004 שתטבול ביום השביעי, לאחר שבדקה עצמה בתחילת היום ומצאה שהיא נקיה, \u0003שמא\u0004 לאחר שטבלה \u0003תבא לידי ספק,\u0004 שתשמש עם בעלה בו ביום, ולאחר שתשמש עמו תראה דם, ונמצא שלא היו אלה שבעה ימי נקיות וטבילתה פסולה, ובאה לידי איסור כרת בתשמיש בנדות.","\u0003אמר רב הונא: אשה\u0004 מותר שתהא \u0003חופפת\u0004 את שערה לקראת טבילה \u0003באחד\u0004 (ביום ראשון) \u0003בשבת\u0004 (בשבוע), \u0003וטובלת ב\u0004יום ה\u0003שלישי בשבת\u0004 (בשבוע). וראיה לדבר: \u0003שכן\u0004 אנו מוצאים ש\u0003אשה חופפת בערב שבת, וטובלת במוצאי שבת.\u0004","וכן מותר ל\u0003אשה\u0004 שתהא \u0003חופפת ב\u0004יום \u0003אחד\u0004 (ראשון) \u0003בשבת, וטובלת ב\u0004יום \u0003רביעי בשבת.\u0004 וראיה לדבר: \u0003שכן\u0004 אנו מוצאים ש\u0003אשה חופפת בערב שבת, וטובלת במוצאי יום טוב שחל להיות אחר\u0004 (למחרת) \u0003השבת.\u0004","וכן מותר ל\u0003אשה\u0004 שתהא \u0003חופפת ב\u0004יום \u0003אחד\u0004 (ראשון) \u0003בשבת, וטובלת ב\u0004יום \u0003חמישי בשבת.\u0004 וראיה לדבר: \u0003שכן\u0004 אנו מוצאים ש\u0003אשה חופפת בערב שבת, וטובלת במוצאי שני ימים טובים של ראש השנה שחל להיות אחר השבת.\u0004","\u0003ו\u0004אילו \u0003רב חסדא אמר\u0004 כי אכן במקרים הללו (כטבילה במוצאי שבת, וטבילה במוצאי יום טוב ומוצאי ראש השנה שחל אחר השבת) \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שהותרה בהם החפיפה הנעשית כמה ימים לפני הטבילה, ואולם על סמך מקרים אלה לומר \u0003\"שכן\",\u0004 וללמוד מהם שאף בטבילות שבימות החול, הותרה החפיפה שתיעשה כמה ימים לפני הטבילה — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 כי \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003אפשר\u0004 שתחפוף בסמיכות זמן לטבילה — הרי \u0003אפשר\u0004 ואין מקום להתיר שתיעשה החפיפה לפני כן. ואולם \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אפשר\u0004 לחפוף בסמוך לטבילה, כגון בטבילות אלה הנעשות במוצאי שבת ויום טוב — הרי \u0003לא אפשר,\u0004 ולכך הותרה רק בהם החפיפה שתיעשה לפני כן.","\u0003ו\u0004אילו \u0003רב יימר אמר\u0004 כי \u0003אפילו \"שכן\" נמי אמרינן\u0004 \u0005[גם כן אומרים אנו],\u0006 ולכך מותרת החפיפה ביום ראשון בשבוע לקראת טבילה שתיעשה ביום שלישי, לטבילה ביום רביעי. כדברי רב הונא, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004היתרו של רב הונא ש\u0003אשה\u0004 תהא \u0003חופפת ב\u0004יום \u0003אחד\u0004 (ראשון) \u0003בשבת וטובלת ב\u0004יום \u0003חמישי בשבת.\u0004 וראייתו משום שכן מוצאים אנו בחפיפה \u0003ל\u0004טבילה של \u0003מוצאי שני ימים טובים של ראש השנה שלאחר השבת.\u0004 שבאופן זה של חפיפה כה מוקדמת לטבילה, מיום ראשון ליום חמישי — \u0003ליתא\u0004 \u0005[אינו,\u0006 אין לו מקום\u0005],\u0006 שהרי \u0003אפשר\u0004 לה שתהא \u0003חופפת בלילה וטובלת ב\u0004אותו ה\u0003לילה,\u0004 ולא תרחיק את החפיפה זמן כה רב עד לטבילה.","ובסיכומה של סוגיה זו מביאים ש\u0003דרש\u0004 (הורה ברבים) \u0003מרימר\u0004 כי \u0003הלכתא\u0004 \u0005[הלכה]\u0006 היא להחמיר \u0003כ\u0004שיטת \u0003רב חסדא,\u0004 האומר שאין להקדים את החפיפה כמה ימים לפני הטבילה. וכן הוא בטבילה הנעשית במוצאי ראש השנה שחל לאחר השבת, אין חופפים בערב שבת (כפי שאמר רב חסדא), אלא יש לחפוף בלילה ולטבול בלילה, \u0003וכ\u0004דרך ש\u0003מתרץ\u0004 \u0005[הסביר]\u0006 \u0003רב יימר.\u0004","מתוך שנידונו ענייני החפיפה, מביאים ש\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמי בית המדרש\u0005]:\u0006 \u0003אשה מהו\u0004 דינה \u0003שתחוף בלילה ותטבול בלילה?\u0004 ונחלקו בדבר חכמים, ש\u0003מר זוטרא אוסר\u0004 לעשות כן. וטעמו, שמתוך שממהרת היא לטבילתה, אינה חופפת היטב. \u0003ו\u0004אילו \u0003רב חיננא מ\u0004העיר \u0003סורא שרי\u0004 \u0005[מתיר]\u0006 לעשות כן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא לרב חיננא מסורא: לאו הכי הוה עובדא בדביתהו דאבא מרי ריש גלותא, דאיקוט\u0004 \u0005[האם לא כך היה מעשה באשתו של אבא מרי ראש הגולה, שהתקוטטה]\u0006 עם בעלה, ולא רצתה לטבול כשהגיע ליל טבילתה. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב נחמן בר יצחק לפיוסה\u0004 \u0005[לפייסה],\u0006 ולשדלה שתטבול. \u0003ואמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מאי איתיה השתא\u0004 \u0005[מה יש עכשיו]\u0006 עוד לעשות בענין זה? שאין טעם למהר אותי לטבול עתה."],["אלא \u0003תסגי אייתי\u0004 \u0005[תסתפק\u0006 בזה ש\u0005תבוא]\u0006 \u0003למחר\u0004 לדבר אתי בענין זה. \u0003ו\u0004מתוך דבריה \u0003ידע\u0004 רב נחמן בר יצחק \u0003מאי קאמרה ליה\u0004 \u0005[מה היא אומרת לו],\u0006 שרומזת שלא חפפה מבעוד יום, ואינה יכולה עתה לטבול. \u0003אמר\u0004 לה: האם \u0003דודי\u0004 \u0005[דודים]\u0006 \u0003חסרת\u0004 או שמא \u0003טשטקי\u0004 \u0005[כסאות]\u0006 \u0003חסרת\u0004 או \u0003עבדי\u0004 \u0005[עבדים]\u0006 \u0003חסרת\u0004 שכל אלה הינם מן הדברים הנצרכים לחפיפה?! ומכאן נלמד שאף לדעת רב נחמן בר יצחק מותרת החפיפה הנעשית בלילה לטבילה שתטבול באותו לילה.","ובענין חפיפה שאינה בסמוך לטבילה, \u0003דרש\u0004 (הורה ברבים) \u0003רבא:\u0004 \u0003אשה\u0004 שחל ליל טבילתה במוצאי שבת, הריהי \u0003חופפת בערב שבת וטובלת במוצאי שבת.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, והא\u0004 \u0005[והרי]\u0006 \u0003שלח רבין באגרתיה\u0004 \u0005[באגרתו]\u0006 כי \u0003אשה לא תחוף\u0004 (תחפוף) \u0003בערב שבת ותטבול במוצאי שבת,\u0004 אלא תחפוף במוצאי שבת, ותטבול בסמוך לחפיפתה.","\u0003ו\u0004הוסיף ואמר, \u0003תמה על עצמך\u0004 (יש מקום לתמוה): \u0003היאך\u0004 התירו חכמים לאשה הטובלת באחד מימות החול שתהא \u0003חופפת ביום וטובלת בלילה, הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 ש\u0003תכף לחפיפה\u0004 תהא ה\u0003טבילה, וליכא\u0004 \u0005[ואין כאן],\u0006 ולא התירו חכמים לעשות כן אלא בקושי רב, ומשום החשש שאם תצטרך לחפוף בלילה בסמוך לטבילתה, עלולה היא שלא לחפוף היטב. ואולם עיקר הדין הוא שתהא החפיפה סמוכה לטבילה. ולכך במקרה של הטובלת במוצאי שבת, יש להעמיד את הדין על עיקרו, ותהא חופפת בלילה.","ומסופר כי בעקבות הדברים הללו, \u0003הדר אוקי\u0004 \u0005[חזר,\u0006 והעמיד] \u0003רבא אמורא\u0004 (חכם העומד לפני רבו, וחוזר ומשמיע את דברי רבו לציבור) \u0003עליה\u0004 \u0005[עליו,\u0006 לפניו\u0005]\u0006 \u0003ודרש: דברים שאמרתי לפניכם, טעות הן בידי.\u0004 \u0003ברם כך אמרו משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: אשה לא תחוף בערב שבת ותטבול במוצאי שבת, ותמה על עצמך: היאך חופפת ביום וטובלת בלילה, הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 שתהא ב\u0003סמוך לחפיפה\u0004 ה\u0003טבילה, וליכא\u0004 \u0005[ואין כאן]!\u0006","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003אשה חופפת ביום וטובלת בלילה.\u0004 \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003אשה לא תחוף אלא בלילה.\u0004 ותוהים: \u0003(אלא) קשיא הלכתא אהלכתא\u0004 \u0005[קשה\u0006 מהלכה זו \u0005על הלכה\u0006 זו\u0005]!\u0006","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שחופפת ביום — כש\u0003אפשר\u0004 לעשות כן, וכגון שטובלת באחד מימות החול, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שחופפת בלילה — כש\u0003לא אפשר\u0004 לעשות כן, וכגון שטובלת במוצאי שבת, שכן אסורה החפיפה ביום השבת.","האשה הטמאה \u0003נדה שבדקה\u0004 את \u0003עצמה\u0004 ב\u0003יום\u0004 ה\u0003שביעי\u0004 לנדתה, ב\u0003שחרית\u0004 (תחילת) היום, \u0003ומצאה\u0004 שהיא \u0003טהורה,\u0004 ויכולה היא להיטהר בטבילה, \u0003ו\u0004אולם בזמן של \u0003בין השמשות\u0004 של היום השביעי שלפני טבילתה בלילה \u0003לא הפרישה\u0004 (לא בדקה את עצמה בבדיקה זו לקראת ההפרשה מטומאה לטהרה, לאחר שתטבול), וטבלה בלילה בזמן הראוי, בליל שמיני. \u0003ולאחר\u0004 כמה \u0003ימים בדקה\u0004 את עצמה \u0003ומצאה\u0004 שהיא \u0003טמאה\u0004 — \u0003הרי היא בחזקת טהורה\u0004 בכל הימים הללו מעת שטבלה ועד לזמן שמצאה שהיא טמאה, ולכך הטהרות שהתעסקה בהן בתקופה זו, אינן טמאות.","ואם \u0003בדקה\u0004 את \u0003עצמה ביום\u0004 ה\u0003שביעי\u0004 ב\u0003שחרית ומצאה\u0004 שהיא \u0003טמאה\u0004 (שעדיין היא רואה דם), \u0003ו\u0004בזמן \u0003בין השמשות לא הפרישה,\u0004 וטבלה בליל שמיני. \u0003ולאחר זמן בדקה\u0004 את עצמה \u0003ומצאה\u0004 שהיא \u0003טהורה\u0004 (שאין היא רואה דם) — \u0003הרי זו בחזקת טמאה.\u0004 שכן ראתה דם בבדיקה האחרונה שעשתה בימי נדתה, ויש חשש שהמשיכה לראות דם גם לאחר מכן (בימים הנקראים \"ימי זיבה\"), והריהי זבה, וטבילתה שטבלה בליל שמיני לא עלתה לה.","ומסבירים עתה כי מה ששנינו שזו שבדקה את עצמה בתחילת היום השביעי ולא ראתה דם, ולא בדקה שוב את עצמה בין השמשות, ולאחר כמה ימים ראתה דם, שהריהי בחזקת טהרה, ואין היא מטמאת את הטהרות שנגעה בהן — הרי זה אמור רק ביחס לימים שעברו מטבילתה והלאה, \u0003ו\u0004אולם הריהי \u0003מטמאה\u0004 את הטהרות שנגעה בהן בפרק הזמן של \u0003מעת לעת\u0004 (יממה) שקדמה לראייה זו של הדם, \u0003ומפקידה לפקידה\u0004 (מבדיקה לבדיקה), וכדינה של כל אשה הרואה דם, וכמבואר בתחילת המסכת. \u0003ואם יש לה וסת\u0004 ביום זה שבדקה עצמה ומצאה שראתה דם — \u0003דיה שעתה,\u0004 שאין היא מטמאת את הטהרות למפרע, אלא מכאן והלאה.","\u0003ור' יהודה אומר: כל\u0004 נדה ביום השביעי לנדתה \u0003שלא הפרישה בטהרה\u0004 (שלא בדקה עצמה בדיקה שלקראת הטבילה) בזמן ש\u0003מן המנחה ולמעלה\u0004 — \u0003הרי זו בחזקת טמאה,\u0004 ובכלל זה, אף האשה שבדקה את עצמה בתחילתו של היום השביעי ומצאה שהיא טהורה, ושלא כדעת התנא הראשון. \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 כי \u0003אפילו\u0004 אם \u0003בשנים\u0004 (ביום השני) \u0003לנדתה\u0004 היא \u0003בדקה ומצאה\u0004 שהיא \u0003טהורה\u0004 (שאינה רואה עוד דם), \u0003ובין השמשות לא הפרישה, ולאחר זמן בדקה ומצאה\u0004 שהיא \u0003טמאה\u0004 — \u0003הרי זו בחזקת טהורה.\u0004","שנינו במשנתנו דינה של זו שלא בדקה את עצמה לפני הטבילה בסופו של היום השביעי לנדתה (\"שלא הפרישה\"), ומביאים עוד בענין זה מחלוקת חכמים בדינה של זו שלא הפרישה, ועברו עליה שלושה ימים מאז הטבילה (שהם ימי זיבה, שהרואה בהם הריהי זבה). \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003רב אמר\u0004 כי הריהי \u0003זבה ודאי,\u0004 ונוהגים בה כל דיני הזבה, שצריכה לספור שבעה נקיים, ולהביא קרבן זבה. \u0003ו\u0004אילו \u0003לוי אמר\u0004 שאין היא אלא \u0003זבה\u0004 מן ה\u0003ספק.\u0004","ומבררים את מחלוקתם: \u0003אהייא\u0004 \u0005[על איזה\u0006 חלק ממשנתנו נאמרו הדברים\u0005]?\u0006 \u0003אילימא ארישא\u0004 \u0005[אם תאמר\u0006 ש\u0005על תחילתה]\u0006 של המשנה, בזו שבדקה עצמה בתחילת היום השביעי ומצאה שהיא טהורה — הלא \u0003\"הרי זו בחזקת טהורה\" קתני\u0004 \u0005[שונים אנו]\u0006 בה, שאין אנו חוששים בה שהמשיכה לראות דם, ואין היא זבה כלל.","\u0003אלא\u0004 יש לומר כי \u0003אסיפא\u0004 \u0005[על סופה]\u0006 של המשנה נאמרו דברי רב ולוי, בזו שבדקה עצמה בתחילת היום השביעי ומצאה שהיא עדיין רואה דם, ובסוף היום לא בדקה את עצמה, ולאחר כמה ימים בדקה את עצמה ומצאה שהיא טהורה — \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 ש\u0003ספק זבה\u0004 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 בה, ולכך אמרה המשנה שהריהי בחזקת טמאה, כדעתו של לוי, \u0003אלא זבה ודאי,\u0004 וכדעתו של רב, \u0003נמי\u0004 \u0005[גם כן]\u0006 אומרים אנו בזה? ו\u0003הרי בדקה\u0004 את עצמה עתה \u0003ומצאה\u0004 שהיא \u0003טהורה!\u0004","\u0003אלא\u0004 יש לומר \u0003כי איתמר\u0004 \u0005[כאשר נאמרה]\u0006 מחלוקת \u0003רב ולוי\u0004 — כ\u0003שמעתא באפי נפשה איתמר\u0004 \u0005[הלכה בפני עצמה נאמרה],\u0006 ולא כמוסבת על האמור במשנתנו, אלא באופן אחר נחלקו: \u0003נדה שבדקה עצמה ביום השביעי\u0004 ב\u0003שחרית ומצאה\u0004 שהיא \u0003טמאה, ובין השמשות לא הפרישה, ולאחר ימים בדקה ומצאה טמאה\u0004 — \u0003רב אמר:\u0004 הריהי \u0003זבה ודאי, ולוי אמר:\u0004 הריהי \u0003זבה ספק.\u0004","ומנמקים את דעותיהם, \u0003רב אמר:\u0004 הריהי \u0003זבה ודאי, כיון דמעיקרא\u0004 \u0005[שמתחילה,\u0006 בבדיקה שבדקה בבוקר יום השביעי\u0005]\u0006 \u0003נמצאת טמאה, ועכשיו\u0004 (כמה ימים לאחר הטבילה) גם כן \u0003נמצאת טמאה\u0004 — הרי זה מורה שלא הפסיקה לראות דם, וראתה איפוא בתקופת ימי הזיבה, ולכך הינה \u0003טמאה\u0004 כזבה מן ה\u0003ודאי.\u0004 \u0003ו\u0004אילו \u0003לוי אמר\u0004 כי אין היא אלא \u0003ספק זבה,\u0004 שכן \u0003אימר\u0004 \u0005[אמור,\u0006 יש מקום לומר\u0005]\u0006 כי היא \u0003פסקה\u0004 מלראות דם \u0003ביני וביני\u0004 \u0005[בין\u0006 בוקרו של יום השביעי לנדתה \u0005לבין\u0006 זמן זה שראתה בו עכשיו\u0005].\u0006"],["\u0003ו\u0004כדרך שאמרנו בהסבר דברי לוי, והאופן בו נאמרה דעתו זו, \u0003כן תנא\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 במפורש \u0003במתניתא\u0004 \u0005[בברייתא]\u0006 שסידר: בדקה עצמה ביום השביעי בתחילתו ומצאה בבדיקה זו שהיא עדיין רואה דם, ולא בדקה עצמה שוב בסוף היום לקראת טבילתה, וטבלה, ול\u0003אחר הימים\u0004 בדקה עצמה: \u0003בין\u0004 ש\u0003בדקה ומצאה\u0004 בבדיקה זו שהיא \u0003טהורה, בין\u0004 ש\u0003בדקה ומצאה\u0004 בבדיקה זו שהיא \u0003טמאה\u0004 — \u0003הרי זו ספק זבה.\u0004","\u0003ו\u0004עוד שנינו במשנתנו בזו שבדקה עצמה בתחילת היום השביעי לנדתה ומצאה טהורה, ולא חזרה ובדקה את עצמה בסוף היום לקראת הטבילה, וטבלה, ולאחר כמה ימים מצאה שהיא טמאה, שאמנם הריהי בחזקת טהרה, ואולם היא \u0003מטמאה\u0004 את הטהרות שנגעה בהן ב\u0003מעת לעת\u0004 שקדמה לראייתה האחרונה. הרי שהרואה דם בתקופת ימי זיבה (אחד עשר הימים הבאים לאחר ימי נדה) מטמאה מעת לעת. ומציעים: \u0003לימא תהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 ל\u0003רבא,\u0004 שכן \u0003אמר רבא\u0004 בהסבר דברי המשנה בפרק \"בנות כותים\" (לח,ב) האומרת כי בתקופת אחד עשר הימים שלאחר תקופת ימי נדה, הריהי בחזקת טהרה, שבאו הדברים \u0003לומר\u0004 לנו \u0003שאין האשה\u0004 הרואה דם \u0003מטמאה\u0004 את הטהרות שנגעה בהן ב\u0003מעת לעת\u0004 שלפני ראייתה, אם היתה ראייתה זו \u0003בתוך\u0004 תקופת \u0003ימי זיבתה!\u0004","ותוהים על עצם הקושיה: \u0003ולאו אותביניה\u0004 \u0005[והאם לא הקשינו\u0006 כבר\u0005]\u0006 \u0003לרבא חדא זימנא\u0004 \u0005[פעם אחת]\u0006 על דבריו ממקום אחר בדברי תנאים, וכמובא שם, ומה צורך להוסיף ולהקשות ממשנתנו? ומשיבים: \u0003הכי קאמרינן\u0004 \u0005[כך אנו אומרים,\u0006 זו כוונת הדברים\u0005]:\u0006 \u0003לימא תהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 ל\u0003רבא נמי מהא\u0004 \u0005[גם כן מזה]?\u0006","ודוחים: מכאן אין להביא ראיה כנגד רבא, שכן \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא\u0004 בהסבר דברי המשנה: \u0003כי קתני\u0004 \u0005[כאשר הוא\u0006 התנא במשנתנו \u0005שנה]\u0006 \u0003\"מטמאה מעת לעת\"\u0004 — אין דבריו מתייחסים לנאמר בתחילת משנתנו, אלא \u0003אריש פרקין קאי\u0004 \u0005[על תחילת פרקנו הוא עומד,\u0006 מתייחס\u0005],\u0006 על מה ששנינו שם בתינוקת שכבר \u0003ראתה\u0004 דם \u0003ו\u0004ב\u0003עודה בבית אביה,\u0004 שלדעת בית הלל נותנים לה רק את הלילה הראשון, שייחשב הדם שהיא רואה כדם בתולים ולא כדם נדה. ובאה משנתנו להורות כי מכאן ואילך, לכשתראה דם, הריהי מטמאה טהרות שנגעה בהן מעת לעת שלפני ראייתה, כשאר הנשים.","ונצרכה משנתנו להשמיענו כן, כיון ש\u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003כיון דמפסקי להו\u0004 \u0005[שמפסיקים להם]\u0006 \u0003ימים טהורין\u0004 (הלילה הראשון, שכל הדמים שרואה בו הינם טהורים), והרי איפוא עבר עליה פרק זמן מסויים בו אין היא חוששת לטומאתה, מעתה היה מקום לומר כי הריהי \u0003כ\u0004זו שנמצאת ב\u0003תחלת\u0004 עידן \u0003נדתה דמיא\u0004 \u0005[דומה,\u0006 נחשבת\u0005],\u0006 \u0003ולא תטמא מעת לעת,\u0004 וכדין הבתולה הרואה פעם ראשונה, שדיה שעתה, ואין היא מטמאה מעת לעת. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא במשנתנו \u0005משמיע לנו]\u0006 שאין אומרים כן בתינוקת זו, שהרי כבר ראתה.","עוד שנינו במשנתנו כי \u0003אם\u0004 לאשה זו שראתה דם בתקופת ימי זיבה (לאחר שבדקה עצמה ביום השביעי לימי נדתה ומצאה שהיא טהורה, ואולם בסוף היום השביעי לא בדקה) \u0003יש לה וסת\u0004 קבוע, וראתה בזמן וסת זה — אין היא מטמאה טהרות שנגעה בהן במעת לעת שקודם לראייתה, אלא דיה שעתה, ומטמאה רק מכאן ולהבא. ומציעים: \u0003נימא תהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על דברי \u0003רב הונא בר חייא\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל.\u0004 שכך \u0003אמר רב הונא בר חייא\u0004 ש\u0003אמר שמואל\u0004 כי דברי המשנה בפרק \"בנות כותים\" (לח,ב) שתקופת אחד עשר הימים שלאחר תקופת ימי נדה, הריהי בחזקת טהרה, באו \u0003לומר שאין האשה קובעת לה וסת\u0004 בראיות שראתה \u0003בימי זיבתה,\u0004 שכן הימים הללו מוגדרים כימים שבהם מסולקת האשה מראיית דמים. ואילו ממשנתנו רואים אנו שיש אופן לקביעת וסת בימי זיבה, ושלא כשמואל!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב הונא בר חייא\u0004 בתשובה: \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003אין אשה קובעת לה וסת בימי זיבתה\u0004 — אין הכוונה לענין שתקבע לה וסת על סמך ראיותיה בתקופת זיבה, אלא רק לענין עקירת וסת, שזו שראתה שלוש פעמים בתקופת ימי הזיבה — אין זו כוסת הקבוע, ולכן \u0003לא בעיא תלתא זימני למיעקר\u0004 \u0005[אינה צריכה שלוש פעמים\u0006 של ראיה בזמן אחר כדי \u0005לעוקרה],\u0006 ודי לה בראיה אחת, שתיעקר על ידה וסת זו. וטעם הדבר: שכן \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 כי בתקופת ימי זיבה \u0003דמיה מסולקין.\u0004 \u0003וכיון\u0004 ש\u0003דמיה מסולקין\u0004 בתקופה זו, אף יש לומר בה לענין טומאה כי \u0003דיה שעתה\u0004 שתטמא רק מכאן והלאה.","שנינו במשנתנו כי \u0003ר' יהודה\u0004 חולק על דברי התנא הראשון, ו\u0003אומר\u0004 שבכל מקרה שבו לא בדקה עצמה בסוף היום השביעי שלפני טבילתה, הריהי בחזקת טומאה (אף שבדקה עצמה בתחילתו ומצאה שהיא טהורה). ומביאים עוד בענין זה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו לו\u0004 חכמים לר' יהודה: \u0003אלמלי\u0004 (אם) היתה נקבעת הלכה שצריכה האשה הטובלת שיהיו \u0003ידיה מונחות בעיניה\u0004 (כינוי לבית הערוה, בלשון נקיה), לבדוק עצמה אם אמנם אינה רואה עוד דם, במשך \u0003כל\u0004 פרק הזמן של \u0003בין השמשות\u0004 (שהוא ספק יום ספק לילה). ואם בדקה עצמה רק לפני כן והסתפקה בכך, יש לחשוש בה שמא ראתה לאחר מכן — \u0003יפה אתה אומר,\u0004 שכל שלא בדקה את עצמה לפני סוף היום, הריהי בחזקת טומאה.","ואולם \u0003עכשיו\u0004 שההלכה היא שדי שתבדוק עצמה בחלקו האחרון של היום — לשיטתך, \u0003אימר\u0004 \u0005[אמור]\u0006 שיש לחשוש כי מיד \u0003עם סלוק ידיה ראתה\u0004 דם, ותהא טמאה. שהרי \u0003מה לי\u0004 שיהא כך הדין בזו ש\u0003הפרישה בטהרה ב\u0004יום ה\u0003שביעי\u0004 לימי ספירתה \u0003מן המנחה ולמעלה\u0004 (שנהגה כהלכה וכראוי), שהריהי בחזקת טהרה, \u0003מה לי\u0004 שיהא כך הדין בזו ש\u0003הפרישה בטהרה ב\u0004יום ה\u0003ראשון\u0004 לימי ספירתה, שהריהי בחזקת טומאה.","ותוהים על דברי חכמים: איך תועיל לה הבדיקה \u0003ב\u0004יום ה\u0003ראשון\u0004 לימי ספירתה, \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 שאפשרי הדבר?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[והרי\u0006 כך אכן \u0005שנויה\u0006 ברייתא\u0005]\u0006 האומרת כן, שכך \u0003אמר רבי: שאלתי את ר'\u0004 \u0003יוסי ור' שמעון כשהיו מהלכים בדרך:\u0004 ה\u0003נדה שבדקה עצמה\u0004 ב\u0003יום\u0004 ה\u0003שביעי\u0004 לספירתה, ב\u0003שחרית\u0004 היום, \u0003ומצאה\u0004 שהיא \u0003טהורה\u0004 (נקיה מראיית דם), \u0003ו\u0004אולם \u0003בין השמשות\u0004 היא \u0003לא הפרישה\u0004 (לא בדקה עצמה לפני טבילה), \u0003ולאחר הימים בדקה\u0004 עצמה \u0003ומצאה\u0004 שהיא \u0003טמאה, מהו\u0004 דין הטהרות שנגעה בהם במשך התקופה שלאחר טבילתה ועד לזמן שראתה דם.","ו\u0003אמרו לו\u0004 ר' יוסי ור' שמעון בתשובה כי \u0003הרי\u0004 אשה \u0003זו\u0004 עומדת \u0003בחזקת טהרה.\u0004 חזר רבי ושאל אותה שאלה בדינה של זו שבדקה עצמה לא ביום השביעי לימי נדתה אלא ביום ה\u0003ששי\u0004 בלבד, ולא חזרה ובדקה בסוף היום השביעי לפני טבילתה, וכן מהו דינה של זו שבדקה עצמה ביום ה\u0003חמישי\u0004 בלבד, וכן של זו שבדקה עצמה רק ביום ה\u0003רביעי,\u0004 וכן ביום ה\u0003שלישי,\u0004 וכיוצא בו אף בזו שבדקה עצמה רק ביום ה\u0003שני, מאי\u0004 \u0005[מה]\u0006 דינה, האם היא עומדת בחזקת טהרה או בחזקת טומאה? ו\u0003אמרו לו\u0004 ר' יוסי ור' שמעון בתשובה כי \u0003לא שנא\u0004 \u0005[אין\u0006 זה \u0005משנה],\u0006 ובכל האופנים הללו הריהי עומדת בחזקת טהרה.","והוסיף רבי כי בדינה של זו שבדקה עצמה רק \u0003ב\u0004יום ה\u0003ראשון לא שאלתי\u0004 אותם, \u0003וטעיתי\u0004 בכך \u0003שלא שאלתי\u0004 אותם. שכן אילו שאלתים, היו מטהרים אף בזו, והיתה זו הלכה הבאה מפיהם של ר' יוסי ור' שמעון. שכך נראה, שאף בבודקת עצמה רק ביום הראשון ומצאה שהיא טהורה, שהריהי בחזקת טהרה. וסברה היא: \u0003אטו כולהו לאו\u0004 \u0005[וכי\u0006 בכל שבעת ימי נדתה \u0005כולם האם לא]\u0006 \u0003בחזקת טומאה קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 שהרי בזמן זה מוחזקת היא כמי שרואה דם. \u0003ו\u0004בכל זאת, קבעו ר' יוסי ור' שמעון הלכה כי \u0003כיון\u0004 ש\u0003פסק\u0004 הדם, שכך נמצא בבדיקה שבדקה עצמה בתוך שבעת הימים הללו — מניחים אנו שהדם כבר \u0003פסק,\u0004 ועל סמך זה מעמידים אנו אותה בחזקת טהרה. ואף בזו שבדקה עצמה רק ביום ה\u0003ראשון נמי\u0004 \u0005[גם כן],\u0006 נאמר כי \u0003כיון\u0004 ש\u0003פסק\u0004 הדם — הריהו בחזקה כמי שכבר \u0003פסק,\u0004 ונעמידנה בחזקת טהרה.","\u0003ו\u0004תוהים: \u0003מעיקרא, מאי סבר\u0004 \u0005[מתחילה,\u0006 כאשר לא רצה רבי לשאול את ר' יוסי ור' שמעון לגבי בדיקת יום ראשון, \u0005מה סבור היה]?\u0006 ומשיבים: סבור היה כי אין מקום להעמידה בחזקת טהרה על סמך בדיקה של יום הראשון בלבד, שאין בדיקה זו מלמדת דבר, \u0003הואיל ו\u0004היום הראשון לראייתה \u0003הוחזק\u0004 ב\u0003מעין פתוח,\u0004 ששופעת דם היא.","\u0003הזב והזבה ש\u0004צריכים הם לספור שבעה ימי נקיות לטהרתם, ובכל יום מאותם שבעה ימים לבדוק את עצמם, ו\u0003בדקו עצמן ביום\u0004 ה\u0003ראשון\u0004 משבעת ימי נקיים, \u0003ומצאו טהור\u0004 (שנקיים הם), \u0003ו\u0004כן בדקו עצמם \u0003ביום השביעי\u0004 מימי שבעת ימי הנקיים, \u0003ו\u0004אף בו \u0003מצאו טהור, ו\u0004אולם ב\u0003שאר ימים שבינתיים לא בדקו\u0004 את עצמם — \u0003ר' אליעזר אומר: הרי הן בחזקת טהרה, ר' יהושע אומר: אין להם\u0004 מנין שלם של שבעה ימי נקיות, \u0003אלא\u0004 יומיים, ה\u0003יום ראשון ו\u0004ה\u0003יום שביעי בלבד,\u0004 ועליהם להוסיף ולמנות חמישה ימי נקיות כדי שיהיו להם שבעה ימים שלמים. \u0003ר' עקיבא אמר: אין\u0004 עולה \u0003להם אלא\u0004 ספירת \u0003יום שביעי בלבד,\u0004 והריהם צריכים לספור עוד ששה ימי נקיות.","\u0003תניא,\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר לו ר' אליעזר לר' יהושע: לדבריך\u0004 שגם היום הראשון נחשב להם כיום בדיקה, ובנוסף לו גם היום השביעי, נמצא כי \u0003אתה מונה בסירוגין\u0004 (בדילוגים), \u0003ו\u0004הרי \u0003התורה אמרה\u0004 בדין הטהרה מטומאת הזיבה \"ואם טהרה מזובה וספרה לה שבעת ימים ו\u0003אחר תטהר\"\u0004 (ויקרא טו, כח), ומן ההדגשה \u0003אחר\u0004 למדים אנו שיהא זה \u0003אחר ל\u0004כל שבעת ימי הנקיות \u0003כולן,\u0004 שיהיו אלה ימי נקיות ברצף, \u0003שלא תהא טומאה מפסקת ביניהן!\u0004","\u0003אמר לו ר' יהושע\u0004 בדחייית דבריו: \u0003ו\u0004האם \u0003אתה אי\u0004 (אין) \u0003אתה מודה בזב שראה קרי\u0004 בתוך שבעת ימי נקיותו, \u0003ובנזיר\u0004 המונה שלושים ימי נזירותו ואסור אז מלהיטמא למת, \u0003שהילך\u0004 במקום \u0003סככות\u0004 (אילן שענפיו סוככים על הדרך) \u0003ופרעות\u0004 (גדר שאבניה יוצאות אל מעל לדרך), שיש בהם ספק טומאת אוהל, \u0003ש\u0004זה וזה מדלג במניינו על אותו יום שהילך בו במקומות הללו, והריהו ממשיך הלאה בספירתו, ונמצא שהוא \u0003מונה בסירוגין? ו\u0004אף ש\u0003התורה אמרה\u0004 בדינו של הנזיר שנטמא למת (בוודאות) בתוך שלושים ימי נזירותו \u0003\"והימים הראשנים יפלו\u0004 כי טמא נזרו\" (במדבר ו, יב) — הרי מכאן ראיה כי אף במקום שאמרה תורה שיש למנות ברצף, ניתן למנות גם בסירוגין.","ומסבירים: \u0003ור' אליעזר,\u0004 מה משיב על טענתו זו של ר' יהושע? \u0003בשלמא התם\u0004 \u0005[זה נוח שם,\u0006 בזב שראה קרי\u0005],\u0006 שהריהו מונה בדילוג אותו יום שראה קרי — טעם יש בדבר: שכן בטומאתו של הזב \"זאת תורת הזב ואשר תצא ממנו שכבת זרע \u0003לטמאה בה\"\u0004 (ויקרא טו, לב) \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 וללמדנו בא הכתוב: \u0003ש\u0004שכבת הזרע של בעל הקרי \u0003אינה סותרת\u0004 את כל מנין שבעת ימי נקיותו מזיבה, \u0003אלא\u0004 רק את \u0003יומה\u0004 בלבד. \u0003ואי\u0004 \u0005[ואם]\u0006 נאמר שראוי שאף הרואה קרי יסתור את כל מניינו, ו\u0003משום איחלופי\u0004 \u0005[החלפה]\u0006 שעלולים להחליף בין קרי לזיבה, ויבואו שלא לסתור אף בראיית זיבה — אין לומר כן, כי \u0003זב בבעל קרי לא מיחלף\u0004 \u0005[אינו מתחלף].\u0006","וכן במקרה זה של ה\u0003נזיר שהילך על גבי סככות ופרעות נמי\u0004 \u0005[גם כן],\u0006 אין מקום לומר שיסתור את כל מנין הימים עד אז, כי \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 בסתירת מנין ימי נזירות, טומאת \u0003אהל מעליא בעינן\u0004 \u0005[מעולה,\u0006 ודאית, \u0005מצריכים אנו],\u0006 וזה שהלך במקום סככות ופרעות אינו נטמא מן התורה. \u0003ורבנן\u0004 \u0005[ו\u0006רק \u0005חכמים]\u0006 \u0003הוא דגזור\u0004 \u0005[שגזרו]\u0006 עליו טומאה, ולכך אין ימי נזירותו נסתרים. \u0003ו\u0004אין מקום לומר שיגזרו אף על טומאה מדברי חכמים שתסתור את ימי הנזירות, מפני החשש שמא יבואו אנשים שלא לסתור ימי נזירות אף בטומאה שמן התורה — שכן \u0003רבנן בדאורייתא לא מיחלף\u0004 \u0005[\u0006דבר שהוא \u0005מדברי חכמים ב\u0006דבר שהוא \u0005מדין תורה אינו מתחלף]\u0006 לאנשים.","\u0003אבל הכא\u0004 \u0005[כאן,\u0006 בדין הזב והזבה שלא בדקו בין הימים\u0005],\u0006 \u0003אי חיישינן\u0004 \u0005[אם חוששים אנו]\u0006 שלא למנות בכלל שבעת ימי נקיות את חמשת הימים שלא בדקה בהם, ומפני האפשרות \u0003דלמא חזאי\u0004 \u0005[שמא ראתה]\u0006 בהם, שכן \u0003בספק\u0004 הם הימים הללו אם ראתה בהם, ואולם את היום הראשון שבדקה בו כן נמנה בכלל שבעת ימי הנקיות (וכשיטת ר' יהושע) — מעתה \u0003אתי לאיחלופי\u0004 \u0005[יבואו\u0006 אנשים \u0005להחליף]\u0006 ספק \u0003בודאי,\u0004 וגם במקרה שראו הזב והזבה בוודאות בתוך חמשת הימים הללו, יאמרו כי כמו שהיום הראשון מצטרף למנין שבעת ימי הנקיות, אף חמשת הימים שביניהם נמנים.","ומסכמים בהכרעת מחלוקתם זו של ר' אליעזר ור' יהושע ור' עקיבא \u0003תני\u0004 \u0005[שנינו]:\u0006 \u0003ר' יוסי ור' שמעון אמרי\u0004 \u0005[אומרים]:\u0006 \u0003נראין דברי ר'\u0004 \u0003אליעזר מדברי ר'\u0004 \u0003יהושע, ודברי ר'\u0004 \u0003עקיבא מדברי כולן, אבל הלכה\u0004 היא \u0003כר' אליעזר.\u0004","ומביאים עוד לענין שיטתו של ר' אליעזר בדין הזב והזבה שלא בדקו עצמם בכל יום משבעת ימי נקיותם. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמי בית המדרש\u0005]\u0006 שאלה זו: \u0003הזב והזבה שבדקו עצמן\u0004 ב\u0003יום\u0004 ה\u0003ראשון\u0004 לשבעת ימי נקיותם ומצאו שהם טהורים מלראות, \u0003ו\u0004כן בדקו את עצמם עוד ב\u0003יום\u0004 ה\u0003שמיני, ו\u0004אף בבדיקה זו \u0003מצאו טהור, ו\u0004אולם ב\u0003שאר הימים\u0004 של שבעת ימי הנקיות \u0003לא בדקו\u0004 את עצמם,"],["\u0003ל\u0004שיטת \u0003ר' אליעזר\u0004 שזבים שבדקו עצמם ביום הראשון וביום השביעי לימי נקיותם ומצאו שהם טהורים, נחשבים שהיו כל הימים בחזקת טהרה, \u0003מהו\u0004 הדין במקרה זה שלא בדקו ביום השביעי אלא ביום השמיני? ומציגים את צדדי הבעיה: האם לשיטת ר' אליעזר בדיקה שהיתה ב\u0003תחלתן\u0004 של שבעת ימי הנקיות (ביום הראשון) \u0003ו\u0004בדיקה שהיתה ב\u0003סופן\u0004 (ביום השביעי) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 כדי לקבוע שכל הימים הם בחזקת טהרה, \u0003ו\u0004אילו \u0003הכא\u0004 \u0005[כאן]\u0006 בנדון בעייתנו — בדיקה ב\u0003תחלתן\u0004 אמנם \u0003איכא\u0004 \u0005[יש],\u0006 אבל בדיקה ב\u0003סופן ליכא\u0004 \u0005[אין],\u0006 שהרי בסוף (ביום השביעי) לא היתה בדיקה, ולכך לא יאמר ר' אליעזר במקרה זה שכל הימים בחזקת טהרה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 יש לומר לשיטת ר' אליעזר כי די בבדיקה ב\u0003תחלתן\u0004 של שבעת הימים, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003שאין\u0004 בדיקה ב\u0003סופן\u0004 ולכך אף כאן יאמר ר' אליעזר שכל הימים בחזקת טהרה.","ונחלקו חכמים בהכרעת הבעייה, שכן \u0003אמר רב\u0004 כי כך \u0003היא\u0004 שיטת ר' אליעזר כשהיתה בדיקה בתחילתן ובסופן, וכך \u0003היא\u0004 שיטתו אף כשהיתה בדיקה רק ב\u0003תחלתן\u0004 של שבעת הימים \u0003אף על פי שאין\u0004 בדיקה ב\u0003סופן.\u0004 \u0003ו\u0004אילו \u0003ר' חנינא אמר\u0004 כי לשיטת ר' אליעזר שתהא בדיקה הן ב\u0003תחלתן\u0004 של שבעת הימים \u0003ו\u0004הן ב\u0003סופן בעינן\u0004 \u0005[צריכים אנו],\u0006 וכיון ש\u0003הכא\u0004 \u0005[כאן]\u0006 — בדיקה ב\u0003תחלתן\u0004 אמנם \u0003איכא\u0004 \u0005[יש],\u0006 אבל בדיקה ב\u0003סופן ליכא\u0004 \u0005[אין],\u0006 ולכך לא יאמר ר' אליעזר במקרה זה שכל הימים בחזקת טהרה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעתו של רב ממה ששנינו: \u0003ושוין\u0004 (מסכימים) חכמים \u0003ב\u0004דינו של ה\u0003זב וב\u0004דינה של ה\u0003זבה שבדקו עצמן\u0004 ב\u0003יום\u0004 ה\u0003ראשון ו\u0004ב\u0003יום\u0004 ה\u0003שמיני ומצאו טהור\u0004 — \u0003שאין\u0004 מחשבים \u0003להם\u0004 במנין שבעת ימי נקיים \u0003אלא\u0004 יום ה\u0003שמיני בלבד.\u0004 ויש לברר: \u0003מאן\u0004 \u0005[מי הם]\u0006 אלה החכמים החולקים בענין אחר, ואולם הריהם \u0003שוין\u0004 בענין זה? \u0003לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ל\u0003ר' אליעזר ור' יהושע,\u0004 החלוקים במקרה שבדקו ביום הראשון וביום השביעי, ואולם במקרה זה שלפנינו שניהם (ואף ר' אליעזר בכלל) מסכימים (\"שוין\") שאין הימים שלפני הבדיקה האחרונה עולים למנין שבעת ימי נקיים. הרי שלשיטת ר' אליעזר צריכים בדיקה הן בתחילה והן בסוף שבעת הימים הנקיים כדי להחשיב את כל הימים בחזקת טהרה, ושלא כרב!","ומשיבים: \u0003לא,\u0004 הכוונה היא ל\u0003ר' יהושע ור' עקיבא,\u0004 שבמקרה זה מודה ר' יהושע לר' עקיבא שאין מחשיבים את היום הראשון לכלל מנין שבעת ימי נקיות. ואולם לדעת ר' אליעזר אף באופן זה מחשיבים אנו את כל הימים בחזקת טהרה.","מתוך שהובאו דברי רב לענין תחילתם אף על פי שאין סופם, מביאים עוד מדבריו בענין דומה. שכן \u0003אמר רב ששת,\u0004 \u0003אמר רב ירמיה בר אבא, אמר רב: נדה שהפרישה בטהרה\u0004 (שבדקה עצמה לקראת טבילה, בהפסק טהרה) \u0003ב\u0004יום ה\u0003שלישי שלה\u0004 — הריהי \u0003סופרתו ל\u0004יום זה בכלל \u0003מנין שבעה נקיים.\u0004","ותוהים על הדברים: בטומאת \u0003נדה,\u0004 \u0003ספירה\u0004 של שבעה נקיים \u0003למה לה,\u0004 שהרי דין ספירת שבעה נקיים נאמר רק בזבה? ומתקנים: \u0003אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור]\u0006 שאמר רב: \u0003זבה שהפרישה בטהרה ב\u0004יום ה\u0003שלישי שלה\u0004 — הריהי \u0003סופרתו ל\u0004יום זה בכלל \u0003מנין שבעה נקיים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לרב ירמיה בר אבא\u0004 בתמיהה על הלכה זו שמסר בשמו של רב: \u0003רב ככותאי\u0004 \u0005[ככותים]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[את שמועתו,\u0006 הלכתו\u0005]\u0006 זו! \u0003דאמרי\u0004 \u0005[ש\u0006כן הכותים \u0005אומרים]\u0006 כי שבאותו \u0003יום שפוסקת בו\u0004 לאחר שראתה זיבה בשלושה ימים רצופים שלאחר שבעת ימי נדתה, וביניהם יום זה, היא \u0003סופרתו למנין שבעה\u0004 ימים של זיבה, ואינה צריכה לספור שבעה ימים שלמים לזיבה.","השיב לו רב ירמיה בר אבא בהסבר דברי רב: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 שהריהי סופרת שבעה ימים — הרי זה \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004יום \u0003שלישי\u0004 זה שבו עשתה הפסק טהרה. שאל רב ששת: אם כוונת דברי רב שמונה \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004יום ה\u0003שלישי\u0004 שבו עשתה הפסק טהרה — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ואין צורך להשמיעו! השיב לו רב ירמיה בר אבא: \u0003לא צריכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר אלא ב\u0003כגון\u0004 שלאחר הפסק הטהרה שעשתה ביום השלישי, שוב \u0003לא בדקה\u0004 את עצמה \u0003עד\u0004 ליום ה\u0003שביעי,\u0004","\u0003ואשמועינן\u0004 \u0005[והשמיענו]\u0006 רב שתי הלכות: \u0003התם\u0004 \u0005[שם,\u0006 בסוגיה הקודמת\u0005]\u0006 — השמיענו רב שדי בבדיקה ב\u0003תחלתן\u0004 של שבעת ימי נקיות, \u0003אף על פי שאין\u0004 בדיקה ב\u0003סופן,\u0004 כדי להחשיב את כל הימים בחזקת טהרה. \u0003והכא קא משמע לן\u0004 \u0005[וכאן הוא,\u0006 רב \u0005משמיע לנו]\u0006 — שדי בבדיקה ב\u0003סופן\u0004 של שבעת ימי נקיות, \u0003אף על פי שאין\u0004 בדיקה ב\u0003תחלתן.\u0004","כי \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]\u0006 שדווקא בבדיקה ב\u0003תחלתן אף על פי שאין\u0004 ב\u0003סופן הוא דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 שכל הימים בחזקת טהרה, ומשום \u0003דאוקמינהו אחזקייהו\u0004 \u0005[שהעמידום על חזקתם],\u0006 שמאחר שנמצאה בבדיקת היום הראשון שאינה רואה דם, מחזיקים אנו אותה כן אף בימים שלא בדקה בהם. \u0003אבל\u0004 בבדיקה ב\u0003סופן אף על פי שאין תחלתן\u0004 — \u0003לא\u0004 אומרים כך. לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו],\u0006 שכך הלכה אף באופן זה.","ושואלים: \u0003איני\u0004 \u0005[האמנם]\u0006 כך היא שיטת רב שדי בבדיקה ביום הראשון או ביום השביעי בלבד, ואין צורך בבדיקה בכל שבעת הימים שיהיו ספורים לפנינו, \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, והביא מדברים שנאמרו בבית המדרש, \u0003אמר: מתיב\u0004 \u0005[הקשה]\u0006 \u0003ר' יוסי בר' חנינא\u0004 על שיטת ר' יהושע בן לוי האומר (לעיל כט,א) שאשה הרה שהפילה, ואין היא יודעת מה הפילה, אם ולד של ממש או רוח שמביאה קרבן יולדת (ומשום שרוב הנשים ההרות מעוברות בולד של ממש), מדינה של אשה ה\u0003טועה\u0004 שיצאה מביתה כשהיא הרה, ושבה לאחר מכן שלא בהריון, ואין ידוע אם ילדה ולד או רוח, ואפילו היה זה ולד האם היה זה בן או בת, והרי הדברים נוגעים למספר ימי טהרתה. ונקבע בה שאין לה ימי טוהר כלל, שמא לא ילדה ולד אלא הפילה רוח. הרי שאין הולכים אחר הכלל שרוב הנשים ההרות יולדות ולד.","\u0003ו\u0004ציין רבין כי \u0003לא ידענא מאי תיובתיה\u0004 \u0005[איני יודע מה קושייתו],\u0006 שהרי ההסבר לכך שאין נותנים לה ימי טוהר אינו משום שמסופקים אנו מה ילדה, אלא משום שאין אנו יודעים מתי ילדה אותו הולד, ואולי כבר עברו ימי הטוהר. \u0003דקיימא לן\u0004 \u0005[ש\u0006מקובל \u0005לנו],\u0006 שכך סיכמו בסוגיית הגמרא (לעיל כט,ב) בבירור דברי הברייתא כי \u0003שבוע קמא דאתיא לקמן\u0004 \u0005[ראשון שבאה לפנינו]\u0006 אשה זו, שאנו מסופקים לענין טומאתה — \u0003בלילותא מטבלינן לה\u0004 \u0005[ב\u0006כל \u0005הלילות\u0006 של שבוע זה, \u0005אנו מטבילים אותה],\u0006 כטבילת הנדה והיולדת (שהיא בלילה), שהרי בכל לילה ולילה אפשר שבו הסתיימו ימי טומאת לידתה, וטבילה בזמנה הריהי מצוה. ואולם \u0003ביממא לא מטבלינן לה\u0004 \u0005[בימים\u0006 של שבוע זה, \u0005אין אנו מטבילים אותה],\u0006 אף שיתכן שביום זה הסתיימה לה טומאת הזיבה והזבה טובלת ביום, שכן עדיין לא ספרה אשה זו שבעה ימים נקיים.","\u0003ו\u0004אולם \u0003אי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר, כשיטת רב, ש\u0003לא בעינן\u0004 \u0005[אין צריכים]\u0006 שיהיו כל שבעת ימי הנקיות \u0003ספורין לפנינו\u0004 — \u0003ביממא נמי נטבלינה\u0004 \u0005[ביום גם כן נטביל אותה],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003יולדת זכר בזוב היא, ועבדה\u0004 \u0005[ועשתה]\u0006 \u0003לה\u0004 כבר שבעה ימים ה\u0003ספורין\u0004 שלא בפנינו! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו ימים ה\u0003ספורין בפנינו!\u0004","ודוחים: \u0003ולאו מי אוקימנא\u0004 \u0005[והאם לא העמדנו]\u0006 אותה ברייתא \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003ספורין לפנינו?!\u0004 ורב הלא אמר את דבריו לשיטת ר' אליעזר, הסבור שאין צורך שיהיו שבעת הימים ספורים לפנינו.","למעלה למדנו כי לשיטת חכמים אין צריכים להיות שבעת ימי הנקיות ספורים לפנינו דווקא. ומבררים את דעת חכמים: \u0003ומנא תימרא דלרבנן לא בעינן\u0004 \u0005[ומנין תאמר שלחכמים אין אנו צריכים]\u0006 שיהיו שבעת ימי נקיות \u0003ספורין לפנינו\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האשה ה\u0003טועה,\u0004 שאינה יודעת אם היא בתקופת ימי נדה, או בתקופת ימי זיבה, \u0003ש\u0004באה לפנינו ביום ו\u0003אמרה \"יום אחד טמא\u0004 (טומאת דם) \u0003ראיתי\",\u0004 ולא ציינה מתי היה יום זה שראתה בו — כיון שאין אנו יודעים מתי ראתה, הרינו \u0003מטבילין אותה תשע טבילות,\u0004","\u0003שבע\u0004 מהן \u0003ל\u0004טומאת \u0003נדה\u0004 (שבכל לילה בשבוע זה יש לומר שבו הסתיימו ימי נדתה), כשהראשונה כבר בלילה זה, בטבילת נדה שהיא בלילה (שמא ראתה דם נדה לפני שבעה ימים ובלילה זה כלו שבעת ימי נדתה) \u0003ותרי\u0004 \u0005[ושתי]\u0006 טבילות אותן היא טובלת ביום, \u0003ל\u0004טומאת \u0003זיבה,\u0004 אחת ביום שבאה לפנינו (שמא אתמול ראתה, ובתקופת ימי זיבה היא, והריהי איפוא זבה קטנה, הטובלת למחרת יום ראייתה), והאחת למחרת היום שבאה לפנינו (שמא ביום זה שבאה לפנינו הוא שראתה ראיה של זבה קטנה). ואם באה לפנינו (בין ביום, בין בלילה) ואמרה \u0003\"בין השמשות טמא ראיתי\"\u0004 — \u0003מטבילין אותה אחת עשרה טבילות.\u0004","ותוהים: \u0003אחת עשרה מאי עבידתייהו\u0004 \u0005[מה מעשיהן,\u0006 מהו עניינן\u0005]?\u0006 שהרי גם כשאמרה \"יום אחד טמא ראיתי\" ואין אנו יודעים בה אם בימי נדה אם בימי זיבה היא, הריהי טובלת תשע טבילות, וכיון שראתה בבין השמשות ויש להסתפק ביומיים — תטבול עשר טבילות! \u0003אמר רב ירמיה מדפתי:\u0004 מדובר \u0003כגון שבאת\u0004 (באה) \u0003לפנינו בין השמשות,\u0004 ואומרת שבין השמשות ראתה, שאמנם אפשר שמתכוונת לבין השמשות שבעבר, ואולם אפשר גם שכוונתה לבין השמשות של עתה, שהריהו ספק יום ספק לילה.","\u0003ו\u0004באופן שכזה \u0003הויין תמני\u0004 \u0005[הריהן שמונה]\u0006 טבילות \u0003לנדה,\u0004 שהרי אפשרי הדבר שראתה בזמן שהוא כבר לילה, ונצרכת היא איפוא לטבילה נוספת לטומאת נדתה, \u0003ו\u0004כן נצרכת משום כך גם לטבילה נוספת, והרי אלה \u0003תלת\u0004 \u0005[שלוש]\u0006 טבילות \u0003לזיבה.\u0004","ואם אשה זו הטועה בדעתה באה לפנינו ואמרה \u0003\"לא ראיתי כל עיקר\"\u0004 — \u0003מטבילין אותה חמש עשרה טבילות,\u0004 שהן שמונה טבילות בלילה לטומאת נדתה, ושבע טבילות ביום לטומאת זיבתה. על הלכה זו שבברייתא \u0003אמר רבא: האי דינא דלא דינא, דייני\u0004 \u0005[דין כמו זה שאינו דין, דנים]\u0006 \u0003ב\u0004מקום הנקרא \u0003גלחי.\u0004 שבאותו מקום היו דנים במידת סדום. שכך אמרו שם: מי \u0003דאית ליה תורא\u0004 \u0005[שיש לו שור]\u0006 — \u0003לירעי חד יומא\u0004 \u0005[שירעה יום אחד]\u0006 את בהמות כל אנשי העיר. ומי \u0003דלית ליה תורא\u0004 \u0005[שאין לו שור]\u0006 — \u0003לירעי תרי יומי\u0004 \u0005[שירעה שני ימים]\u0006 את בהמות אנשי העיר.","ומסופר כי \u0003אתרמי להו יתמא בר ארמלתא\u0004 \u0005[הזדמן להם\u0006 באותו מקום \u0005יתום בן אלמנה],\u0006 שלא היה לו שור משלו, ו\u0003יהבי ליה תורי\u0004 \u0005[נתנו לו\u0006 אנשי העיר את \u0005השוורים\u0006 שלהם לרעותם שני ימים\u0005],\u0006 \u0003אזל נכסינהו\u0004 \u0005[הלך\u0006 אותו יתום ו\u0005שחטם],\u0006 \u0003אמר להו\u0004 \u0005[להם,\u0006 לבעלי השוורים\u0005]:\u0006 זה \u0003דאית ליה תורא\u0004 \u0005[שיש לו שור]\u0006 — \u0003לשקול חד משכא\u0004 \u0005[שיקח עור אחד],\u0006 זה \u0003דלית ליה תורא\u0004 \u0005[שאין לו שור]\u0006 — \u0003לשקול תרי משכי\u0004 \u0005[שיקח שני עורות].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 אנשי העיר לאותו יתום: \u0003מאי האי דקאמרת\u0004 \u0005[מה הוא זה שאמרת]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003סוף דינא\u0004 \u0005[דין]\u0006 \u0003כתחלת דינא\u0004 \u0005[דין].\u0006 כשם שב\u0003תחלת דינא\u0004 \u0005[הדין,\u0006 לענין חובת רעיית השוורים\u0005],\u0006 \u0003לאו מאן דלית ליה\u0004 \u0005[האם לא\u0006 קבעתם כי \u0005מי שאין לו\u0006 שוורים\u0005]\u0006 \u0003עדיף\u0004 על זה שיש לו שוורים, שהרי זה שיש לו שוורים רועה יום אחד, ואילו זה שאין לו שוורים הריהו רועה יומיים? \u0003סוף דינא נמי\u0004 \u0005[הדין,\u0006 לענין דרך חלוקת העורות, \u0005גם כן]\u0006 יש לקבוע כי \u0003מאן דלית ליה\u0004 \u0005[מי שאין לו]\u0006 \u0003עדיף\u0004 על מי שיש לו!","הוסיף רבא ואמר: \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין טבילותיה של זו, יש לומר באופן זה, \u0003ומה היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003אמרה \"ראיתי\u0004 טומאה יום אחד\" או שאמרה \"בין השמשות ראיתי טומאה\" — \u0003סגי\u0004 \u0005[די]\u0006 \u0003לה אי\u0004 \u0005[או]\u0006 \u0003בתשע טבילות\u0004 (במקרה הראשון) \u0003אי\u0004 \u0005[או]\u0006 \u0003באחת עשרה טבילות\u0004 (במקרה השני), מעתה \u0003היכא דקאמרה איהי\u0004 \u0005[היכן שאמרה היא]\u0006 \u0003\"לא ראיתי\u0004 כל עיקר\" \u0003בעיא\u0004 \u0005[צריכה]\u0006 היא לטבול \u0003חמש עשרה טבילות?\u0004","\u0003אלא אימא הכי\u0004 \u0005[אמור,\u0006 תקן \u0005כך]\u0006 את לשון הברייתא: אשה הטועה הבאה לפנינו ואומרת \u0003\"ראיתי, ואיני יודע כמה\u0004 ימים היו אלה ש\u0003ראיתי\u0004 בהם, וכן איני יודעת \u0003אי\u0004 \u0005[אם]\u0006 \u0003ב\u0004תקופת \u0003ימי נדה ראיתי\u0004 ראייה זו, \u0003או ב\u0004תקופת \u0003ימי זיבה ראיתי\"\u0004 — \u0003מטבילין אותה חמש עשרה טבילות.\u0004 ומפרטים את סדר טבילותיה: אם \u0003אתאי קמן ביממא\u0004 \u0005[באה לפנינו ביום]\u0006 — \u0003יהבינן\u0004 \u0005[נותנים אנו]\u0006 \u0003לה\u0004 לטבול החל מלילה זה \u0003שב\u0004\u0005[שבע]\u0006 טבילות בלילה, \u0003ל\u0004טומאת \u0003נדה.\u0004 שכן אפשר שביום זה נסתיימו שבעת ימי נקיות"],["\u0003ותמני\u0004 \u0005[ושמונה]\u0006 טבילות של יום \u0003ל\u0004טומאת \u0003זיבה.\u0004 שאפשר שראתה אף ביום שבאה לפנינו, והריהי זבה גדולה, ולכך מתחילים ימי נקיותה מיום שלמחרת בואה, וטובלת לזיבתה ביום השמיני. והרי אלה חמש עשרה טבילות. וכמו כן כאשר \u0003אתאי קמן בלילותא\u0004 \u0005[באה לפנינו בלילה]\u0006 \u0003יהבינן\u0004 \u0005[נותנים אנו]\u0006 \u0003לה תמני\u0004 \u0005[שמונה]\u0006 טבילות \u0003ל\u0004טומאת \u0003נדה,\u0004 האחת כבר בלילה זה (שמא כבר הסתיימו שבעת ימי נקיותה), ועוד שבע טבילות בשבעת הלילות הבאים (שמא ראתה בלילה קודם שבאה אלינו, ומסתיימים שבעת ימי נקיותה רק ביום השמיני, ובלילו היא טובלת), \u0003ו\u0004כן מצריכים אנו אותה שתטבול \u0003שב\u0004\u0005[שבע]\u0006 טבילות \u0003ל\u0004טומאת \u0003זיבה,\u0004 החל מהבוקר שלאחר בואה לפנינו, במשך שבעה ימים, והרי אלה חמש עשרה טבילות.","ותוהים: כאשר היא באה לפנינו בלילה, מדוע היא טובלת רק שבע טבילות לטומאת \u0003זיבה,\u0004 והלא \u0003תמני בעיא\u0004 \u0005[שמונה\u0006 טבילות היא \u0005צריכה],\u0006 שהרי יתכן שראתה בלילה לפני שבאה לפנינו ראיה של זיבה, והריהי איפוא זבה גדולה, וצריכה שבעה ימי נקיים קודם לטבילתה! \u0003אלא\u0004 יש לומר כי \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 הן זו הבאה לפנינו ביום והן זו הבאה לפנינו בלילה נותנים אנו לה \u0003שב\u0004\u0005[שבע]\u0006 טבילות \u0003ל\u0004טומאת \u0003נדה ותמני\u0004 \u0005[ושמונה]\u0006 טבילות \u0003ל\u0004טומאת \u0003זיבה.\u0004","ומקשים על תירוץ זה: ומדוע לזו הבאה לפנינו \u0003בלילותא\u0004 \u0005[בלילות]\u0006 נותנים אנו לטבול שבע טבילות לטומאת נדתה, והלא \u0003תמני\u0004 \u0005[שמונה]\u0006 טבילות \u0003ל\u0004טומאת \u0003נדה\u0004 היא \u0003בעי\u0004 \u0005[צריכה],\u0006 ואם כך שש עשרה טבילות הן, ואילו הברייתא אומרת שחייבת היא בחמש עשרה טבילות!","ומשיבים: הטעם שהזכירה הברייתא חמש עשרה טבילות, שכן מספר הטבילות שטובלת זו לטומאת \u0003זיבה דפסיקא ליה\u0004 \u0005[שפסוק,\u0006 שקצוב וקבוע \u0005הוא],\u0006 \u0003דלא שנא כי אתיא קמן ביממא, לא שנא כי אתיא קמן בליליא\u0004 \u0005[ש\u0006כן \u0005אין\u0006 זה \u0005משנה כאשר באה לפנינו ביום, אין\u0006 זה \u0005משנה כאשר באה לפנינו בלילה],\u0006 בכל מקרה היא טובלת שמונה טבילות — \u0003חשיב לה\u0004 \u0005[מונה אותה]\u0006 התנא כמספר קבוע, שמונה טבילות. ואולם מספר הטבילות שטובלת זו לטומאת \u0003נדה דלא פסיקא ליה\u0004 \u0005[שלא פסוק,\u0006 קצוב וקבוע \u0005הוא],\u0006 \u0003דכי אתיא קמן בלילותא\u0004 \u0005[ש\u0006כן \u0005כאשר\u0006 היא \u0005באה לפנינו בלילה]\u0006 — \u0003בעי תמני\u0004 \u0005[צריכה שמונה]\u0006 טבילות, וכאשר באה לפנינו \u0003ביממא\u0004 \u0005[ביום]\u0006 — \u0003לא קבעי תמני\u0004 \u0005[אין היא צריכה שמונה]\u0006 טבילות אלא שבע, לכך \u0003לא קחשיב לה\u0004 \u0005[אין התנא מונה אותה]\u0006 את מספר שמונה טבילות, אלא הריהו מונה שבע טבילות (שבכל האופנים היא טובלתן), ועולה כלל הטבילות לחמש עשרה.","\u0003ו\u0004עתה מסכמים כי לדעת חכמים (החולקים על ר' עקיבא) אין אנו צריכים שיהיו שבעת ימי נקיים ספורים לפנינו, שכן \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר כי שבעת ימים ה\u0003ספורין לפנינו בעינן\u0004 \u0005[אנו צריכים]\u0006 — \u0003כל הני\u0004 \u0005[אלה]\u0006 ה\u0003טבילות\u0004 המנויות בברייתא בדינה של זו שבאה לפנינו, שהריהי נדרשת לטבול מזמן שבאה לפנינו, \u0003למה לי?\u0004 והרי כיון שלא ספרה לפנינו, דינה ש\u0003תספור\u0004 תחילה \u0003שבעה\u0004 ימי נקיים, \u0003ו\u0004רק לאחר מכן \u0003הדר\u0004 \u0005[תחזור]\u0006 ו\u0003תטבול! אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 כי ברייתא זו כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, דאמרי\u0004 \u0005[שאומרים]\u0006 כי \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיו אלה שבעה ימים ה\u0003ספורין לפנינו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי\u0004 בדחיית הוכחה זו: \u0003לאו תרוצי קמתרצינן לה\u0004 \u0005[האם לא תירצנו,\u0006 העמדנו נוסח דברים שונה של \u0005אותה\u0006 ברייתא\u0005]\u0006 באומרת \"לא ראיתי\"? אף כאן \u0003תריץ ואימא הכי\u0004 \u0005[תרץ,\u0006 תקן, \u0005ואמור כך]:\u0006 האומרת \u0003\"ספרתי\u0004 ימי נקיים כדין, \u0003ו\u0004אולם \u0003איני יודעת כמה\u0004 ימים \u0003ספרתי.\u0004 וכן אין אני יודעת \u0003אם ב\u0004תקופת \u0003ימי נדה ספרתי ואם ב\u0004תקופת \u0003ימי זיבה ספרתי\"\u0004 — \u0003מטבילין אותה חמש עשרה טבילות.\u0004 ונמצא לפי נוסח זה, שאין להביא מכאן ראיה לענין ספירת שבעה ימי נקיות שיכולה להיעשות אף שלא בפנינו, שכן אפשר להעמיד ברייתא זו אף כר' עקיבא האומר שצריכים שבעת ימי הנקיות להיות ספורים לפנינו.","ומקשים על העמדה זו של דברי הברייתא: והרי במקרה של האומרת \u0003\"ספרתי, ואיני יודעת כמה ספרתי\"\u0004 — \u0003חד יומא מיהא\u0004 \u0005[יום אחד,\u0006 הוא היום שבאה לפנינו, \u0005לפחות]\u0006 \u0003אי אפשר\u0004 ש\u0003לא ספרה\u0004 בו, שהרי הוא ספור לפנינו, ומדוע היא צריכה לטבול אף ביום השמיני לבואה, ונמצא ש\u0003חסרה לה טבילה\u0004 אחת!","\u0003אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003\"איני יודעת אם ספרתי, אם לא ספרתי.\u0004 ואם היה זה בתקופת ימי נדה או בתקופת ימי זיבה — הריהי טובלת אף ביום השביעי, שכן יתכן שלא ספרה כלל.","\u0003הזב, והזבה, והנדה, והיולדת, והמצורע שמתו\u0004 בעודם טמאים — הריהם \u0003מטמאין ב\u0004טומאת \u0003משא,\u0004 ונוהג בהם דין זה \u0003עד\u0004 לשלב התבלות גוף המת \u0003ש\u0004בו \u0003ימוק\u0004 (ירקב) \u0003הבשר.\u0004 גופתו של \u0003גוי שמת\u0004 — אף שבחייו הריהו מטמא כזב, משעה שמת הריהו \u0003טהור מלטמא.\u0004","\u0003בית שמאי אומרים: כל הנשים\u0004 ה\u0003מתות\u0004 נחשבות כאילו היו \u0003נדות\u0004 בשעת מותן, ולכך הבגדים שהיו עליהן בשעת מותן נטמאו, ויש להטבילם. \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 כי \u0003אין\u0004 דין זה של טומאת האשה ה\u0003נדה\u0004 אמור \u0003אלא\u0004 באשה \u0003שמתה\u0004 כשהיא טמאת \u0003נדה,\u0004 ולא בנשים אחרות.","שנינו במשנתנו בטמאים שמתו שהריהם מטמאים במשא. ודנים בדבר: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה שהריהם מטמאים \u0003במשא? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה שמטמאים \u0003במשא ממש\u0004 — \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל מת\u0004 (ולא רק הטמא שמת) \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מטמא במשא!\u0004 ואין איפוא צורך להשמיענו שכך היא הלכה באלה הטמאים שמתו!","\u0003אלא מאי\u0004 \u0005[מה]\u0006 הכוונה שהריהם מטמאים \u0003במשא\u0004 — \u0003באבן מסמא\u0004 (אבן כבדה, שלא נועדה לטלטול, אלא להנחה במקום אחד).","ומסבירים שכן מובנו של הביטוי \"אבן מסמא\" \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדניאל שהושלך אל גוב האריות, \u0003\"והתית אבן חדא ושמת על פם גבא\"\u0004 \u0005[והובאה אבן אחת והושמה על פי הבור]\u0006 (דניאל ו, יח). ונלמד ממשנתנו שאף שסתם מת הנמצא על אבן זו אינו מטמא את הנמצא תחתיה (שהרי אין אבן זו נועדת לטלטול ולמשא), מכל מקום הטמאים שמתו, כשנמצאים הם על אבן זו הריהם מטמאים את הדבר הטהור הנמצא תחתיה.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב: גזרה\u0004 היא שגזרו חכמים, משום \u0003שמא יתעלפה\u0004 (יתעלף) הזב (או שאר הטמאים הנזכרים במשנתנו) בעודו יושב על אבן מסמא, ויחשבוהו למת, ויבואו שלא לטמא את הנמצא תחתיו, אף שלמעשה הוא נטמא (בטומאת מושבו של הזב). לכך גזרו חכמים שהזב (ושאר הטמאים שבמשנתנו) יטמאו באבן מסמא, אף כשמתו.","ומביאים ראיה, שכן \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]\u0006 כי \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' אליעזר אמרו\u0004 חכמים שכל אלה הטמאים שמתו הריהם מטמאים, \u0003עד שיבקע כריסו,\u0004 שכן לא גזרו חכמים אלא על המתים הדומים במצבם ובמראיהם לאדם החי שהתעלף. ואילו מת זה שהתבקעה כריסו, שאינו נראה כמתעלף, לא נאמרה בו גזירה זו.","שנינו במשנתנו בדינו של ה\u0003גוי שמת\u0004 שאין הוא מטמא במשא. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: מפני מה אמרו\u0004 חכמים כי \u0003גוי שמת\u0004 נחשב כ\u0003טהור מלטמא במשא\u0004 — \u0003לפי שאין טומאתו\u0004 אף \u0003מחיים מדברי תורה, אלא מדברי סופרים,\u0004 שאף שגזרו חכמים בגוי החי שהריהו נחשב כזב לכל דבריו, לא הוסיפו חכמים לגזור בו שיטמא משמת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנים עשר דברים שאלו אנשי\u0004 העיר \u0003אלכסנדריא\u0004 שבמצרים \u0003את ר'\u0004 \u0003יהושע בן חיננא, שלשה\u0004 מהם \u0003דברי חכמה,\u0004 \u0003שלשה\u0004 אחרים \u0003דברי הגדה,\u0004 ו\u0003שלשה\u0004 נוספים \u0003דברי בורות,\u0004 ועוד \u0003שלשה\u0004 היו \u0003דברי דרך ארץ.\u0004","ומפרטים: \u0003שלשה דברי חכמה:\u0004 האחד, \u0003הזב והזבה והנדה והיולדת והמצורע שמתו, עד מתי\u0004 הריהם \u0003מטמאין במשא? אמר להן: עד שימוק הבשר,\u0004 וכהלכה השנויה במשנתנו.","והדבר השני, ששאלו, \u0003בת\u0004 האשה ה\u0003משולחת\u0004 (שהתגרשה מבעלה), שלאחר שהתגרשה נישאה לבעל אחר, ואף ממנו התגרשה או שמת בעלה זה, ושב בעלה הראשונה ונשאה (שלא כהלכה, שכן אסורה היא על בעלה הראשון משעה שנישאה לאיש אחר), ונולדה להם בת מנישואין אסורים אלה, \u0003מה היא\u0004 ההלכה, האם בת זו יכולה להינשא \u0003לכהן?\u0004","והסבירו את שאלתם, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003קל וחומר\u0004 הוא: \u0003ומה אלמנה לכהן גדול, שאין איסורה שוה בכל,\u0004 שהרי היא אסורה רק לכהן גדול — \u0003בנה\u0004 הנולד מנישואין אסורים שכאלה הריהו \u0003פגום\u0004 לכהונה, שהתחלל מכהונתו. \u0003זו\u0004 (הגרושה שנישאה לאחר) \u0003שאיסורה שוה בכל\u0004 אדם מישראל — \u0003אינו דין שבנה\u0004 הנולד מנישואין אסורים אלה יהא \u0003פגום,\u0004 ולכך תיחשב הבת הנולדת כפגומה לנישואין עם כהן. \u0003או דילמא\u0004 \u0005[שמא]\u0006 יש לפרוך קל וחומר זה, שכן \u0003מה לאלמנה לכהן גדול\u0004 — \u0003שהיא עצמה מתחללת\u0004 בנישואיה לכהן גדול, שהיא נפסלת מאכילת תרומה, ולכשתתאלמן מכהן גדול זה הריהי אסורה להינשא לכהן הדיוט.","\u0003אמר להן:\u0004"],["באיסור המחזיר גרושתו אמרה תורה \"לא יוכל בעלה הראשון אשר שלחה לשוב לקחתה לו לאשה אחרי אשר הוטמאה כי תועבה היא לפני ה' \" (דברים כד, ד), ומדייקים מלשון הכתוב \"כי תועבה היא\", שדווקא \u0003היא\u0004 האשה הגרושה שנישאה שוב לבעלה הראשון \u0003תועבה, ו\u0004אולם \u0003אין בניה\u0004 הנולדים מנישואין אלה \u0003תועבין.\u0004 ולפיכך הבת הנולדת מנישואין אלה, מותרת להינשא לכהן.","והדבר השלישי ששאלו, \u0003שני מצורעין\u0004 עשירים (שלאחר שגילחו וטבלו מביאים שלוש בהמות לקרבנותיהם: חטאת, אשם ועולה) \u0003שנתערבו קרבנותיהן\u0004 שהובאו לכפרתם \u0003זה בזה, וקרב קרבנו\u0004 (קרבן החטאת) \u0003של אחד מהן,\u0004 ואין אנו יודעים קרבנו של מי היה זה, \u0003ו\u0004לאחר מכן \u0003מת אחד מהן\u0004 (מהמצורעים הללו), \u0003השני\u0004 (המצורע החי) \u0003מה\u0004 תקנה \u0003תהא עליו\u0004 שיוכל לאכול בקדשים. שכן אילו לא מת אחד מהם — היה כל אחד מהם מקריב קרבן אחד לשם מי שהוא בעליו, וכיון שמת אחד — אי אפשר לו למצורע החי להקריב את קרבן החטאת שלפניו, שהרי יתכן שהוא קרבנו של חבירו המת, והחטאת שמתו בעליה מומתת. ואף קרבן חטאת אחר אינו יכול להביא, שהרי יתכן שאותו קרבן שקרב היה שלו, ומאחר שכבר קרב קרבן חטאתו, אינו יכול לשוב ולהביא קרבן שני לחטאת.","\u0003אמר להן\u0004 ר' יהושע לאנשי אלכסנדריה בתשובה: תקנתו היא שהריהו \u0003כותב\u0004 בשטר מתנה שנותן הוא את כל \u0003נכסיו ל\u0004אנשים \u0003אחרים\u0004 (שסומך הוא עליהם, שישובו ויתנו לו אותם במתנה לאחר מכן) — \u0003והוי\u0004 \u0005[והריהו]\u0006 מעתה נקרא \u0003עני, ו\u0004דינו של המצורע העני שהריהו מביא את חטאתו ואת עולתו מן העופות, והריהו איפוא \u0003מביא חטאת העוף, הבא על הספק.\u0004","ותוהים על פתרון זה: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם קרבן \u0003אשם\u0004 שהמצורע מביא לכפרתו, ואולם האשם בא רק מן הבהמה, ואינו בא על הספק, ומה יעשה המצורע החי בהקרבת אשמו? \u0003אמר שמואל:\u0004 תקנה זו שהציע ר' יהושע אמורה רק \u0003כשקרב\u0004 כבר \u0003אשמו\u0004 של המצורע החי (לפני שהתערבו קרבנותיו בקרבנות המצורע שמת).","\u0003אמר רב ששת\u0004 בתמיהה על הסברו זה של שמואל: \u0003גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003כשמואל לימא כי האי מילתא\u0004 \u0005[יאמר כדבר הזה]?\u0006 שהרי \u0003כ\u0004שיטתו של \u0003מאן\u0004 \u0005[מי]\u0006 אמר שמואל את דבריו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי הקרבת ה\u0003אשם קבעה\u0004 את דרך כפרתו של המצורע. שמצורע שהיה עשיר בשעה שהקריב את אשמו — נקבעה בכך כפרתו כשל מצורע עשיר, ומעתה אף אם ייעשה עני, חייב עדיין להביא שתי בהמות לחטאתו ולעולתו. \u0003וכיון\u0004 שכבר \u0003קבעה לה אשם בעשירות\u0004 — שוב הוא \u0003לא מצי מייתי\u0004 \u0005[אינו יכול להביא]\u0006 את קרבן ה\u0003חטאת בדלות\u0004 כדינו של מצורע עני (המביא חטאתו ועולתו מן העוף).","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצורע\u0004 עני \u0003שהביא\u0004 אחד מקרבנותיו כ\u0003קרבן עני, ו\u0004לאחר מכן \u0003העשיר, א\u0004 \u0003ו\u0004במקרה הפוך, שהיה מצורע \u0003עשיר\u0004 והביא אחד מקרבנותיו, \u0003ו\u0004לאחר מכן \u0003העני\u0004 — \u0003הכל הולך אחר\u0004 (הגדרתו נקבעת לפי) קרבן ה\u0003חטאת.\u0004 שאם הקרבן שהקריב במצבו הקודם היה חטאת (וכגון שהיה עני, והביא מן העוף) — אף את שאר קרבנותיו הריהו מביא כבמצבו הקודם (ויביא את עולתו מן העוף). ואם הקרבן שקרב היה עולה או אשם (וכגון שהיה עני, והביא את עולתו מן העוף) וקרבן החטאת טרם הוקרב — את שאר קרבנותיו הריהו מביא כבמצבו הנוכחי (ולכך יביאם מן הבהמות). אלה הם \u0003דברי ר'\u0004 \u0003שמעון.\u0004","\u0003ו\u0004אילו \u0003ר' יהודה אומר: הכל הולך אחר\u0004 קרבן ה\u0003אשם.\u0004 \u0003ר'\u0004 \u0003אליעזר בן יעקב אומר: הכל הולך אחר צפורים\u0004 (באיזה מצב היה המצורע ביום הראשון לסדר טהרתו, כשהביא את שתי הציפורים).","\u0003ואי\u0004 \u0005[ואם]\u0006 תאמר ששמואל אמר את דבריו בהסבר פתרונו של ר' יהושע \u0003כ\u0004שיטתו של \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 כי ה\u0003חטאת\u0004 היא ש\u0003קבעה,\u0004 כיון שהקריב זה את אשמו מן הבהמה (כמצורע עשיר), יכול הוא להביא את חטאתו ואת עולתו מן העוף — אין להעמיד את דברי ר' יהושע כשיטתו של ר' שמעון, שהרי לדעת ר' שמעון \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא קרב\u0004 קרבן ה\u0003אשם\u0004 של המצורע החי לפני שהתערבו קרבנותיהם של המצורע המת והחי, יש לו תקנה, ובאופן זה: \u0003ניתי\u0004 \u0005[שיביא]\u0006 קרבן \u0003אחר,\u0004 שיוקרב כאשם בתנאי שהוא מתנה שאם קרבן האשם שכבר הוקרב היה של חבירו שמת — הרי קרבן זה יהיה קרבן אשמו שלו. ואם קרבן האשם שכבר הוקרב היה שלו — יהא קרבן זה לשלמים. \u0003דהא שמעינן ליה\u0004 \u0005[שהרי\u0006 כך \u0005שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 בדינו של מי שהוא ספק מצורע, כי \u0003לייתי ולתני\u0004 \u0005[שיביא ויתנה].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003שמעון\u0004 בדינו של ספק מצורע, שנוהג בשבעת ימי טהרתו ככל שאר המצורעים, ביום הראשון בתגלחת ובהבאת שתי ציפורים, והריהו מתגלח שנית וטובל ביום השביעי, ו\u0003למחרת\u0004 (ביום השמיני) הריהו \u0003מביא\u0004 את \u0003אשמו ולוגו\u0004 (לוג השמן המשמש להזאה ולנתינתו על המצורע) \u0003עמו, ומעמידו בשער נקנור\u0004 שבהר הבית, \u0003ומתנה עליו, ואומר: אם\u0004 קרבן זה של \u0003מצורע הוא\u0004 — \u0003הרי\u0004 זהו \u0003אשמו ו\u0004זה הוא \u0003לוגו\u0004 הבא \u0003עמו.\u0004 \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין הוא מצורע, איל \u0003אשם זה\u0004 — \u0003יהא\u0004 של \u0003שלמי נדבה,\u0004 שכן דרך הקרבתם שווה.","\u0003ואותו אשם\u0004 של ספק הריהו \u0003טעון\u0004 (חייב)"],["שתהא \u0003שחיטתו בצפון\u0004 העזרה, כדין האשם, \u0003וטעון מתנת\u0004 (נתינה) מדמו על \u0003בהונות\u0004 המיטהר ועל אוזנו (יעוין ויקרא יד, יד), \u0003וסמיכה\u0004 על ראש הקרבן, \u0003ו\u0004הבאת \u0003נסכים\u0004 עם הקרבן, \u0003ותנופה\u0004 (הנפה) של \u0003חזה ושוק\u0004 כדין השלמים, \u0003ו\u0004אולם דינו כדין האשם לענין שהריהו \u0003נאכל לזכרי כהונה ל\u0004משך \u0003יום ולילה,\u0004 ולא לשני ימים ולילה כדין השלמים.","\u0003ולא הודו לו חכמים לר' שמעון,\u0004 בדינו של ספק מצורע, וטעם הדבר: \u0003מפני ש\u0004בכך הריהו נמצא ש\u0003מביא קדשים לבית הפסול.\u0004 שהרי אפשר שקרבן זה הוא אמנם שלמים, הנאכלים לשני ימים ולילה. ועתה שנוהגים בקרבן זה כספק שלמים ספק אשם, ואין אוכלים אותו אלא ליום ולילה אחד בלבד (כדין האשם ולא כדין השלמים), נמצא שקרבן שלא נאכל באותו יום ולילה, מובל לשריפה כקדשים שנפסלו (\"בית הפסול\"). הרי איפוא, שאין להעמיד את הסברו של שמואל כשיטת ר' שמעון!","ומתרצים: אין זו קושיה, שכן אפשר לומר כי \u0003שמואל סבר לה\u0004 \u0005[הריהו סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד],\u0006 ולענין זה שאין האשם קובע, \u0003ופליג עליה בחדא\u0004 \u0005[ו\u0006הריהו \u0005חולק עליו ב\u0006דבר \u0005אחד],\u0006 לענין ההתנאה בקרבן.","ועוד שאלו חכמי אלכסנדריה את ר' יהושע בן חנניה \u0003שלשה\u0004 דברים ב\u0003דברי אגדה.\u0004 האחד, \u0003כתוב אחד אומר\u0004 בהנהגת הקדוש ברוך הוא \u0003\"כי לא אחפץ במות המת\"\u0004 (יחזקאל יח, לב), \u0003ו\u0004אילו \u0003כתוב אחד\u0004 אודות בני עלי אשר לא שמעו לתוכחת אביהם \u0003אומר \"כי חפץ ה'\u0004 \u0003להמיתם\"\u0004 (שמואל א ב, כה)! השיב להם ר' יהושע: אין זו סתירה, שכן \u0003כאן\u0004 בכתוב האומר שאין ה' חפץ במות המת — מדובר \u0003ב\u0004חוטאים ה\u0003עושין תשובה,\u0004 ואילו \u0003כאן\u0004 בכתוב האומר שחפץ ה' במותם — מדובר \u0003ב\u0004חוטאים \u0003שאין עושין תשובה.\u0004","ועוד שאלו חכמי אלכסנדריה את ר' יהושע: \u0003כתוב אחד אומר\u0004 בהנהגת הקדוש ברוך הוא \u0003\"כי\u0004 ה' אלהיכם הוא אלהי האלהים ואדוני האדונים האל הגדול הגבור והנורא אשר \u0003לא ישא פנים ולא יקח שחד\"\u0004 (דברים י, יז), \u0003ו\u0004אילו \u0003כתוב אחד\u0004 הנאמר בברכת כהנים לבני ישראל \u0003אומר \"ישא ה'\u0004 \u0003פניו אליך\u0004 וישם לך שלום\" (במדבר ו, כו)! השיב להם ר' יהושע: אין זו סתירה, שכן \u0003כאן\u0004 בכתוב האומר שיש נשיאת פנים לפני המקום — מדובר \u0003קודם גזר דין,\u0004 ואילו \u0003כאן\u0004 בכתוב האומר שאין נשיאת פנים לפניו — מדובר \u0003לאחר גזר דין.\u0004","\u0003ועוד שאלו את ר' יהושע:\u0004 \u0003כתוב אחד אומר \"כי בחר ה'\u0004 \u0003בציון\u0004 אוה למושב לו\" (תהלים קלב, יג), ומשמע כי העיר ירושלים היא העיר הרצויה לפני הקדוש ברוך הוא, \u0003ו\u0004אילו \u0003כתוב אחד אומר\u0004 על ירושלים \u0003\"כי על אפי ועל חמתי היתה העיר הזאת למן היום אשר בנו אותה עד היום הזה\u0004 להסירה מעל פני\" (ירמיה לב, לא)! והשיב להם ר' יהושע: \u0003כאן\u0004 בכתוב האומר כי ירושלים היא העיר הרצויה לפניו — מדובר \u0003קודם שנשא שלמה את בת פרעה,\u0004 ואילו \u0003כאן\u0004 בכתוב האומר שיש בירושלים להכעסת הקדוש ברוך הוא — מדובר \u0003לאחר שנשא שלמה את בת פרעה.\u0004","ואף \u0003שלשה דברי בורות\u0004 שאלו חכמי אלכסנדריה את ר' יהושע, ומפרטים: האחד, \u0003אשתו של לוט\u0004 (שהיתה לנציב מלח, ככתוב בה \"ותבט אשתו מאחריו ותהי נציב מלח\", בראשית יט, כו), \u0003מהו\u0004 דינה לענין \u0003שתטמא\u0004 כאדם המת? \u0003אמר להם:\u0004 דווקא האדם ה\u0003מת\u0004 הוא ה\u0003מטמא, ואין נציב מלח\u0004 (אף שהיה זה קודם לכן אדם חי) \u0003מטמא.\u0004","חזרו ושאלוהו: \u0003בן\u0004 האשה ה\u0003שונמית\u0004 (שהחיה אותו הנביא אלישע, כמובא במלכים ב ד, לג—לו), \u0003מהו\u0004 דינו לענין \u0003שיטמא\u0004 כאדם מת, לאחר ששב לחיים? \u0003אמר להן\u0004 ר' יהושע: דווקא האדם ה\u0003מת\u0004 הוא ש\u0003מטמא, ואין\u0004 אדם ה\u0003חי\u0004 (אף שבשלב מסויים היה מת) \u0003מטמא.\u0004","ועוד שאלוהו בעניינם של ה\u0003מתים\u0004 הקמים לתחיה \u0003לעתיד לבא,\u0004 האם הם \u0003צריכין הזאה שלישי ושביעי,\u0004 כדרך האדם הנטהר מטומאת מת (שהרי היו מתים בעצמם), \u0003או\u0004 ש\u0003אין\u0004 הם \u0003צריכין\u0004 הזאה לטהרם מטומאת מת? \u0003אמר להן: לכשיחיו\u0004 — \u0003נחכם להן\u0004 מהו דינם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך אמר להם בתשובה לשאלתם זו: \u0003לכשיבא משה רבינו עמהם\u0004 יאמר לנו מהו דינם של אלה.","וכן שאלו חכמי אלכסנדריה את ר' יהושע \u0003שלשה דברי דרך ארץ,\u0004 ומפרטים: האחד, \u0003מה יעשה אדם\u0004 ועל ידי כך \u0003ויחכם? אמר להן: ירבה בישיבה, וימעט בסחורה.\u0004 \u0003אמרו\u0004 לו בשאלה: והלא \u0003הרבה עשו כן, ולא הועיל להם!\u0004 חזר ואמר להם ר' יהושע: \u0003אלא\u0004 כן יעשו מבקשי החכמה, \u0003יבקשו רחמים\u0004 (יבקשו בתפילה) \u0003מ\u0004לפני \u0003מי שהחכמה\u0004 \u0003שלו,\u0004 שיעניק לו חכמה. \u0003ש\u0004כן \u0003נאמר \"כי ה'\u0004 \u0003יתן חכמה מפיו דעת ותבונה\"\u0004 (משלי ב, ו).","ומביאים כי בענין זה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: משל למלך בשר ודם שעשה סעודה לעבדיו,\u0004 שעבדיו אוכלים מהאוכל אשר לפניהם, ואולם המלך \u0003משגר\u0004 (שולח) \u0003לאוהביו\u0004 אוכל \u0003ממה שלפניו.\u0004 וכן הוא בענין החכמה שהקדוש ברוך הוא נותן מחכמתו לאוהביו, שכן הוא בכתוב זה האומר \"כי ה' יתן חכמה מפיו דעת ותבונה\".","ושואלים: מאחר ודרך רכישת החכמה היא בתפילה מלפני ה', \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 ר' יהושע, \u0005משמיע לנו]\u0006 בדבריו שאמר תחילה שהדרך לרכישת החכמה היא להרבות בישיבה ולמעט בסחורה? ומשיבים: ללמדנו, \u0003דהא\u0004 \u0005[שזו,\u0006 תפילה\u0005]\u0006 \u0003בלא הא\u0004 \u0005[זו,\u0006 המרבה בישיבה וממעט בסחורה\u0005],\u0006 \u0003לא סגיא\u0004 \u0005[אינה מספיקה],\u0006 שנצרך המבקש לחכמה לזה ולזה.","ועוד שאלו אנשי אלכסנדריה את ר' יהושע: \u0003מה יעשה אדם ויתעשר? אמר להן: ירבה בסחורה, וישא ויתן באמונה.\u0004 \u0003אמרו לו\u0004 בשאלה: והלא \u0003הרבה עשו כן, ולא הועילו\u0004 בכך להיות לעשירים! חזר ר' יהושע ואמר להם: \u0003אלא\u0004 כך יעשה הרוצה להיות עשיר, \u0003יבקש רחמים\u0004 בתפילה \u0003מ\u0004לפני \u0003מי שהעושר שלו,\u0004 שיעניק לו עושר, \u0003ש\u0004כן \u0003נאמר \"לי הכסף ולי הזהב\u0004 נאום ה' צבאות\" (חגי ב, ח).","ושואלים: מאחר ודרך רכישת העושר היא בתפילה מלפני ה', \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 ר' יהושע, \u0005משמיע לנו]\u0006 בדבריו שאמר בתחילה שהדרך לרכישת העושר היא להרבות בסחורה ולשאת ולתת באמונה? ומשיבים: ללמדנו, \u0003דהא\u0004 \u0005[שזו,\u0006 תפילה\u0005]\u0006 \u0003בלא הא\u0004 \u0005[זו,\u0006 שירבה בסחורה וישא ויתן באמונה\u0005],\u0006 \u0003לא סגי\u0004 \u0005[אינה מספיקה],\u0006 שנצרך המבקש עושר לזה ולזה.","ועוד שאלו אנשי אלכסנדריה את ר' יהושע: \u0003מה יעשה אדם ויהיו לו בנים זכרים? אמר להם: ישא אשה ההוגנת לו,\u0004"],["\u0003ויקדש עצמו\u0004 לשמש בצניעות \u0003בשעת\u0004 ה\u0003תשמיש.\u0004","\u0003אמרו\u0004 אנשי אלכסנדריה לר' יהושע בשאלה על דבריו אלה: והלא \u0003הרבה עשו כן, ולא הועילו\u0004 שיוולדו להם בנים זכרים! \u0003אלא\u0004 חזר ר' יהושע ואמר להם כי הדרך לכך שיוולדו לאדם בנים זכרים היא ש\u0003יבקש רחמים\u0004 בתפילה \u0003מ\u0004לפני \u0003מי שהבנים\u0004 הם \u0003שלו,\u0004 שיעניק לו בנים זכרים, \u0003ש\u0004כן \u0003נאמר \"הנה נחלת ה'\u0004 \u0003בנים שכר פרי הבטן\"\u0004 (תהלים קכז, ג).","ושואלים: מאחר והדרך להולדת בנים זכרים היא בתפילה מלפני ה', \u0003מאי קא משמע לן\u0004 \u0005[מה הוא,\u0006 ר' יהושע, \u0005משמיע לנו]\u0006 בדבריו שאמר תחילה? ומשיבים: ללמדנו, \u0003דהא\u0004 \u0005[שזו,\u0006 תפילה\u0005]\u0006 \u0003בלא הא\u0004 \u0005[זו,\u0006 נישואין לאשה ההוגנת לו וצניעות בשעת תשמיש\u0005],\u0006 \u0003לא סגי\u0004 \u0005[אינה מספיקה],\u0006 שנצרך המבקש להוליד בנים זכרים לזה ולזה.","אגב כך מסבירים \u0003מאי\u0004 \u0005[מה\u0006 פירוש הכתוב\u0005]\u0006 \u0003\"שכר פרי הבטן\"? אמר ר'\u0004 \u0003חמא בר' חנינא: בשכר ש\u0004בשעת התשמיש הבעלים \u0003משהין עצמן בבטן\u0004 מלהזריע, ועושים כן \u0003כדי שתזריע אשתו תחילה\u0004 — \u0003נותן לו הקדוש ברוך הוא שכר פרי הבטן,\u0004 ונולדים מזיווג זה בנים זכרים.","שנינו במשנתנו כי \u0003בית שמאי אומרים\u0004 שכל הנשים המתות נחשבות כמי שמתו בנידתן, ולכך מטבילים את הבגדים שהיו עליהן סמוך למיתתן. ומבררים: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי? אי נימא\u0004 \u0005[אם נאמר]\u0006 שהוא \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 באסתר המלכה לכשראתה את כתב הגזירה שנכתב על כל היהודים להיהרג \u0003\"ותתחלחל המלכה\"\u0004 (אסתר ד, ד) \u0003ואמר רב\u0004 כי הכתוב \u0003מלמד ש\u0004אסתר \u0003פרסה נדה,\u0004 ומכאן למדנו כי הפחד גורם לראיית דם נדה, ו\u0003הכא נמי\u0004 \u0005[כאן,\u0006 בנשים המתות, \u0005גם כן]\u0006 יש לומר טעם זה, כי \u0003אגב ביעתותא דמלאכא דמותא\u0004 — \u0003חזיא\u0004 \u0005[מתוך הפחד ממלאך המוות\u0006 \u0005— רואה],\u0006 \u0003ו\u0004אולם \u0003האנן תנן\u0004 \u0005[הרי אנו שנינו]\u0006 \u0003שחרדה מסלקת את הדמים!\u0004 ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שכן \u0003פחדא\u0004 \u0005[פחד,\u0006 חרדה\u0005]\u0006 ממושכת — אכן \u0003צמית\u0004 \u0005[מצמית]\u0006 את הדם מלצאת, משום שהוא מכווץ את בית הרחם. ואולם \u0003ביעתותא\u0004 \u0005[בעתה]\u0006 פתאומית — הריהי \u0003מרפיא\u0004 \u0005[מרפה,\u0006 מרווחת את בית הרחם\u0005],\u0006 דבר הגורם ליציאת דם מן המקור.","\u0003אלא\u0004 אם אכן תאמר שטעמם של בית שמאי הוא משום שהבעתה גורמת ליציאת דם מן המקור, \u0003הא דתנן\u0004 \u0005[זה ששנינו\u0006 במשנה\u0005]\u0006 כי \u0003בית שמאי אומרים\u0004 כי \u0003כל האנשים\u0004 ה\u0003מתים\u0004 נחשבים \u0003זבין, ו\u0004אילו \u0003בית הלל אומרים\u0004 כי \u0003אין\u0004 האיש המת נקרא \u0003זב אלא\u0004 רק \u0003מי שמת\u0004 כשהוא אמנם \u0003זב.\u0004 ואם זה הוא טעמם של בית שמאי בענין הנשים המתות, לכאורה כן הוא גם כן טעמם לענין האנשים המתים, שהם רואים זוב מחמת הבעתה.","וקשה, שכן אף בזה \u0003אקרי\u0004 \u0005[אקרא]\u0006 \u0003כאן\u0004 את הדרשה על הכתוב \"איש איש כי יהיה זב \u0003מבשרו\"\u0004 (ויקרא טו, ב) — אין הדברים אמורים אלא כשהזיבה באה מחמתו, \u0003ולא מחמת אונסו.\u0004 ואם כן הזיבה שבאה מחמת בעתת המוות הינה אונס גמור, ולא יהיה זה זב.","\u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית שמאי\u0004 בדינן של כל הנשים המתות שהריהן מטמאות כנדה, \u0003כ\u0004זו \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בראשונה\u0004 (בתחילה) נוהגים \u0003היו\u0004 ש\u0003מטבילין\u0004 מפני הטומאה רק את ה\u0003כלים\u0004 (הבגדים) שהיו \u0003על גבי\u0004 ה\u0003נדות\u0004 ה\u0003מתות,\u0004 בסמוך למיתתן, שנטמאו הבגדים מחמת הנשים, \u0003והיו\u0004 הנשים ה\u0003נדות\u0004 ה\u0003חיות מתביישות,\u0004 שאף בשעת מותן דינן שונה מדינו של אדם אחר. וכשמטבילים את בגדיהם, יודעים הכל שהן היו נדות בשעת מותן. לכך \u0003התקינו\u0004 חכמים \u0003שיהו מטבילין\u0004 את כל הבגדים שהיו \u0003על גבי כל הנשים\u0004 שמתו, ואף אלה שלא היו נדות בשעת מותן, ועשו כן \u0003מפני כבודן של נדות חיות.\u0004","וכיוצא בדבר, \u0003בראשונה היו מטבילין\u0004 את כל הבגדים שהיו \u0003על גבי\u0004 הגברים ה\u0003זבין\u0004 ה\u0003מתין, והיו\u0004 ה\u0003זבין\u0004 ה\u0003חיין מתביישין\u0004 בדבר. עמדו חכמים ו\u0003התקינו שיהו מטבילין\u0004 את כל הבגדים שהיו \u0003על גבי כל האנשים\u0004 שמתו, ואף אלה שלא היו זבים באותה עת, \u0003מפני כבודן של\u0004 ה\u0003זבין\u0004 ה\u0003חיים.\u0004","\u0003האשה שמתה, ו\u0004לאחר מותה \u0003יצאה ממנה\u0004 כשיעור \u0003רביעית דם\u0004 — אף שיצאה לאחר מיתה, הריהי \u0003מטמאה\u0004 בטומאת הנדה, \u0003משום כתם\u0004 המטמא במגעו ובמשא. וטומאה זו הריהי מטמאת אף בשיעור כלשהו, שאין צריך שיהא בו שיעור רביעית כדי לטמא. ושלא כטומאת המת, שהדם מטמא בה בשיעור רביעית ויותר. \u0003ו\u0004כן הריהי \u0003מטמאה ב\u0004טומאת \u0003אהל,\u0004 ככל הדם היוצא מן המת, ובלבד שיהא בדם שיעור רביעית הנמצא כולו באוהל.","\u0003ר' יהודה אומר: אינה מטמאה משום כתם, מפני שנעקר\u0004 הדם לאחר \u0003ש\u0004כבר \u0003מתה,\u0004 ואז אין זה נחשב לדם נדה. \u0003ו\u0004מוסיפים עוד כי \u0003מודה ר'\u0004 \u0003יהודה ב\u0004אשה מעוברת שאחזו בה צירי לידה, והריהי \u0003יושבת על\u0004 ה\u0003משבר\u0004 (כסא היולדת), \u0003ומתה, ויצאה ממנה רביעית דם\u0004 — \u0003שהיא מטמאה משום כתם,\u0004 שכן באופן זה נעקר הדם ממנה בעודה בחיים. \u0003אמר ר'\u0004 \u0003יוסי:\u0004 כיון שאמרנו שאשה שמתה בתוך לידתה, הדם היוצא ממנה לאחר מותה נעקר ממנה בחיים, \u0003לפיכך\u0004 רביעית דם זו \u0003אינה מטמאה באהל,\u0004 שהרי אין זו באה מן המת.","שנינו במשנתנו בטעם דברי ר' יהודה המטהר את הדם היוצא מהאשה לאחר מותה, שכן דם זה (אף שיצא מן המקור) יצא ממנה לאחר מותה, ואין דם שכזה מטמא בטומאת נדה. ושואלים: האם \u0003מכלל\u0004 הדברים נלמד כי \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון\u0006 שבמשנתנו \u0005סבור],\u0006 ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003נעקר דם משמתה\u0004 הריהי \u0003מטמאה משום כתם?\u0004","\u0003אמר ר'\u0004 \u0003זעירי:\u0004 אף לדעת התנא הראשון דם המקור שיצא לאחר מות האשה, אינו מטמא משום נדות. ואולם כאן מדובר בדם שנעקר ממקומו עוד בחיי האשה, אך לא יצא מן המקור אלא לאחר שמתה. ובשאלה האם \u0003מקור מקומו טמא\u0004 (האם כל דם שהיה במקור מטמא) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. שלדעת התנא הראשון אף דם שנראה רק לאחר מות האשה מטמא משום נדות כיון שהיה במקום המקור. ולדעת ר' יהודה אינו מטמא, אף שהיה במקום המקור.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003מודה ר'\u0004 \u0003יהודה\u0004 שדם היוצא לאחר מות היולדת שישבה על המשבר מטמא משום נדות, משום שבוודאי נעקר ממנה בעודה בחיים. ועל כך אמר ר' יוסי כי מעתה יש לומר גם כי דם זה אינו מטמא באוהל.","ושואלים: האם \u0003מכלל\u0004 הדברים נלמד כי \u0003תנא קמא\u0004 \u0005[התנא הקודם,\u0006 ר' יהודה\u0005],\u0006 שלא אמר את דינו זה אלא לענין טומאת נדה, ולא לטומאת אוהל, \u0003סבר\u0004 \u0005[סבור]\u0006 שדם היוצא מן האשה שמתה ביושבה על המשבר, אף שיצא לאחר מותה \u0003ב\u0004טומאת \u0003אהל נמי\u0004 \u0005[גם כן]\u0006 \u0003מטמא,\u0004 והרי נעקר הדם ממנה בעודה בחיים? \u0003אמר רב יהודה:\u0004 \u0003לא אמר ר' יהודה אלא כאשר חלק מן הדם יצא ממנה בעודה בחיים, ואולם חלקו האחר יצא ממנה לאחר מותה, והרי זה איפוא\u0004 \u0003דם תבוסה\u0004 (שיש בו תערובת דמים, היוצא מן האדם בעודו חי והיוצא ממנו לאחר מותו), ובדבר זה מחלוקת \u0003איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 בין ר' יהודה לר' יוסי\u0005]\u0006 שלדעת ר' יהודה יש דין דם תבוסה אף ביולדת היושבת על המשבר, ולכך הדם היוצא ממנה לאחר מותה מטמא (מדברי חכמים) אף באוהל. ואילו לדעת ר' יוסי אין הדם היוצא ממנה נחשב כדם תבוסה, שכן ברור לנו בזו שנעקר ממנה הדם בעודה בחיים.","ומבררים עניינו של דם תבוסה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003איזהו\u0004 (מהו) \u0003דם תבוסה\u0004 שאמרנו בו (לעיל סב,ב) שמטמא באוהל מדברי חכמים? \u0003פירש ר' אלעזר בר' יהודה: הרוג שיצא ממנו דם בין בחייו בין במותו,\u0004 שהתחילה רביעית דם לצאת ממנו בעודו בחיים, והמשיכה לזוב ממנו לאחר מותו. ומעתה הרי זה \u0003ספק\u0004 שמא שיעור רביעית דם מלא, עוד \u0003בחייו יצא\u0004 (ואין זה דם המטמא), \u0003ספק\u0004 שמא רק \u0003במותו יצא\u0004 שיעור הרביעית (והריהו מטמא מן התורה), \u0003ספק\u0004 שמא חלק מהרביעית יצא \u0003בחייו ו\u0004חלקו האחר יצא \u0003במותו\u0004 — \u0003זהו דם תבוסה.\u0004","\u0003וחכמים\u0004 חולקים על ר' אלעזר בר' יהודה ו\u0003אומרים\u0004 כי זה אינו נחשב לדם תבוסה, שמאחר שיש ספק שמא כל רביעית הדם יצאה לאחר מותו, הרי זה איפוא ספק טומאה מן התורה, ויש לנהוג לפי הכלל כי אם נמצא הספק \u0003ברשות היחיד\u0004 — \u0003ספקו טמא,\u0004 ואם נמצא \u0003ברשות הרבים\u0004 — \u0003ספקו טהור.\u0004 ואין בזה מקום לגזירת חכמים.","\u0003אלא איזהו דם תבוסה? הרוג שיצא הימנו\u0004 (ממנו) \u0003רביעית דם בחייו ובמותו, ועדיין לא פסק,\u0004 וברור לנו שלא יצאה רביעית דם שלימה ממנו לאחר מותו, ואולם \u0003ספק\u0004 הוא האם \u0003רובו\u0004 יצא ממנו בעודו \u0003בחייו ומיעוטו\u0004 יצא ממנו \u0003במותו,\u0004 \u0003ספק\u0004 יצא ממנו \u0003מיעוטו בחייו ורובו במותו\u0004 — \u0003זהו דם תבוסה.\u0004","\u0003ר'\u0004 \u0003יהודה אומר: הרוג שיצא ממנו רביעית דם, והיה מוטל במטה ודמו מטפטף ל\u0004תוך \u0003גומא\u0004 — הרי זה \u0003טמא, מפני שהטפה של מיתה מעורבת בו.\u0004 \u0003וחכמים מטהרין, מפני\u0004"],["\u0003שראשון ראשון\u0004 (כל טיפה וטיפה) יוצאת כ\u0003נפסק\u0004 (נפרדת) מהטיפה שקדמה לה, שאין זה דם הזב בקילוח. ומשום כך, אפילו היה רוב היוצא לאחר מיתה — הרי זה דם טהור. שהרי מתחילה נפל לתוך הגומה דם טהור (הדם שיצא ממנו בחייו), וכל טיפה וטיפה שנפלה לאחר מכן לתוך הגומה מתבטלת בדם הנמצא בגומה. ומקשים: \u0003שפיר קאמרי ליה רבנן\u0004 \u0005[יפה אמרו לו חכמים]\u0006 \u0003לר' יהודה,\u0004 ומה משיב הוא על דבריהם? ומשיבים: \u0003ר' יהודה\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכך \u0003אומר\u0004 ר' יהודה ש\u0003אין דם מבטל דם.\u0004","ומביאים עוד, \u0003ר' שמעון אומר:\u0004 האדם ה\u0003צלוב על העץ,\u0004 ומת בצליבתו, \u0003שדמו\u0004 אינו נוטף תחתיו אלא \u0003שותת\u0004 בקילוח רצוף \u0003לארץ, ונמצא תחתיו רביעית דם\u0004 — הרי זה דם \u0003טמא.\u0004 \u0003ר'\u0004 \u0003יהודה מטהר,\u0004 וטעמו: \u0003ש\u0004כן \u0003אני אומר\u0004 כי \u0003טפה של\u0004 דם שיצאה לאחר \u0003מיתה עומדת לו על גב העץ,\u0004 ואילו רביעית הדם שתחת הצלוב יצאה ממנו בעודו חי.","ומקשים על דברי ר' יהודה: \u0003ור' יהודה\u0004 שאמר כן במחלוקתו עם ר' שמעון \u0003נימא איהו לנפשיה\u0004 \u0005[שיאמר כן לעצמו],\u0006 שגם בהרוג המוטל במיטה ודמו מטפטף לגומה, שאמר שהוא טמא (מפני שהטיפה של מיתה מעורבת בו, כמובא בעמוד הקודם), יאמר שהריהו דם טהור, מפני \u0003\"שאני אומר\u0004 כי \u0003טפה של מיתה עומדת על גב המטה\"!\u0004 ומשיבים: ר' יהודה אומר כן רק בעץ התליה, ולא בהרוג המוטל במיטה, כי \u0003שאני\u0004 \u0005[שונה]\u0006 הוא ההרוג המוטל \u0003במטה\u0004 — \u0003דמחלחלה\u0004 \u0005[שמחלחלת]\u0006 המיטה את הדם הנשפך עליה, מה שאין כן בעץ.","\u0003בראשונה היו\u0004 חכמים \u0003אומרים\u0004 כי האשה שילדה ועברו עליה ימי טומאה (שבעה לבן, וארבעה עשר לבת), וטבלה, והריהי מעתה \u0003יושבת על דם טהור,\u0004 שאף שמותרת בימים אלה לשמש עם בעלה, הריהי נחשבת כטבול יום שלא העריב שמשו (הנחשב שני לטומאה, ועושה שלישי בתרומה), \u0003היתה מערה\u0004 (שופכת) \u0003מים\u0004 מהכלי שבידה \u0003ל\u0004צורך הדחתו של קרבן ה\u0003פסח.\u0004 כיון שאין היא נוגעת אלא בכלי, ולא במימיו, וכלל הוא שאין השני לטומאה מטמא את הכלי. ואולם במים עצמם לא תגע (אף שחולין הם, ואין טבול יום פוסל את החולין), שכן מים אלה הריהם חולין שנעשו על טהרת הקודש, שהריהם באים לקרבן הפסח.","ברם \u0003חזרו\u0004 חכמים \u0003לומר\u0004 בדינה של היושבת על דמי טהרה ש\u0003הרי היא כמגע\u0004 (כדינו של הנוגע) ב\u0003טמא מת,\u0004 שהוא ראשון לטומאה המטמא אף כלים, \u0003ל\u0004ענין \u0003קדשים.\u0004 ואולם לענין החולין (ואף החולין שנעשו על טהרת הקודש, שאינם קודש ממש), כמים אלה שמדיחים בהם את קרבן הפסח — הריהי מותרת לא רק לערות מים מהכלי שבידה על הקרבן, אלא אף לגעת בהם עצמם. שכן הריהי נחשבת כשני לטומאה, ואין שני עושה שלישי בחולין, אלה \u0003כדברי בית הלל.\u0004 \u0003בית שמאי אומרים: אף כטמא מת\u0004 היא נחשבת בימי טהרתה, ולכך הריהי כאב הטומאה, ומטמאת את הכלי שמערה בו מים לקרבן הפסח, ואסורה בכך.","ומבררים את דברי משנתנו: בתחילה שנינו בה שהיושבת בימי טהרה \u0003מערה\u0004 מים מהכלי שבידה על קרבן פסח. ויש לדייק: לערות מים מן הכלי — \u0003אין\u0004 \u0005[כן]\u0006 מותרת היא, ואולם \u0003נוגעת\u0004 במים עצמם — \u0003לא.\u0004 ומכאן נסיק, \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 ש\u0003חולין שנעשו על טהרת הקדש,\u0004 דוגמת מים אלה שנעשו בטהרת הקודש, לצורך הדחת קרבן הפסח — \u0003כקדש דמו\u0004 \u0005[דומים,\u0006 נחשבים\u0005].\u0006","ומעתה \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003חזרו לומר\u0004 ש\u0003הרי היא כמגע טמא מת לקדשים\u0004 שהוא ראשון לטומאה, ומכאן יש לדייק: דווקא \u0003ל\u0004ענין \u0003קדשים\u0004 עצמם — \u0003אין\u0004 \u0005[כן]\u0006 נחשבת היא כראשון לטומאה, ואולם \u0003לחולין\u0004 כמים אלה שמדיחים בהם את קרבן הפסח — \u0003לא\u0004 נחשבת היא כשני לטומאה, ולכך מותרת היא אף בנגיעה במים עצמם. ומכאן נסיק, \u0003אלמא\u0004 \u0005[הרי איפוא]\u0006 ש\u0003חולין שנעשו על טהרת הקדש\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כקדש דמו\u0004 \u0005[דומים,\u0006 נחשבים\u0005]. ומסבירים:\u0006","\u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 שהחמירה בדינו של טבול יום שהריהו כראשון לטומאה, כשיטת \u0005מי היא]?\u0006 — כשיטת התנא \u0003אבא שאול היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא שאול אומר: טבול יום\u0004 נחשב כ\u0003תחילה\u0004 (ראשון) לטומאה, \u0003ל\u0004ענין בשר ה\u0003קדש,\u0004 שבנגיעתו בקודש הריהו מטמא אותו ועושה אותו שני לטומאה, ובכך יש בו \u0003לטמא שנים\u0004 בקודש, את זה שהוא נגע בו (שנהיה שני לטומאה), וזה חוזר ומטמא את הקודש שנוגע בו והריהו שלישי לטומאה, \u0003ולפסול אחד.\u0004 שהשלישי לטומאה אינו מטמא את הקודש שנגע בו (שיחשב זה \"רביעי לטומאה\", ויטמא אחרים) אלא שפוסל הוא אותו לעצמו.","במשנה הקודמת שנינו שנחלקו בית שמאי ובית הלל בדרגת טומאתה של היושבת בימי טהרה לענין הקדשים, \u0003ו\u0004מוסיפים עתה כי \u0003מודים\u0004 בית שמאי לבית הלל \u0003שהיא\u0004 \u0003אוכלת\u0004 מלכתחילה \u0003במעשר,\u0004 וכדינו של טבול יום, שמותר הוא באכילת מעשר \u0003וקוצה לה\u0004 (חותכת מקצת בצק מן העיסה) להפרשת \u0003חלה, ומקפת\u0004 (ומקרבת) את הכלי בו נמצאת חתיכת הבצק שנלקחה מן העיסה אל העיסה, \u0003ו\u0004לאחר מכן היא \u0003קורא לה שם\u0004 חלה, שאומרת שחתיכה זו מופרשת למצות חלה, ומעתה נקראת היא \"חלה\".","\u0003ו\u0004עוד מודים בית שמאי לבית הלל ש\u0003אם נפל מרוקה\u0004 של היושבת בימי טהרה, \u0003ו\u0004כן אם נפל \u0003דם טהרה\u0004 (הדם שרואה בימי טהרה, שנחשב הוא כדם טהור), \u0003על ככר של תרומה\u0004 — \u0003שהוא טהור,\u0004 ככל משקה (נוזל המופרש מן הגוף, כרוק, דם, מי רגלים ודמעות) היוצא מטבול יום, שהריהו טהור.","ואולם עוד נחלקו בית שמאי ובית הלל בדינה של האשה שהשלימה את ימי טהרתה, לאחר לידת בן או בת, ש\u0003בית שמאי אומרים\u0004 כי אין די בטבילה לפני שהחלה במנין ימי טהרתה, כדי להתירה להיכנס למקדש ובאכילת תרומה (אם כהנת היא), אלא \u0003צריכה טבילה\u0004 אף \u0003באחרונה\u0004 בתום ימי טהרתה, \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 שהריהי סומכת על הטבילה שטבלה לפני שהחלה במנין ימי טהרתה, ולפיכך היא \u0003אינה צריכה\u0004 שוב ל\u0003טבילה באחרונה.\u0004","שנינו במשנתנו שאף לדעת בית שמאי האשה בימי טהרה רשאית לאכול במעשר. ומסבירים את טעם הדבר: שכן \u0003אמר מר\u0004 \u0005[החכם,\u0006 בברייתא\u0005]\u0006 בדינו של טבול יום, שלאחר ש\u0003טבל ועלה\u0004 מן הטבילה — הריהו \u0003אוכל במעשר,\u0004 אף שלא העריב עדיין שמשו. ואף היולדת היושבת בימי טהרתה, כיון שדינה כטבול יום מותרת במעשר.","\u0003ו\u0004עוד שנינו במשנתנו כי הריהי \u0003קוצה לה חלה,\u0004 ואינה מטמאה את העיסה בכך. ומסבירים: שכן \u0003חולין הטבולין\u0004 (שבכלל \"טבל\" הם, האסורים באכילה, ומשום שעדיין לא תוקנו בהפרשה הראויה), וכגון עיסה זו שנלקח ממנה מקצת הבצק \u0003ל\u0004צורך הפרשת \u0003חלה\u0004 ממנה — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כחלה דמו\u0004 \u0005[נחשבים]\u0006 הם, ואינם כקדשים הנטמאים על ידי האשה בימי טהרה.","עוד שנינו בדרך הפרשת החלה, שלאחר שנתנה את חתיכת הבצק שהפרישה מן העיסה בתוך כלי, הריהי \u0003מקפת\u0004 (מקרבת) את הכלי שבו בצק זה אל העיסה. ומסבירים: שכן \u0003אמר מר\u0004 \u0005[החכם,\u0006 בברייתא\u0005]\u0006 כי \u0003מצוה לתרום\u0004 (להפריש תרומות ומעשרות, וכיוצא בזה הפרשת חלה) \u0003מן\u0004 הדבר \u0003המוקף\u0004 (הסמוך).","עוד שנינו בדרך הפרשת החלה, שלאחר שהניחה את מקצת הבצק בתוך כלי הסמוך לעיסה הריהי \u0003קורא לה שם.\u0004 ומסבירים כי היה צורך לתנא להשמיענו כן, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 ש\u0003נגזור\u0004 בה לאסור עליה לקרוא שם לחלה, מפני החשש \u0003דלמא אתי למנגע\u0004 \u0005[שמא\u0006 בתוך כך \u0005תבוא לגעת]\u0006 \u0003בה מאבראי\u0004 \u0005[מבחוץ],\u0006 ותטמא בכך את החלה — לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא, \u0005משמיע לנו]\u0006 שאין חוששים לכך.","עוד שנינו במשנתנו כי מודים בית שמאי לבית הלל ש\u0003אם נפל מרוקה\u0004 או מדם טהרתה של היושבת בימי טהרה על ככר של תרומה, שלא נטמא הככר בכך. ומסבירים: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 כי כל \u0003משקה\u0004 (נוזל המופרש מן הגוף, כרוק, דם, מי רגלים ודמעות) של \u0003טבול יום (משקין היוצאין ממנו),\u0004 דינם \u0003כ\u0004דין ה\u0003משקין\u0004 שטבול יום \u0003נוגע בהם.\u0004 \u0003ואלו ואלו,\u0004 הן המשקים היוצאים ממנו והן המשקים שנגע בהם, \u0003אינן מטמאין,\u0004 שכן הריהם חולין, ואין טבול יום מטמא את החולין (מאחר שאין הוא אלא שני לטומאה, ואין שני עושה שלישי בחולין). ומסייגים: \u0003חוץ ממשקה\u0004 היוצא מן \u0003הזב\u0004 — \u0003שהוא אב הטומאה,\u0004 והריהו מטמא.","עוד שנינו במשנתנו כי נחלקו \u0003בית שמאי\u0004 ובית הלל אם זו שהשלימה את מנין ימי טהרתה נצרכת לשוב ולטבול על מנת שתוכל להיכנס למקדש או לאכול בתרומה (אם כהנת היא). שלדעת בית שמאי הריהי צריכה לשוב ולטבול, ולדעת בית הלל אין היא נזקקת לכך. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם,\u0006 במה נחלקו\u0005]?\u0006 \u0003אמר רב קטינא:\u0004 בדינו של \u0003טבול יום\u0004 שעבר זמן \u0003ארוך\u0004 מזמן שטבל הוא ש\u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת בית שמאי, כיון שעבר זמן רב מאז שטבלה (שלושים ושלושה ימים ביולדת זכר, וששים ושישה ימים ביולדת נקבה), אין היא יכולה לסמוך על טבילה זו, ולדעת בית הלל הריהי סומכת עליה.","האשה \u0003הרואה\u0004 דם ב\u0003יום\u0004 ה\u0003אחד עשר\u0004 (שהוא סוף תקופת ימי זיבה), ואינה מותרת לשמש עם בעלה, אלא לאחר שתשמור יום אחד בטהרה (כ\"שומרת יום כנגד יום\"), \u0003ו\u0004היא לא נהגה כן, אלא \u0003טבלה לערב\u0004 (ליל היום השנים עשר) \u0003ומשמשה\u0004 (ושימשה) עם בעלה.","\u0003בית שמאי אומר:\u0004 מאחר ולא שמרה יום כנגד יום — הריהי נחשבת כזבה, ולכך היא ובעלה (כדין הבועל את הזבה) \u0003מטמאין\u0004 את ה\u0003משכב\u0004 ששכבו עליו \u0003ו\u0004את ה\u0003מושב\u0004 שישבו עליו, לטמא את האוכלים והמשקים שנגעו בהם. \u0003וחייבין\u0004 הם \u0003בקרבן\u0004 חטאת, כדין בעילת זבה."],["\u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 כי אמנם הריהם מטמאים משכב ומושב, ואולם הם \u0003פטורים מן הקרבן,\u0004 מאחר שאין היום השנים עשר מצטרף ליום האחד עשר לזיבה (ולכך, אם תראה ביום השנים עשר וביום השלושה עשר — אין היא נעשית בכך זבה גדולה), מעתה אף אין זו שרואה ביום אחד עשר צריכה לשמור יום כנגד יום. ומטעם זה, אין הם מביאים קרבן על תשמיש זה.","ואם \u0003טבלה\u0004 רק \u0003ביום\u0004 \u0003של אחריו,\u0004 היום השנים עשר, \u0003ושמשה את ביתה\u0004 (בלשון נקיה: עם בעלה) במהלך היום, שמותרת בכך כיון ששמרה מקצת היום (בתוך אחד עשר יום אסורה היא לשמש עם בעלה באופן זה, אף ששמרה מקצת היום, ומפני החשש שמא תראה לאחר מכן דם, ויצטרפו הימים לזיבה), \u0003ואחר כך ראתה\u0004 דם — \u0003בית שמאי אומרים:\u0004 הריהם \u0003מטמאין משכב ומושב\u0004 מדברי חכמים (שהרי מן התורה טבילתה זו נחשבת לה, שכן שמרה מקצת היום), שגזרו בה משום העושה כן כשהיא שומרת יום כנגד יום, בתוך אחד עשר ימי הזיבה, ואולם הריהם \u0003פטורין מן הקרבן,\u0004 שהרי שמרה מקצת היום, ואין הראיה שראתה לאחר התשמיש נחשבת להצטרף לזיבה, כיון שהיתה בתקופת נידה.","\u0003ו\u0004אילו \u0003בית הלל אומרים: הרי זה\u0004 הבעל הינו \u0003גרגרן\u0004 (זולל למילוי תאוותו), שלא התאפק עד שתסיים שמירת כל היום השנים עשר, ואולם אין זו עבירה ממש, ולכך אין אלה מטמאים משכב ומושב. \u0003ומודים\u0004 בית הלל לבית שמאי \u0003ב\u0004זו ה\u0003רואה בתוך אחד עשר יום, וטבלה לערב ושמשה\u0004 עם בעלה, ובלא ששמרה יום טהור כנגדו — \u0003ש\u0004הריהם \u0003מטמאין משכב ומושב,\u0004 שנחשבת זבה, מאחר ולא שמרה יום כנגד יום, ובעלה נחשב כבועל זבה. \u0003וחייבין בקרבן.\u0004","ואם \u0003טבלה ביום של אחריו,\u0004 ביום השנים עשר, ולאחר ששמרה מקצת היום עמדה \u0003ושמשה\u0004 עם בעלה — \u0003הרי זה תרבות\u0004 (הנהגה) \u0003רעה,\u0004 שהרי אפשר שתראה לאחר התשמיש, ותצטרף ראיה זו לראיה קודמת שראתה, והריהי זבה, ולא עלתה לה טבילה זו. \u0003ו\u0004לכך משום הספק דין \u0003מגען\u0004 (טהרות שנגעו בהן) \u0003ו\u0004כן דין \u0003בעילתן\u0004 (אם יתחייבו עליה קרבן חטאת כביאת זבה) \u0003תלויין\u0004 באם תראה באותו יום שטבלה. שאם תראה — הטהרות טמאות, וחייבים בקרבן, ואם לא תראה — אין החטאות טמאות, ופטורים מלהביא קרבן.","שנינו במשנתנו שנחלקו בית הלל ובית שמאי בחיוב זו שראתה ביום אחד עשר וטבלה בערב בקרבן על כך. ומביאים עוד בענין מחלוקת זו ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003ושוין\u0004 בית הלל ובית שמאי בדעתם \u0003ב\u0004זו ה\u0003טובלת\u0004 ב\u0003לילה ל\u0004טהרת \u0003זבה\u0004 קטנה — \u0003שאינה טבילה.\u0004 \u0003ו\u0004כן \u0003שוין\u0004 בית הלל ובית שמאי \u0003ב\u0004דינה של ה\u0003רואה בתוך אחד עשר יום\u0004 (ימי זיבה), שהיא איפוא זבה קטנה, וצריכה שימור יום שלא תראה בו, ולטבול למחרת ביום, כדי לשמש עם בעלה. \u0003ו\u0004אילו זו לא שימרה את יום המחרת, אלא \u0003טבלה לערב ושמשה\u0004 עם בעלה — אין טבילת הלילה עולה לה, והרי תשמיש זה נחשב להם כמי ששימשו בו ביום ולפני טבילה. ולכך היא (וכן בועלה) \u0003מטמאה משכב ומושב, וחייבין בקרבן\u0004 אף לדעת בית הלל.","ו\u0003לא נחלקו\u0004 בית שמאי ובית הלל \u0003אלא ב\u0004זו הרואה ב\u0003יום אחד עשר יום\u0004 בתקופת ימי זיבה, וטבלה בערב ושימשה עם בעלה. \u0003שבית שמאי אומרים\u0004 כי דינה כשל זבה קטנה, ולכך הריהם \u0003מטמאין משכב ומושב וחייבין בקרבן.\u0004 \u0003ו\u0004אילו \u0003בית הלל פוטרין\u0004 אותם \u0003מקרבן,\u0004 שכן אין חובת שמירה על ראיית היום האחד עשר, שאף אם תראה ביום השנים עשר, אין זו מצטרפת לראייה הקודמת לעשותה זבה גדולה.","\u0003אמרו להן בית שמאי לבית הלל\u0004 בשאלה על שיטתם: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 דינה של הרואה ב\u0003יום אחד עשר\u0004 מתקופת ימי זיבה, שלדעתכם אינה צריכה שימור, \u0003מ\u0004דינה של זו הרואה ב\u0003יום\u0004 שהוא \u0003תוך\u0004 תקופת \u0003אחד עשר\u0004 ימי הזיבה, שצריכה שימור. והרי \u0003אם שיוה\u0004 (שווה) \u0003לו ל\u0004ענין \u0003טומאה\u0004 של משכב ומושב, שבזו ובזו הריהם מטמאים משכב ומושב (שכן אף בית הלל מודים בכך), מעתה מדוע \u0003לא ישוה לו\u0004 גם \u0003ל\u0004ענין \u0003קרבן,\u0004 שיתחייבו בקרבן אף ברואה ביום אחד עשר וטבלה בערב?","\u0003אמרו להן בית הלל לבית שמאי\u0004 בתשובה: \u0003לא,\u0004 אין זו שאלה. שכן \u0003אם אמרת\u0004 שחייבים בקרבן \u0003ב\u0004רואה ב\u0003תוך אחד עשר יום\u0004 — טעם יש לדבר: \u0003שכן יום שלאחריו מצטרף עמו לזיבה\u0004 (שאם תראה גם בימים שלאחרי כן, הריהי זבה גדולה), \u0003תאמרו\u0004 כן גם ברואה \u0003ביום אחד עשר, שאין יום שלאחריו שנצטרף עמו לזיבה?!\u0004","\u0003אמרו להם בית שמאי\u0004 לבית הלל: \u0003השוו מדותיכם\u0004 (שיטתכם בהלכה), \u0003אם\u0004 הרואה ביום אחד עשר \u0003שיוה לו\u0004 לרואה בתוך אחד עשר הימים, \u0003ל\u0004ענין \u0003טומאה\u0004 — \u0003ישוה לו\u0004 גם כן \u0003ל\u0004ענין ה\u0003קרבן, ואם לא שיוה לו ל\u0004ענין ה\u0003קרבן\u0004 — כמו כן, \u0003לא ישוה לו לטומאה.\u0004","\u0003אמרו להם בית הלל\u0004 לבית שמאי בתשובה: \u0003אם\u0004 אמנם אנו משווים את הרואה ביום אחד עשר לרואה בתוך תקופת אחד עשר הימים, אין זה אלא כשבכך \u0003הביאנוהו לידי טומאה\u0004 — והרי זה \u0003להחמיר\u0004 עליו, גזירה מפני הרואה בתוך אחד עשר יום. ואולם \u0003לא\u0004 נשווה אותו לרואה בתוך תקופת אחד עשר יום שבכך \u0003נביאהו לידי קרבן\u0004 — והרי זה \u0003להקל\u0004 עליו, להתיר לו להביא חולין לעזרה.","\u0003ועוד\u0004 הוסיפו בית הלל בתשובתם לבית שמאי: \u0003מ\u0004תוך \u0003דבריכם\u0004 שלכם \u0003אתם נושכין\u0004 (מוקשים) באותה קושיה שהקשיתם עלינו, שאף אתם אינכם משווים את שיטתכם בהלכה. \u0003ש\u0004הרי \u0003אתם אומרין\u0004 בדינה של זו שראתה ביום אחד עשר, ולא טבלה בו בערב, אלא \u0003טבלה\u0004 ב\u0003יום שלאחריו\u0004 (ועשתה איפוא מקצת שימור) \u0003ושמשה\u0004 עם בעלה, \u0003ואחר כך ראתה\u0004 — שהריהי \u0003מטמא משכב ומושב, ו\u0004אולם \u0003פטורה מן הקרבן.\u0004 מעתה \u0003אף אתם השוו מדותיכם,\u0004 שהרי \u0003אם\u0004 דינה של הטובלת ביום שנים עשר \u0003שיוה לו ל\u0004דינה של הטובלת במוצאי יום אחד עשר לענין \u0003טומאה,\u0004 מעתה \u0003ישוה לו\u0004 גם כן \u0003ל\u0004ענין \u0003קרבן,\u0004 ואף בטובלת ביום שנים עשר יביאו קרבן על שימושם.","\u0003ואם\u0004 הוא \u0003לא שיוה לו ל\u0004ענין \u0003קרבן,\u0004 שבטובלת ביום שנים עשר פטורים מן הקרבן, ובטובלת במוצאי יום אחד עשר חייבים בקרבן — מעתה גם \u0003לא ישוה לו ל\u0004ענין \u0003טומאה,\u0004 ובטובלת ביום שנים עשר אין הם מטמאים משכב ומושב! \u0003אלא\u0004 אף אתם סבורים שמשווים אנו רק \u0003להחמיר\u0004 (כבדין הטומאה) \u0003ולא להקל\u0004 (בדין הקרבנות, להביא חולין לעזרה), \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בהשוואת הרואה ביום אחד עשר לרואה בתוך תקופת אחד עשר, \u0005גם כן]\u0006 — משווים אנו רק \u0003להחמיר ולא להקל.\u0004","ומביאים עוד בבירור שיטת בית שמאי ממה ש\u0003אמר רב הונא:\u0004 האשה הרואה בתוך אחד עשר יום של תקופת זיבות, והריהי צריכה לשמור יום, ולא שמרה את כל יום המחרת אלא מקצתו, שהלכה וטבלה בו ולא המתינה ללילה — \u0003משכבה ומושבה ש\u0004שכבה או ישבה עליהם \u0003ב\u0004יום ה\u0003שני\u0004 (ביום שלמחרת יום ראייתה), לאחר טבילתה, \u0003בית שמאי מטמאין\u0004 אותה, \u0003אף על פי שטבלה\u0004 ביום שלמחרת, ולאחר ששמרה מקצת היום, ו\u0003אף על פי שלא ראתה\u0004 לאחר שטבלה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכך גזרו בה חכמים, \u0003כיון\u0004 ש\u0003אילו חזיא\u0004 \u0005[ראתה]\u0006 ביום שלמחרת ולאחר הטבילה — הריהי \u0003מטמאה\u0004 מן התורה, לכך \u0003השתא\u0004 \u0005[עכשיו],\u0006 אף שלא ראתה לאחר הטבילה, \u0003נמי מטמיא\u0004 \u0005[גם כן מטמאה].\u0006","\u0003אמר רב יוסף\u0004 בתמיהה על דברי רב הונא אלה: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]\u0006 בדבריו, והרי \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו שזו שראתה ביום אחד עשר, ו\u0003טבלה\u0004 ב\u0003יום שלאחריו, ושמשה את ביתה, ואחר כך ראתה\u0004 — \u0003בית שמאי אומרים:\u0004 הריהי \u0003מטמאה משכבות ומושבות, ופטורה מן הקרבן!\u0004 וטומאתה מגזירת חכמים מפני זו שראתה בתוך אחד עשר יום (שהריהי טמאה מן התורה). וכמו כן יודעים אנו שחכמים גזרו בזו שראתה בתוך אחד עשר יום וטבלה למחרת ולא ראתה מפני זו שטבלה למחרת היום וראתה (שהריהי טמאה מן התורה)!","\u0003אמר רב כהנא\u0004 בתשובה לשאלת רב יוסף: ממשנתנו לא היינו יודעים את דינו של רב הונא, שכן היינו אומרים כי דווקא במקרה ש\u0003ראתה\u0004 אחר טבילתה, הוא שגזרו בה חכמים, כי \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר, שהרי ראתה. מה שאין כן בדברי רב הונא שגזרו חכמים אף באופן זה שלא ראתה ביום שלמחרת ראייתה ולאחר טבילתה.","\u0003אמר רב יוסף\u0004 בדחיית דברי רב כהנא אלה: \u0003ו\u0004אף \u0003כי\u0004 \u0005[כאשר]\u0006 אמנם \u0003ראתה\u0004 ביום השנים עשר, למחרת ראייתה ביום האחד עשר, \u0003מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005],\u0006 אין זו סיבה לגזור עליה מפני זו שראתה בתוך תקופת האחד עשר ימים של זיבות, שהרי \u0003ראייה\u0004 זו של יום שנים עשר, אינה ראיה של זיבות, אלא ראיה של \u0003נדה היא,\u0004 שהרי היום השנים עשר הוא היום הראשון לתקופת ימי הנדה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף\u0004 בהסבר דברי \u0003רב כהנא:\u0004 \u0003הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו],\u0006 שהתקשה בדברי רב הונא האומר שגזרו חכמים ברואה בתוך תקופת זיבתה, וטבלה למחרת, שטמאה אף שלא ראתה לאחר טבילתה, וכגזירה מפני הרואה באותו יום: \u0003בשלמא היכא\u0004 \u0005[זה נוח היכן,\u0006 במקרה\u0005]\u0006 ש\u0003ראתה\u0004 ביום השנים עשר — \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003ראייה\u0004 של \u0003נדה אטו\u0004 \u0005[משום]\u0006 \u0003ראייה\u0004 של \u0003זבה,\u0004 וכדין האמור במשנתנו. \u0003אלא היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא ראתה,\u0004 וכדין האמור בדברי רב הונא — \u0003מאי נגזר\u0004 \u0005[\u0006מפני \u0005מה נגזור]\u0006 \u0003בה?\u0004","\u0003ועוד\u0004 הקשה על דברי רב הונא, שכן \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנה בדין טומאתו של הזב \u0003הרואה ראייה אחת של זוב,\u0004 וטבל — \u0003בית שמאי אומרים:\u0004 דינו \u0003כ\u0004דינה של ה\u0003שומרת יום כנגד יום\u0004 (זבה קטנה), למחרת ראייתה, שטובלת ושומרת יום זה, והמעשרות שנגעה בהם לאחר טבילתה תלויים ועומדים: שאם תראה בהמשך היום — הריהם נטמאים למפרע. ואף זב זה שטבל, טומאתו תלויה: שאם יראה שוב, הרי זו מצטרפת לזיבה, וייטמאו המעשרות. \u0003ו\u0004אילו \u0003בית הלל אומרים\u0004 כי דינו של זב זה שטבל הריהו \u0003כבעל קרי\u0004 הנטהר מטומאתו בטבילתו, ולכך המעשרות שנגע בהם טהורים. שאף אם יראה שוב לאחר טבילתו — אין הוא נטמא כזב אלא מכאן והלאה."],["\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 בדינו של הזב בראייתו הראשונה, כי הטהור \u0003המסיט את הראייה\u0004 (טיפת הזוב) הראשונה, מהו דינו שייטמא במשא, ויטמא את הטהרות שנגע בהן — \u0003בית שמאי אומרים\u0004 כי \u0003תולין\u0004 (מסופקים) אנו בדינו של זה. שכן אם יחזור ויראה היום עוד זיבה, נעשה הוא בכך למפרע זב גמור, והרי הזוב מטמא במשא, ונטמא. ואם לא ישוב ויראה ראיית זוב נוספת — אין זה נטמא בטומאת משא. \u0003ו\u0004אילו \u0003בית הלל מטהרין\u0004 את הטהור שהסיט. שכן עתה אינו אלא כבעל קרי, שאינו מטמא בהיסט. ואף אם ישוב הזב ויראה לאחר מכן, אינו מטמא בזיבה למפרע, אלא מכאן והלאה.","וכיוצא בדבר נחלקו בדינם של \u0003משכבות ומושבות ש\u0004שכב או ישב עליהם \u0003בין ראייה ראשונה לראייה שנייה,\u0004 שלדעת \u0003בית שמאי\u0004 — הרי אנו \u0003תולין\u0004 בדינם של אלה, ולא יקבע דינם אלא משיוודע אם ראה ראיה נוספת של זיבה אם לא. \u0003ו\u0004אילו \u0003בית הלל מטהרין\u0004 משכבות ומושבות אלה, אף אם לאחר מכן ישוב ויראה זיבה.","\u0003ו\u0004מעתה נלמד, שהרי \u0003קתני רישא\u0004 \u0005[שנינו\u0006 ב\u0005תחילת\u0006 המשנה שבמסכת זבים\u0005]\u0006 כי הזב \u0003הרואה ראייה אחת של זוב, בית שמאי אומרים\u0004 שדינו \u0003כ\u0004דינה של ה\u0003שומרת יום כנגד יום,\u0004 \u0003אלמא\u0004 \u0005[נסיק]\u0006 מכאן כי אף ב\u0003שומרת יום כנגד יום ל\u0004שיטת \u0003בית שמאי\u0004 אנו \u0003תולין.\u0004 שאין זו טומאה וודאית, אלא מן הספק, ושלא כדברי רב הונא שלדעת בית שמאי השומרת יום כנגד יום מטמאת (מדברי חכמים) בטומאה וודאית!","ומשיבים: אין זו ראיה, כי \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 \u0003תשנה בדברי המשנה\u0004\u0005]\u0006 שדינו של זב זה כדינה של \u0003שומרת יום כנגד יום, אלא אימא\u0004 \u0005[אמור]\u0006 שדינו של הזב \u0003כ\u0004דינו של ה\u0003בועל שומרת יום כנגד יום\u0004 לאחר שטבלה. שאין משכבו ומושבו מטמאים (מדברי חכמים) בוודאות, אלא מן הספק.","ומבררים: \u0003מאי שנא איהו\u0004 \u0005[\u0006ב\u0005מה שונה הוא,\u0006 הבועל שומרת יום כנגד יום\u0005],\u0006 ש\u0003לא מטמא משכב ומושב\u0004 ששכב או ישב עליהם, \u0003ומאי שנא איהי\u0004 \u0005[\u0006ב\u0005מה שונה היא,\u0006 שומרת יום כנגד יום\u0005],\u0006 \u0003דמטמיא ליה\u0004 \u0005[שמטמאה אותו,\u0006 את משכבה ומושבה\u0005]?\u0006","\u0003איהו\u0004 \u0005[הוא]\u0006 \u0003דלא שכיחי ביה\u0004 \u0005[שאין מצויים בו]\u0006 \u0003דמים\u0004 — \u0003לא גזור ביה רבנן\u0004 \u0005[גזרו בו חכמים]\u0006 שיטמא משכב ומושב אלא מן הספק, והריהם טהורים אם לא חזרה וראתה. ואילו \u0003איהי דשכיחי\u0004 \u0005[היא, שמצוים]\u0006 \u0003בה דמים\u0004 — \u0003גזור\u0004 \u0005[גזרו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים],\u0006 שטמאה מן הודאי, אף שלא חזרה וראתה ביום זה שטבלה בו.","וממשיכים: \u0003ו\u0004מאחר שגזרו חכמים באשה (ומשום הטעם שמרובים דמיה), מעתה \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה הוא]\u0006 \u0003משכב ומושב\u0004 ששכבה או ישבה עליו, \u0003דמטמיא ליה\u0004 \u0005[שמטמאה אותו],\u0006 \u0003ומאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה הוא]\u0006 ה\u0003בועל,\u0004 \u0003דלא מטמיא ליה\u0004 \u0005[שאין היא מטמאה אותו]?\u0006","ומסבירים: \u0003משכב ומושב דשכיח\u0004 \u0005[שמצוי]\u0006 הוא, שתשכב ותשב עליהם — הריהי \u0003מטמיא ליה\u0004 \u0005[מטמאת אותו],\u0006 ואולם \u0003בועל דלא שכיח\u0004 \u0005[שאין\u0006 זה \u0005מצוי]\u0006 — \u0003לא מטמיא\u0004 \u0005[אינה מטמאה].\u0006","ומוסיפים עוד לשאול על דברי רב הונא מדברי משנתנו, שכן \u0003תנן\u0004 \u0005[שנינו]\u0006 בזו שראתה ביום אחד עשר לימי זיבות, ו\u0003טבלה\u0004 ב\u0003יום שלאחריו,\u0004 ששמרה מקצת היום, \u0003ושמשה\u0004 באותו יום עם בעלה — \u0003הרי זו תרבות\u0004 (הנהגה) \u0003רעה,\u0004 ו","\u0003מגען\u0004 (לענין טומאה וטהרה) \u0003ובעילתן\u0004 (לענין הבאת קרבן על כך) \u0003תלויין,\u0004 שאם תראה באותו יום — הרי זה מגע הזבה המטמא, והריהם חייבים בקרבן. ואם לא תראה — אין זה כמגע הזבה ואין הם חייבים בקרבן. ומעתה נשאל: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 משנה זו כ\u0003דברי הכל היא,\u0004 ואף לשיטת בית שמאי. ונמצא איפוא כי גם לדעת בית שמאי אין השומרת יום כנגד יום מטמאת ודאי אלא מן הספק, ושלא כדברי רב הונא!","ודוחים: \u0003לא,\u0004 אין המשנה כדברי הכל, אלא כשיטת \u0003בית הלל היא,\u0004 ולא כבית שמאי. ומביאים ראיה לדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להם ר'\u0004 \u0003יהודה לבית הלל: וכי ל\u0004הנהגה \u0003זו אתם קורין\u0004 רק \u0003\"תרבות רעה\", והלא לא נתכוון זה אלא לבעול את הנדה!\u0004 ותוהים על דבריו: \u0003נדה סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר, והרי המדובר בשומרת יום כנגד יום לזיבתה?","ומתקנים: \u0003אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור]\u0006 בדברי ר' יהודה לבית הלל \"והלא לא נתכוון זה אלא \u0003לבעול את הזבה\".\u0004 ואף על נוסח דברים זה תוהים: \u0003זבה סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר, והרי המדובר בשומרת יום כנגד יום לזיבתה, ולא במי שהיא זבה? ומתקנים: \u0003אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור]\u0006 בדברי ר' יהודה לבית הלל \"והלא לא נתכוון זה אלא \u0003לבעול שומרת יום כנגד יום\".\u0004 נמצאנו למדים כי דברי סוף משנתנו הריהם לשיטת בית הלל, ולא לשיטת בית שמאי.","ומביאים עוד מדברי חכמים בדינה של הרואה בסוף תקופת ימי הזיבות. \u0003איתמר\u0004 \u0005[נאמר]\u0006 האשה הרואה ביום ה\u0003עשירי\u0004 בימי זיבותה, \u0003ר' יוחנן אמר:\u0004 הרואה ביום ה\u0003עשירי\u0004 דינה \u0003כ\u0004זו הרואה ביום ה\u0003תשיעי\u0004 בתקופת ימי זיבות. \u0003מה\u0004 הרואה ביום ה\u0003תשיעי\u0004 — הריהי \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003שימור\u0004 (כדינה של השומרת יום כנגד יום. שהרי אם תראה ביום העשירי וביום האחד עשרה, הרי אלה שלוש ראיות המטמאות אותה כזבה גדולה). \u0003אף\u0004 הרואה ביום ה\u0003עשירי\u0004 — \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003שימור,\u0004 אף שאין אפשרות שתהא בכך זבה (שכן אף אם תראה ביום האחד עשר, אין לה אלא שתי ראיות בלבד).","ואילו \u0003ריש לקיש אמר:\u0004 הרואה ביום ה\u0003עשירי\u0004 דינה \u0003כ\u0004של הרואה ביום ה\u0003אחד עשר.\u0004 \u0003מה\u0004 הרואה ביום ה\u0003אחד עשר\u0004 — \u0003לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003שימור,\u0004 שהרי למחרת אין זה שוב מכלל ימי זיבתה. \u0003אף\u0004 הרואה ביום ה\u0003עשירי\u0004 — \u0003לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003שימור.\u0004","ומביאים כי \u0003איכא דמתני לה אהא\u0004 \u0005[יש ששונה אותה\u0006 מחלוקת בין ר' יוחנן לריש לקיש \u0005על זו],\u0006 בהקשר למה ששנינו בדין חלות ורקיקים הבאים כמנחות במקדש, שחייבות במתן מחצית לוג שמן. ודרש כן ר' עקיבא מדרשות הכתובים, שנאמר בהם \"בשמן\" \"בשמן\" (ויקרא ז, יב), ו\u0003אמר לו ר' אלעזר בן עזריה לר' עקיבא: אפילו אתה מרבה \"בשמן\" [\" בשמן\"] כל היום כולו\u0004 — \u0003איני שומע לך\u0004 (איני מקבל את דבריך) שיש ללמוד את ההלכות הללו מן הכתובים, \u0003אלא\u0004 ההלכה האומרת ש\u0003חצי לוג שמן\u0004 הניתן \u0003ל\u0004לחמי \u0003תודה, ו\u0004כן ההלכה האומרת ש\u0003רביעית יין\u0004 היא השיעור האסור \u0003לנזיר\u0004 בשתיה, שהריהו לוקה אם שתה יין כשיעור זה. \u0003ו\u0004כן ההלכה בדינה של האשה הרואה דם בפרק הזמן של \u0003אחד עשר יום שבין\u0004 תקופת \u0003נדה ל\u0004תקופת \u0003נדה\u0004 — כל אלה הן \u0003הלכה למשה מסיני.\u0004","ונשאלה השאלה \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003הלכה\u0004 זו שנאמרה לתקופת אחד עשר הימים שבין נדה לנדה? ונחלקו בדבר ר' יוחנן וריש לקיש, ש\u0003ר' יוחנן אמר:\u0004 הכוונה ל\u0003הלכה\u0004 אחת שנבדל בה יום ה\u0003אחד עשר\u0004 מעשרת הימים האחרים. ו\u0003ריש לקיש אומר\u0004 כי הכוונה היא לשתי \u0003הלכות\u0004 שנבדל בהן יום ה\u0003אחד עשר\u0004 משאר הימים.","ומפרטים: \u0003ר' יוחנן אמר\u0004 כי ב\u0003הלכה\u0004 אחת נבדל יום ה\u0003אחד עשר\u0004 משאר הימים, שכן יום ה\u0003אחד עשר הוא\u0004 עצמו יום \u0003דלא בעי\u0004 \u0005[שאין צריך]\u0006 \u0003שימור,\u0004 ולענין שאם ראתה ביום זה — אין היא צריכה לשמור את יום המחרת. \u0003הא לאחריני\u0004 \u0005[הרי ל\u0006ימים \u0005אחרים]\u0006 שבתוך האחד עשר — הוא \u0003עביד\u0004 \u0005[עושה]\u0006 \u0003שימור,\u0004 שאם ראתה ביום העשירי, הריהי צריכה לשמור את היום האחד עשר. \u0003ו\u0004אילו \u0003ריש לקיש אמר\u0004 כי הכוונה היא לשתי \u0003הלכות\u0004 שבהן נבדל היום ה\u0003אחד עשר\u0004 משאר הימים: כי \u0003לא\u0004 \u0005[אין]\u0006 ראייה שראתה ביום ה\u0003אחד עשר בעי\u0004 \u0005[צריכה]\u0006 \u0003שימור\u0004 ביום השנים עשר. ושלא כשאר הימים, שראיית יום זה מצריכה שימור ביום המחרת. \u0003ו\u0004כן שיום האחד עשר, \u0003לא שימור לעשירי הוי\u0004 \u0005[הינו],\u0006 ומשום שראייה ביום העשירי לא מצריכה שמירה ביום המחרת. ואף בדבר זה נבדל היום האחד העשר משאר הימים.","ותוהים על דברי ר' אלעזר בן עזריה שאמר כי אחד עשר יום שבין נדה לנדה הריהם הלכה למשה מסיני: וכי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003הלכות\u0004 למשה מסיני \u0003נינהו\u0004 \u0005[הן],\u0006 והלא \u0003הני קראי נינהו\u0004 \u0005[אלה מקראות הן],\u0006 שמהן נלמדים אנו כך. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול\u0004 יהא הדין שכל אשה \u0003הרואה שלשה ימים\u0004 אף שחלים ימים אלה \u0003בתחילת\u0004 תקופת \u0003נדה,\u0004 ושלושה ימים אלה הם \u0003רצופים,\u0004 ש\u0003תהא\u0004 נחשבת בכך \u0003זבה,\u0004 ותתחייב איפוא בספירת שבעה נקיים ובהבאת קרבן לאחר מכן (כאמור בפרשת הזבה, ויקרא טו, כח—ל). שכן נאמר בזבה \"ואשה כי יזוב זוב דמה ימים רבים\" (ויקרא טו, כה), והרי \"ימים רבים\" אלה שלושה.","\u0003ו\u0004ב\u0003מה אני מקיים\u0004 את הכתוב בפרשיה הקודמת \"ו \u0003אשה כי תהיה זבה דם יהיה זבה\u0004 בבשרה שבעת ימים תהיה בנדתה\" (שם יט), שאין הכתוב מצריכה לטהרתה אלא טבילה לאחר שבעת ימים אלה, ובלא ספירה וקרבן — \u0003ב\u0004זו ה\u0003רואה יום אחד\u0004 בלבד, \u0003(אבל הרואה שלשה ימים בתחילה תהיה זבה).\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר):"],["\"ואשה כי יזוב זוב דמה ימים רבים \u0003\"בלא עת נדתה\" (על נדתה)\u0004 או כי תזוב על נדתה כל ימי זוב טומאתה כימי נדתה תהיה טמאה היא\" (ויקרא טו, כה), ובא הכתוב ללמדנו שלא נאמר דינה של הזבה אלא כשהיא רואה בזמן ה\u0003סמוך ל\u0004ימי \u0003נדתה,\u0004 ולא בזו הרואה בתוך ימי נדותה.","וממשיכים ודנים: \u0003ואין לי\u0004 ללמוד ממקרא זה \u0003אלא\u0004 לזו הרואה ביום השמיני לימי נדותה, שהוא היום ה\u0003סמוך ל\u0004שבעת ימי \u0003נדתה,\u0004 ואולם הרואה ביום התשיעי לימי נדותה, שהריהו \u0003מופלג\u0004 (מרוחק) \u0003לנדתה יום אחד, מנין\u0004 לי שאף היא באה בכך לדין זבה — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"או כי תזוב\u0004 על נדתה\", להורות כי אף הרואה ביום מרוחק משבעת ימי נדתה, באה בכך לכלל זבה.","וממשיכים ושואלים: ועדיין \u0003אין לי\u0004 ללמוד ממקרא זה \u0003אלא\u0004 לזו הרואה ב\u0003יום אחד\u0004 המרוחק משבעת ימי הנידות, ו\u0003מנין\u0004 לי שכך הוא הדין אף \u0003לרבות\u0004 את הרואה ביום שהוא \u0003מופלג שנים\u0004 ימים מתקופת נידותה, או \u0003שלשה, ארבעה, חמשה, ששה, ושבעה, שמונה, תשעה, עשרה, מנין\u0004 לי שבכל אלה הריהי באה לכלל זבה?","\u0003אמרת\u0004 (יש לך לומר) כי למדים אנו כן בדרך הדרשה הנקראת \u0003מה מצינו\u0004 (מצאנו), בהיקש לדבר הידוע לנו. שכן מוצאים אנו ברואה \u0003ב\u0004יום ה\u0003רביעי\u0004 שלאחר שבעת ימי נידותה — \u0003ש\u0004יום זה הריהו \u0003ראוי\u0004 גם \u0003לספירה\u0004 של שבעת ימי זיבה (כשראתה לזיבתה בשלושת הימים הראשונים שלאחר ימי נידותה). \u0003ו\u0004הרי גם \u0003ראוי לזיבה,\u0004 שתחול על ידו שם זבה (שהרי למדנו למעלה כי לא רק הרואה ביום השמיני לשבעת ימי נידות באה לכלל זבה, אלא אף הרואה ביום התשיעי (הוא היום השני שלאחר שבעת ימי נקיות). ונזקקת היא לעוד יומיים של ראייה שתיחשב על ידם זבה, שהם היום השלישי והיום הרביעי. \u0003אף אני אביא\u0004 את כל הימים שאחרי היום הרביעי, וכן את היום \u0003העשירי\u0004 שלאחר תקופת ימי נדות — \u0003ש\u0004אף הוא \u0003ראוי ל\u0004שמש כיום \u0003ספירה\u0004 של שבעת ימי נקיות לזיבה, \u0003ו\u0004כן \u0003ראוי\u0004 הוא \u0003ל\u0004שמש כיום המתחיל דין \u0003זיבה.\u0004","וממשיכים ושואלים: \u0003ומנין\u0004 שיש \u0003לרבות\u0004 אף את הרואה ביום \u0003אחד עשר\u0004 לאחר ימי נידותה, אף שיום זה אינו ראוי לשמש מאחד משבעת ימי נקיים (כשראתה בסמוך לתקופת נדתה) — לכך \u0003תלמוד לומר \"בלא עת נדתה\",\u0004 אף ביום זה שהוא רחוק ביותר מתקופת נדתה. וממשיכים ומבררים: אלא מעתה, \u0003יכול\u0004 יהא הדין \u0003שאני מרבה אף\u0004 את הרואה ביום \u0003שנים עשר\u0004 לתקופת נדתה, שאף זו באה לכלל זבה? \u0003אמרת\u0004 בתשובה לכך: \u0003לאו\u0004 \u0005[לא],\u0006 אין לומר כן.","","","","","","","","","","\u0003ו\u0004אם תשאל: \u0003מה ראית לרבות\u0004 לדין הזבה אף את הרואה ביום \u0003אחד עשר ולהוציא\u0004 (למעט) מכלל דין הזבה את הרואה ביום \u0003שנים עשר?\u0004 — \u0003מרבה אני\u0004 את הרואה ביום \u0003אחד עשר\u0004 — \u0003ש\u0004כן \u0003ראוי\u0004 יום זה לשמש \u0003לספירת\u0004 שבעת ימי נקיות של הרואה ביום הרביעי שלאחר תקופת ימי נדות, שכן למדו מהכתוב \u0003\"או כי תזוב\"\u0004 שאף הרואה ביום הרביעי שלאחר תקופת ימי נדות באה לכלל זבה, ומעתה למדנו גם לעניינו של היום האחד עשר שלאחר תקופת ימי נדות, שראוי לספירה. \u0003ומוציא אני\u0004 מכלל דין זבה את הרואה ביום \u0003שנים עשר\u0004 — \u0003ש\u0004כן \u0003אין ראוי\u0004 יום זה \u0003לספירת\u0004 שבעת ימי נקיים של זוב הנלמדים מהכתוב \u0003\"או כי תזוב\".\u0004 וממשיכים בבירור דינה של האשה הנטמאת בראייתה: \u0003ואין לי\u0004 שנטמאת \u0003אלא\u0004 זו הרואה \u0003שלשה ימים,\u0004 ואולם זו הרואה \u0003שני ימים מנין\u0004 לי שאף היא טמאה — לכך \u0003תלמוד לומר\u0004 \"כל ימי זוב טומאתה כימי נדתה תהיה טמאה היא\", \u0003\"ימי\"\u0004 — שאף הרואה שני ימים בלבד טמאה. וממשיכים ומבררים: והרואה \u0003יום אחד\u0004 בלבד, \u0003מנין\u0004 לי שאף היא נטמאת — לכך \u0003תלמוד לומר \"כל ימי\",\u0004 ללמדנו שהריהי טמאה אף בראיית יום אחד. ועוד בדרשת כתוב זה: נאמר בו \"טמאה היא\", והכתוב \u0003\"טמאה\" מלמד ש\u0004הרואה יום אחד בלבד, \u0003מטמאה את בועלה כנדה.\u0004 והכתוב \u0003\"היא\"\u0004 מלמד: דווקא \u0003היא מטמאה את בועלה, ואין הזב מטמא מה שהוא בועל.\u0004 שהיה מקום לומר שיטמא הזב את מה שהוא בועל, \u0003והלא דין\u0004 (קל וחומר) \u0003הוא,\u0004 ובאופן זה: \u0003ומה היא\u0004 הזבה, שהריהי קלה בדינה, \u0003ש\u0004כן \u0003אינה מטמאה ב\u0004שלוש \u0003ראיות\u0004 בלבד (אם ראתה את כולן ביום אחד) להיחשב על ידן כזבה, \u0003כבימים,\u0004 שהריהי נעשית זבה רק בראיה שראתה בשלושה ימים נפרדים — ובכל זאת הריהי \u0003מטמאה את בועלה.\u0004 \u0003הוא\u0004 (הזב), החמור בדינו, \u0003ש\u0004כן \u0003מטמא ב\u0004שלוש \u0003ראיות\u0004 שראה, אף שראה את כולן ביום אחד, \u0003כ\u0004דרך שהוא מטמא בראיות שראה \u0003בימים\u0004 נפרדים — \u0003אינו דין ש\u0004יהא אף הוא \u0003מטמא\u0004 את מה שהוא בועל! לכך \u0003תלמוד לומר \"היא\"\u0004 — דווקא \u0003היא מטמאה את בועלה, ואין הזב מטמא מה שהוא בועל.\u0004 וממשיכים בבירור דיניה של הזבה, \u0003ומנין\u0004 לנו \u0003שהוא\u0004 (שהיא) \u0003עושה משכב ומושב\u0004 — לכך \u0003תלמוד לומר\u0004 \u0003\"כמשכב נדתה\".\u0004 \u0003ו\u0004דנים בהלכה זו: \u0003אין לי\u0004 שהריהי עושה משכב ומושב \u0003אלא\u0004 בזו שראתה \u0003שלשה ימים,\u0004 שהריהי זבה גמורה (\"זבה גדולה\"), ואולם בזו שראתה \u0003שני ימים מנין\u0004 לי שכך הוא — לכך \u0003תלמוד לומר \"ימי\".\u0004 וזו שראתה \u0003יום אחד מנין\u0004 לי שכך הוא — \u0003תלמוד לומר\u0004 \u0003\"כל ימי\".\u0004 \u0003ו\u0004מבררים עתה את דינה של הרואה יום אחד בתקופת ימי זיבתה, שהיא \"שומרת יום כנגד יום\", \u0003מנין\u0004 לי \u0003ש\u0004הריהי \u0003סופרת\u0004 יום \u0003אחד ל\u0004ראייה של יום \u0003אחד\u0004 — \u0003תלמוד לומר \"יהיה לה\".\u0004 ושואלים: \u0003יכול\u0004 יהא הדין ש\u0003תספור שבעה\u0004 ימים \u0003ל\u0004ראייה של \u0003שנים\u0004 ימים, ולא יומיים בלבד. שכן יש מקום לומר כהלכה זו, \u0003ו\u0004הלא \u0003דין\u0004 (קל וחומר), \u0003הוא,\u0004 ובאופן זה: \u0003ומה הוא\u0004 (הזב), שקל בדינו \u0003ש\u0004הרי \u0003אין סופר אחד לאחד\u0004 — בכל זאת הריהו \u0003סופר שבעה\u0004 ימים נקיים \u0003לשנים\u0004 ראיות. \u0003היא\u0004 (הזבה), שחמורה בדינה, \u0003ש\u0004הרי היא \u0003סופרת אחד לאחד\u0004 — \u0003אינו דין שתספור שבעה\u0004 נקיים \u0003לשנים?\u0004 לכך \u0003תלמוד לומר\u0004 \u0003\"יהיה לה\"\u0004 — להורות שהיא \u0003אינה סופרת אלא יומה.\u0004 ומסכמים את השאלה: \u0003אלמא קראי נינהו\u0004 \u0005[הרי איפוא מקראות הן]\u0006 כל הלכותיה של תקופת אחד עשרה הימים הללו, ושלא כדברי ר' אלעזר בן עזריה! ומשיבים: \u0003ל\u0004שיטת \u0003ר' עקיבא\u0004 — אכן כל ההלכות הללו נלמדות מ\u0003קראי\u0004 \u0005[מקראות],\u0006 ואולם \u0003ל\u0004שיטת \u0003ר' אלעזר בן עזריה\u0004 — \u0003הלכתא\u0004 \u0005[הלכות\u0006 למשה מסיני\u0005]\u0006 הן. ומתוך שהובאו דרשות הלכותיה של הזבה מן הכתוב \"ואשה כי יזוב זוב דמה ימים רבים\", ובכללן, דין תקופת ימי זיבה הבאה בסמוך לתום תקופת ימי נדות, מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמעיה לר' אבא\u0004 בשאלה: מאחר ואחז הכתוב בלשון \"ימים\", מעתה \u0003אימא\u0004 \u0005[אמור]\u0006 כי הרואה \u0003ביממא\u0004 \u0005[ביום]\u0006 — \u0003תהוי\u0004 \u0005[תהא]\u0006 \u0003זבה,\u0004 והרואה \u0003בליליא\u0004 \u0005[בלילה]\u0006 — \u0003תהוי\u0004 \u0005[תהא]\u0006 \u0003נדה! אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא לרב שמעיה בתשובה: \u0003עלך\u0004 \u0005[עליך],\u0006 כנגד החושב כך, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בהמשך דבריו \"או כי תזוב \u0003על נדתה\"\u0004 — להורות: \u0003סמוך ל\u0004תקופת \u0003נדתה.\u0004 ומעתה נשאל: הזמן המוגדר כ\u0003סמוך לנדתה אימת הוי\u0004 \u0005[מתי הוא]?\u0006 — \u0003בליליא\u0004 \u0005[בלילה],\u0006 \u0003וקא קרי\u0004 \u0005[והוא\u0006 הכתוב \u0005קורא]\u0006 \u0003לה זבה.\u0004 וחותמים את המסכת בדבר אגדה, ממה ש\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003אליהו: כל השונה הלכות בכל יום\u0004 — \u0003מובטח לו שהוא בן העולם הבא, ש\u0004כן \u0003נאמר \"הליכות עולם לו\"\u0004 (חבקוק ג, ו), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"הליכות\" אלא הלכות,\u0004 וללמדנו שכל השונה הלכות (\"הליכות\"), נוחל עולם הבא (\"עולם לו\").",""]]};
